window.__Q=window.__Q||{};window.__Q["tcm/8/A1"]=[{"q":"左心衰竭最早出现的表现是","o":["心源性哮喘","端坐呼吸","劳力性呼吸困难","咳粉红色泡沫痰","夜间阵发性呼吸困难"],"a":2,"e":"左心衰竭使左室舒张末压升高，肺毛细血管楔压上升，活动时回心血量增加、肺淤血加重，故劳力性呼吸困难最先出现。端坐呼吸和夜间阵发性呼吸困难是肺淤血进一步加重后平卧时的表现，出现较晚；心源性哮喘为夜间阵发性呼吸困难伴支气管痉挛；粉红色泡沫痰提示急性肺水肿，属重症晚期表现"},{"q":"流行性出血热的最基本病变是","o":["右心房心内膜下弥漫出血","脑实质灶性出血坏死","全身广泛性小血管损害","腹膜后疏松结缔组织水肿如胶冻样","垂体前叶出血坏死"],"a":2,"e":"流行性出血热由汉坦病毒引起，病毒直接损伤内皮细胞并诱发免疫损伤，导致全身广泛小血管扩张、通透性增高和出血，这是各器官病变的基础。右心房心内膜下弥漫出血、垂体前叶出血坏死、腹膜后胶冻样水肿均为小血管损害在特定部位的表现，而非基本病变；脑实质灶性出血坏死也只是其继发改变"},{"q":"应激是指机体受到内外环境刺激所出现的","o":["微循环障碍","非特异性全身性反应","肾素-血管紧张素系统活性增高","继发性甲状旁腺功能亢进","失控的全身炎症反应"],"a":1,"e":"应激是机体受到创伤、感染、精神刺激等各类应激原作用时产生的非特异性全身性反应，以神经内分泌激活和代谢改变为核心，与刺激性质无关。微循环障碍是休克时的表现，肾素-血管紧张素系统活性增高仅为应激中部分内分泌改变；失控的全身炎症反应见于脓毒症，继发性甲状旁腺功能亢进则属慢性肾病并发症，均不能概括应激本质"},{"q":"风湿性心内膜炎急性期所形成的疣状赘生物常见于","o":["二尖瓣的心室面","二尖瓣的闭锁缘","二尖瓣的腱索处","二尖瓣的乳头肌处","左室乳头肌腱索附着处"],"a":1,"e":"风湿性心内膜炎急性期瓣膜表面形成白色血栓性赘生物，好发于二尖瓣闭锁缘，因该处内皮易受血流冲击损伤，赘生物细小、单行排列、不易脱落。二尖瓣心室面、腱索及乳头肌处并非典型好发部位；左室乳头肌腱索附着处更是感染性心内膜炎赘生物常见部位，与风湿性赘生物部位不同"},{"q":"大肠癌的好发部位中最多见的是","o":["直肠","乙状结肠","盲肠及升结肠","横结肠","降结肠"],"a":0,"e":"大肠癌可发生于各段结肠，但直肠最为多见，其次为乙状结肠，两者合计占绝大多数，这与粪便停留时间长、黏膜长期受刺激有关。盲肠及升结肠、横结肠、降结肠发病率依次降低。乙状结肠虽常见但少于直肠，故该项并非最多见部位，其余各段结肠更少"},{"q":"病毒性肺炎的炎症性质常为","o":["肺大叶实变性炎症","肺小叶实变性炎症","肺间质性炎症","肺泡性炎症","胸膜性炎症"],"a":2,"e":"病毒性肺炎的病变主要在肺间质，表现为支气管壁、细支气管壁及肺泡间隔充血水肿和淋巴细胞、单核细胞浸润，肺泡腔内渗出少，故属肺间质性炎症。大叶性肺炎、小叶性肺炎及肺泡性炎症以肺泡腔内渗出为主，属细菌性肺炎常见类型；胸膜性炎症病变以胸膜为主，均不同于病毒性肺炎"},{"q":"下列属于核受体的是","o":["胰高血糖素受体","肾上腺素受体","胰岛素受体","糖皮质激素受体","乙酰胆碱受体"],"a":3,"e":"糖皮质激素受体位于胞浆和细胞核内，激素与受体结合后直接进入核内调控基因转录，属核受体超家族。胰高血糖素受体、肾上腺素受体和乙酰胆碱受体均为膜表面G蛋白偶联受体；胰岛素受体虽为跨膜酶联受体，也不在细胞内，均与核受体定位不同"},{"q":"高钾血症时心电图的特征性变化主要是","o":["P波压低","QRS波群增宽","Q-T间期延长","P-R间期延长","T波高耸"],"a":4,"e":"高钾血症时细胞外钾升高使心肌细胞静息电位上移、3相复极加快，T波高尖、基底变窄，这是最早且特征性的心电图改变，严重时才出现QRS增宽。Q-T间期延长多见于低钙血症，P-R间期延长和P波压低并非高钾特征，QRS增宽是重度中毒表现而非早期特征性变化"},{"q":"局部不含肉芽组织的病变是","o":["结核空洞","脓肿壁","化生病灶","动脉粥样硬化","心肌梗死灶"],"a":2,"e":"化生病灶是上皮组织化生后形成的良性改变，属于适应性反应，局部无肉芽组织长入。结核空洞壁由肉芽组织、干酪样物质构成，脓肿壁为肉芽组织包裹形成，心肌梗死灶由肉芽组织机化修复，动脉粥样硬化斑块内亦有肉芽组织长入，这些病变局部均含肉芽组织"},{"q":"急性重度高钾血症时，心肌电生理特性表现为","o":["兴奋性降低，传导性降低，自律性升高，收缩性升高","兴奋性升高，传导性降低，自律性升高，收缩性降低","兴奋性降低，传导性降低，自律性降低，收缩性降低","兴奋性降低，传导性升高，自律性升高，收缩性升高","兴奋性升高，传导性升高，自律性降低，收缩性升高"],"a":2,"e":"急性重度高钾血症时，静息电位显著上移使快钠通道失活，兴奋性、传导性、自律性和收缩性全面降低，严重时心肌停搏于舒张期。A、B、E项所述兴奋性升高仅见于轻度高钾，重度时钠通道失活而兴奋性降低；D项称传导性与收缩性升高，与重度高钾的全面抑制相悖"},{"q":"良性高血压的基本病变是","o":["细动脉玻璃样变","大、中动脉粥瘤","小动脉纤维素样坏死","动脉中层黏液变性","动脉中层钙化"],"a":0,"e":"良性高血压的基本病变是全身细动脉硬化，表现为细动脉壁玻璃样变，血浆蛋白渗入内皮下并沉积，使管壁增厚变硬、管腔狭窄。大、中动脉粥瘤是动脉粥样硬化的病变；小动脉纤维素样坏死见于恶性高血压；动脉中层黏液变性和钙化分别为Marfan综合征及老年性动脉硬化表现，均非良性高血压基本病变"},{"q":"呼吸衰竭时最常发生的酸碱平衡紊乱是","o":["代谢性酸中毒","呼吸性酸中毒","代谢性碱中毒","呼吸性碱中毒","混合性酸碱平衡紊乱"],"a":4,"e":"呼吸衰竭时缺氧和二氧化碳潴留常同时存在，二氧化碳潴留致呼吸性酸中毒，缺氧又使无氧酵解增强、乳酸堆积引起代谢性酸中毒，故最常见的是混合性酸碱平衡紊乱。单纯呼吸性酸中毒或代谢性酸中毒仅见于单一因素，呼吸性碱中毒与代谢性碱中毒在呼衰中少见"},{"q":"下列细胞中属于稳定细胞的是","o":["皮肤表皮","心肌细胞","肾小管上皮细胞","淋巴造血细胞","胃黏膜细胞"],"a":2,"e":"稳定细胞在生理状态下增殖缓慢，但受损伤刺激后可迅速进入分裂周期参与修复，肾小管上皮细胞、肝细胞等属此类。皮肤表皮和胃黏膜上皮为持续更新的不稳定细胞；心肌细胞为永久细胞，损伤后不能再生；淋巴造血细胞同属不稳定细胞，均非稳定细胞"},{"q":"结核结节的组成不包括","o":["中性粒细胞","淋巴细胞","成纤维细胞","上皮样细胞","朗汉斯巨细胞"],"a":0,"e":"结核结节由上皮样细胞、朗汉斯巨细胞、淋巴细胞和成纤维细胞构成，是肉芽肿性炎的典型结构，中性粒细胞不参与其组成。中性粒细胞主要见于急性化脓性炎；成纤维细胞、上皮样细胞和朗汉斯巨细胞均为结节必备成分，分别承担纤维包裹、吞噬和免疫呈递作用"},{"q":"系统性红斑狼疮可检测到“狼疮带”的部位是","o":["真皮与表皮交界处","关节囊","心脏瓣膜形成的赘生物","肾小球基底膜","小动脉壁"],"a":0,"e":"狼疮带是指系统性红斑狼疮患者真皮与表皮交界处免疫球蛋白和补体沉积形成的荧光带，由自身抗体攻击基底膜所致，具诊断价值。关节囊病变表现为滑膜炎；赘生物为Libman-Sacks心内膜炎表现；肾小球基底膜病变是狼疮性肾炎，小动脉壁纤维素样坏死为血管炎改变，均不形成狼疮带"},{"q":"在应激时合成增多的激素中，与应激镇痛有关的是","o":["β－内啡肽","内皮素","心钠素","心房钠尿肽","前列腺素"],"a":0,"e":"β－内啡肽是应激时下丘脑-垂体释放的内源性阿片肽，作用于中枢阿片受体产生镇痛效应，与应激镇痛直接相关。内皮素为强烈缩血管肽，心钠素和心房钠尿肽实为同类利钠利尿激素，前列腺素参与炎症和血管调节，均无应激镇痛作用"},{"q":"干酪样坏死属于","o":["纤维素样坏死","凝固性坏死","坏疽","液化性坏死","脂肪坏死"],"a":1,"e":"干酪样坏死是结核病的特征性病变，坏死组织彻底崩解呈无结构红染颗粒状，因含脂质较多而呈黄色奶酪样，本质属凝固性坏死的特殊类型。纤维素样坏死为免疫性血管病和风湿病的表现；坏疽是大块坏死合并腐败菌感染；液化性坏死见于脑梗死和脓肿；脂肪坏死为酶解性坏死，均不同"},{"q":"胶质瘤中最常见的类型","o":["星形细胞瘤","少突胶质细胞瘤","室管膜瘤","神经鞘瘤","神经纤维瘤"],"a":0,"e":"星形细胞瘤是胶质瘤中发病率最高的类型，起源于星形胶质细胞，浸润性生长，按分化程度分级。少突胶质细胞瘤和室管膜瘤较少见；神经鞘瘤和神经纤维瘤起源于神经鞘膜细胞，属周围神经肿瘤而非胶质瘤，均非最常见类型"},{"q":"心肌肌节的最适初长度是","o":["1、8μm","2、0μm","2、2μm","2、4μm","2、6μm"],"a":2,"e":"心肌肌节最适初长度约为2.2μm，此时粗细肌丝重叠最佳，横桥有效结合数目最多，收缩产生的张力最大，符合Starling定律。2.0μm时肌丝重叠未达最佳；2.4μm及2.6μm时细肌丝被拉出粗肌丝重叠区，收缩力下降；1.8μm过短则细肌丝相互重叠干扰收缩"},{"q":"肝硬化时蜘蛛痣形成的主要原因是","o":["侧支循环形成","凝血因子合成减少","血管内压增高","低蛋白血症","雌激素增多"],"a":4,"e":"肝硬化时肝细胞对雌激素的灭活能力下降，体内雌激素蓄积，引起小动脉末梢扩张，形成蜘蛛痣和肝掌。侧支循环形成是门脉高压结果，表现为食管胃底静脉曲张；凝血因子合成减少致出血倾向；低蛋白血症致水肿腹水；血管内压增高并非蜘蛛痣成因"},{"q":"低张性缺氧时，细胞发生缺氧的机制是","o":["毛细血管血量减少","血氧容量降低","毛细血管平均氧分压降低","静脉氧分压降低","组织利用氧障碍"],"a":2,"e":"低张性缺氧由吸入气氧分压低、外呼吸障碍等引起，动脉血氧分压降低，导致毛细血管平均氧分压下降，细胞获氧不足。血氧容量降低是血液性缺氧的特点；毛细血管血量减少属循环性缺氧；组织利用氧障碍为组织性缺氧，如氰化物中毒；静脉氧分压降低是结果而非缺氧机制"},{"q":"急性弥漫性增生性肾小球肾炎的主要临床表现是","o":["肾病综合征","急性肾炎综合征","慢性肾炎综合征","无症状血尿、蛋白尿","快速进行性肾炎综合征"],"a":1,"e":"急性弥漫性增生性肾小球肾炎多为链球菌感染后肾小球肾炎，内皮细胞和系膜细胞增生，临床上表现为急性肾炎综合征，以血尿、蛋白尿、水肿和高血压为特征。肾病综合征以大量蛋白尿和低蛋白血症为主，多见于膜性肾病；快速进行性肾炎综合征见新月体性肾炎；慢性肾炎综合征病程迁延"},{"q":"下列有关癌的描述，错误的是","o":["来源于上皮组织","发病率较肉瘤高","肉眼观，质软、细腻、灰红、湿润、鱼肉状","镜下见，癌细胞成巢，实质与间质分界清","早期易发生淋巴道转移"],"a":2,"e":"癌来源于上皮组织，发病率高于肉瘤，镜下癌细胞成巢、实质与间质分界清楚，早期多经淋巴道转移。肉眼观质软、细腻、灰红湿润、呈鱼肉状是肉瘤的大体特点，因肉瘤间质少、血管丰富，故该项描述错误。来源于上皮、发病率较高、成巢分布及淋巴道转移均为癌的正确特征"},{"q":"黄曲霉菌导致肝细胞癌与下列哪项关系密切","o":["多环芳烃在肝脏氧化成环氧化物","异环芳烃在肝脏代谢为环氧化物","葡萄糖苷酸在葡萄糖苷酸水解酶作用下释放出活化的羟胺","亚硝胺被活化释放烷化碳离子","基因组整合到宿主细胞DNA中"],"a":1,"e":"黄曲霉菌产生的黄曲霉毒素属异环芳烃类，其本身需经肝微粒体混合功能氧化酶代谢活化为环氧合物，后者与DNA鸟嘌呤结合引起基因突变，导致肝细胞癌。多环芳烃如苯并芘需经肝氧化活化；葡萄糖苷酸水解释放羟胺、亚硝胺释放烷化碳离子及病毒基因组整合分别是其他致癌物的机制，与黄曲霉毒素无关"},{"q":"慢性风湿性心瓣膜病变的表现不包括","o":["瓣膜增厚变硬","瓣膜短缩","瓣叶间粘连","腱索增粗变短","瓣膜断裂，穿孔"],"a":4,"e":"慢性风湿性心瓣膜病变为机化瘢痕形成过程，表现为瓣膜增厚变硬、短缩、瓣叶间粘连及腱索增粗变短，导致瓣膜狭窄或关闭不全。瓣膜断裂、穿孔是感染性心内膜炎的特点，因细菌毒素破坏瓣膜组织所致，不属于慢性风湿性病变"},{"q":"病毒性肝炎镜下所见嗜酸性小体，其病变属于","o":["细胞凋亡，为单个细胞死亡","细胞变性，为嗜酸性变","细胞坏死","纤维素样坏死","细胞萎缩"],"a":0,"e":"病毒性肝炎时单个肝细胞胞浆水分丢失、嗜酸性增强，核固缩碎裂，最终形成深红染圆形小体即嗜酸性小体，属细胞凋亡，为单个细胞死亡。细胞变性为可逆性损伤，不形成凋亡小体；纤维素样坏死见于免疫性损伤；细胞萎缩为细胞体积缩小，均与嗜酸性小体性质不同"},{"q":"关于炎症的阐述，错误的是","o":["炎症是白细胞吞噬及清除有害因子的反应","炎症是机体对于损伤因子的防御反应","炎症是机体损伤及抗损伤过程","炎症的局部表现为红、肿、热、痛和功能障碍","炎症的全身反应包括发热和白细胞增多等"],"a":0,"e":"炎症是具有血管系统的活体组织对损伤因子的防御反应，本质为损伤与抗损伤的统一过程，局部表现为红肿热痛和功能障碍，全身反应有发热和白细胞增多。把炎症仅定义为白细胞吞噬清除有害因子的反应，忽略了血管反应和组织损伤，概念片面，故该阐述错误"},{"q":"诊断绒毛膜癌最可靠的依据是","o":["侵犯子宫肌层","镜下见水泡状绒毛","阴道不规则出血","病灶呈暗红色，结节状","镜下见异型性明显的细胞滋养层和合体细胞滋养层两种细胞"],"a":4,"e":"绒毛膜癌的诊断依靠镜下见异型性明显的细胞滋养层和合体细胞滋养层两种细胞，且无绒毛结构、无间质血管，这是与葡萄胎鉴别的关键。侵犯肌层、暗红色结节状病灶及阴道出血均可见于侵蚀性葡萄胎；水泡状绒毛是葡萄胎的特征，绒癌中不存在，故镜下双相细胞最可靠"},{"q":"炎症过程中，组织损伤的主要表现是","o":["充血","渗出","变质","增生","播散"],"a":2,"e":"变质是炎症局部组织细胞的变性和坏死，是组织损伤的主要表现，可由致炎因子直接作用或免疫损伤引起。充血和渗出属血管反应，为抗损伤防御环节；增生是修复性改变；播散是炎症扩散后果，均不代表组织损伤本身"},{"q":"合成急性期反应蛋白最主要的细胞是","o":["中性粒细胞","成纤维细胞","血管内皮细胞","单核巨噬细胞","肝细胞"],"a":4,"e":"急性期反应蛋白如C反应蛋白、纤维蛋白原等主要由肝细胞合成，受细胞因子刺激后生成显著增加，是急性期反应的重要介质。中性粒细胞和单核巨噬细胞主要产生细胞因子；成纤维细胞合成胶原等基质蛋白；血管内皮细胞参与炎症黏附和凝血，均非急性期反应蛋白的主要来源"},{"q":"伤寒回肠淋巴滤泡肿胀是因为","o":["淋巴细胞增生","浆细胞增生","肉芽组织增生","巨噬细胞增生","局部水肿"],"a":3,"e":"伤寒由伤寒沙门菌引起，细菌侵入回肠末端集合淋巴小结并在巨噬细胞内繁殖，导致巨噬细胞大量增生形成伤寒肉芽肿，使淋巴滤泡肿胀隆起。淋巴细胞增生见于病毒性感染；浆细胞增生为慢性炎特点；肉芽组织增生属修复过程；局部水肿不能解释滤泡的实质性肿大"},{"q":"青春期前骨骺未闭合，生长素分泌过多可能引起","o":["肢端肥大症","多毛症","巨人症","Simonds综合征","Sheehan综合征"],"a":2,"e":"青春期前骨骺尚未闭合，生长素分泌过多刺激长骨骨骺软骨细胞分裂增殖，使骨骼纵向过度生长，形成巨人症。肢端肥大症见于成年后骨骺闭合者，表现为手足粗大和颅面改变；Simonds综合征为垂体功能减退；Sheehan综合征是产后垂体坏死所致，均与生长素过多无关"},{"q":"下列属于抑癌基因的是","o":["ras","CDK4","bcl-2","p53","L-myc"],"a":3,"e":"p53基因是最常见的抑癌基因，编码转录因子，在DNA损伤时阻滞细胞周期并启动凋亡，防止异常增殖。ras和L-myc为原癌基因，活化后促进增殖；bcl-2抑制凋亡，属癌基因；CDK4为细胞周期蛋白依赖性激酶，过度活化推动细胞增殖，均非抑癌基因"},{"q":"侵袭性葡萄胎与绒毛膜癌的主要区别是前者","o":["可有阴道转移结节","可浸润肌层","细胞异型性明显","有绒毛结构","有出血坏死"],"a":3,"e":"侵袭性葡萄胎与绒毛膜癌的关键鉴别在于有无绒毛结构：前者镜下仍可见水泡状绒毛或绒毛阴影，后者完全无绒毛，仅见两种滋养层细胞异型增生。两者均可侵犯肌层、出现阴道转移结节和出血坏死，细胞异型性在绒癌更明显，但这些均非二者最根本的区别"},{"q":"下列关于暴发型脑炎临床症状的描述，错误的是","o":["脑膜刺激症状严重","多见于儿童","可出现败血症","可出现中毒性休克","可出现沃-弗综合征"],"a":0,"e":"暴发型脑炎以脑实质损害为主，起病急骤、昏迷抽搐明显，而脑膜刺激症状多不严重，这是它与普通型流脑的鉴别点。本病多见于儿童，可伴败血症和中毒性休克，暴发型流脑可出现沃-弗综合征，故其余描述均符合暴发型脑炎特点"},{"q":"下述病理变化中，属于肿瘤组织结构异型性的是","o":["瘤细胞形态大小不一","细胞失去正常的层次与排列","细胞核大小不等","可见病理性核分裂象","细胞核染色深，核膜厚，核胞浆明显"],"a":1,"e":"组织结构异型性指肿瘤组织在空间排列上失去正常层次和极性，如细胞失去正常的层次与排列。瘤细胞形态大小不一、核大小不等、核深染核膜厚及病理性核分裂象均为细胞形态异型性的表现，反映单个细胞的异常，而非组织结构排列紊乱"},{"q":"细菌性痢疾与阿米巴痢疾的鉴别依据是","o":["毒血症的程度","腹痛的部位","X线钡餐灌肠的所见","粪便中检查病原体","粪便性状"],"a":3,"e":"细菌性痢疾与阿米巴痢疾的可靠鉴别是粪便中检查病原体：前者为志贺菌感染，粪便培养阳性；后者可查见溶组织内阿米巴滋养体。两者均有腹痛、黏液血便，粪便性状相似，毒血症程度和腹痛部位差异不具特异性；X线钡餐对肠道感染鉴别价值有限"},{"q":"胃癌最主要的转移途径是","o":["胃内播散","直接蔓延","血道转移","种植性转移","淋巴道转移"],"a":4,"e":"胃癌最主要转移途径为淋巴道转移，癌细胞侵入胃壁淋巴管，先至局部淋巴结，晚期可经胸导管转移至左锁骨上淋巴结。胃内播散和直接蔓延属局部扩散；血道转移多见于晚期；种植性转移可形成卵巢Krukenberg瘤，但均非主要途径"},{"q":"血栓被肉芽组织取代的过程称","o":["肉芽肿形成","血栓机化","血栓再通","血栓软化","血栓吸收"],"a":1,"e":"血栓机化是指血栓形成后由血管壁向血栓内长入肉芽组织，逐渐取代血栓的过程，可使血栓与血管壁粘连。肉芽肿形成是慢性肉芽肿性炎的表现；再通是机化过程中血栓内形成新血管使血流部分恢复；软化和吸收是血栓溶解过程，均非肉芽组织取代"},{"q":"能产生氧自由基的体液性因素是","o":["儿茶酚胺","血管紧张素","血栓素","前列腺素","内皮素"],"a":0,"e":"儿茶酚胺在休克等应激时大量释放，其自氧化及经单胺氧化酶代谢过程可产生氧自由基，是重要的体液性自由基来源。血管紧张素、内皮素主要起缩血管作用；血栓素促进血小板聚集和血管收缩；前列腺素多为舒血管或炎症介质，均不以产生氧自由基为主"},{"q":"严重感染时发生的DIC通常是","o":["急性DIC","亚急性DIC","慢性DIC","代偿型DIC","过度代偿型DIC"],"a":0,"e":"严重感染时细菌毒素及炎症介质大量释放，可迅速激活凝血系统和血小板，导致弥散性微血栓形成，病情急剧，属急性DIC。亚急性和慢性DIC病程较缓，多见于肿瘤、产科等；代偿型和过度代偿型是按代偿程度分类，并非严重感染的典型类型"},{"q":"休克期微循环灌流的特点是","o":["少灌少流、灌少于流","多灌多流、灌多于流","少灌多流、灌少于流","多灌多流、灌少于流","多灌少流、灌多于流"],"a":4,"e":"休克期即微循环淤血期，因酸中毒使毛细血管前括约肌松弛而后阻力血管仍收缩，灌入多而流出少，呈多灌少流、灌多于流，血液淤积。少灌少流、灌少于流是休克早期缺血期的特点；少灌多流和多灌多流的组合不存在于典型休克分期"},{"q":"流行性出血热病理损害最明显的器官是","o":["皮肤","肝","脑","肾","肺"],"a":3,"e":"流行性出血热病毒主要侵犯小血管和肾脏，肾脏病理损害最为明显，表现为肾小管变性坏死、间质出血水肿，临床上出现少尿和蛋白尿。皮肤、肝、脑、肺虽也可受累出血，但病变程度和特异性均不及肾脏"},{"q":"对于微小病变性肾小球病的透射电镜检查，可能出现以下哪种超微结构改变","o":["基底膜分层形成双轨现象","基底膜大量电子致密物沉积","足突广泛融合、变平，甚至消失","内皮下大量电子致密物沉积","系膜区大量电子致密物沉积"],"a":2,"e":"微小病变性肾小球病光镜下肾小球基本正常，电镜特征为脏层上皮细胞足突广泛融合、变平甚至消失，临床表现为肾病综合征。基底膜双轨现象见于膜增生性肾炎；大量电子致密物沉积分别见于膜性肾病、内皮下或系膜区沉积型肾炎，均非本病特点"},{"q":"假性神经递质引起肝性脑病的机制是","o":["与正常神经递质竞争，但其效应远比正常递质为弱","引起血浆氨基酸失衡","干扰脑的能量代谢","使抑制性神经递质增多","干扰脑细胞膜的功能"],"a":0,"e":"假性神经递质如苯乙醇胺、羟苯乙醇胺在肝性脑病时蓄积，其结构与去甲肾上腺素相似，可竞争性占据突触受体，但效能远弱于正常递质，致神经传导障碍。血浆氨基酸失衡和干扰能量代谢是其他学说；抑制性递质增多、干扰脑细胞膜功能并非假性递质的主要机制"},{"q":"典型的结核结节中央可出现","o":["渗出的大量血浆成分","变性、坏死的中性粒细胞","干酪样坏死","纤维素样坏死","抗原抗体复合物"],"a":2,"e":"典型结核结节中央为干酪样坏死，呈红染无结构颗粒状，周围绕以上皮样细胞、朗汉斯巨细胞、淋巴细胞和成纤维细胞。纤维素样坏死见于风湿病和血管炎；渗出的血浆成分和中性粒细胞是急性炎表现；抗原抗体复合物不形成结核结节的中央坏死"},{"q":"治疗肝性脑病时，下列哪项不正确","o":["使用镇静麻醉类药物","口服乳果糖","纠正水电解质紊乱","给予左旋多巴","口服或注射支链氨基酸"],"a":0,"e":"肝性脑病患者中枢神经抑制状态明显，使用镇静麻醉类药物可加重意识障碍甚至诱发昏迷，属禁忌。口服乳果糖可酸化肠道减少氨吸收；纠正水电解质紊乱和给予左旋多巴、支链氨基酸均为合理治疗措施"},{"q":"癌与肉瘤最根本的区别是","o":["异型性","组织来源","分化成熟程度","转移","发病率"],"a":1,"e":"癌与肉瘤最根本的区别是组织来源不同：癌起源于上皮组织，肉瘤起源于间叶组织。异型性、分化程度和转移能力两者均可出现，只是程度或方式不同；发病率虽癌高于肉瘤，但只是数量差异，均非本质区别"},{"q":"目前认为休克的本质是","o":["微循环障碍","血压下降","血管运动中枢麻痹","神经调节障碍","局部体液因子分泌亢进"],"a":0,"e":"休克的本质是各种病因引起的急性微循环障碍，导致组织灌流不足和细胞缺氧，而非单纯血压下降。血管运动中枢麻痹和神经调节障碍只是部分机制；局部体液因子分泌亢进仅参与微循环改变，不能概括休克的本质"},{"q":"动-静脉血氧含量差增大，可见于","o":["低输出量性心力衰竭","慢性阻塞性肺气肿","一氧化碳中毒","氰化物中毒","亚硝酸盐中毒"],"a":0,"e":"低输出量性心力衰竭时心排血量减少，组织为维持代谢需从单位容积血液中摄取更多氧，使静脉血氧含量下降，动-静脉血氧含量差增大。慢性阻塞性肺气肿、一氧化碳中毒、氰化物中毒和亚硝酸盐中毒均为供氧或运氧障碍，动静脉氧差反而缩小"},{"q":"下列对口眼干燥综合征描述不正确的是","o":["是一种自身免疫病","病变主要累及唾液腺和泪腺","部分患者可伴有肾小球肾炎","本病可与其他自身免疫病同时存在","临床以眼干、口干表现为特征"],"a":2,"e":"口眼干燥综合征即干燥综合征，是累及唾液腺和泪腺的自身免疫病，临床以眼干、口干为特征，可与其他自身免疫病并存。其肾脏损害主要为间质性肾炎，而非肾小球肾炎，故该描述不正确；其余各项均为本病特点"},{"q":"关于慢性浅表性胃炎病理变化的描述，错误的是","o":["炎症仅限于黏膜浅层","黏膜充血水肿","病变部位炎症细胞浸润","胃黏膜腺体萎缩","可见点状出血和糜烂"],"a":3,"e":"慢性浅表性胃炎的炎症限于黏膜浅层，表现为黏膜充血水肿、炎症细胞浸润，可见点状出血和糜烂，腺体保持完整。胃黏膜腺体萎缩是慢性萎缩性胃炎的特征，浅表性胃炎不出现腺体萎缩，故该描述错误"},{"q":"下列病理改变中，不属于“变性”范畴的是","o":["混浊肿胀","含铁血黄素沉积","中性脂肪沉积","转移性钙化","细胞核溶解消失"],"a":4,"e":"变性是细胞或细胞间质内出现异常物质或正常物质异常蓄积的可逆性损伤，混浊肿胀、含铁血黄素沉积、中性脂肪沉积和转移性钙化均属此范畴。细胞核溶解消失即核溶解，是细胞坏死的标志性改变，属不可逆损伤，不属于变性"},{"q":"判断细胞凋亡的特征性形态变化","o":["细胞皱缩","胞浆嗜酸性增强","核固缩","凋亡小体","DNA电泳呈梯状条带"],"a":3,"e":"凋亡小体是凋亡细胞裂解形成的膜包裹小体，被邻近细胞吞噬，是判断细胞凋亡的特征性形态学依据。细胞皱缩、胞浆嗜酸性增强、核固缩也可见于凋亡，但并非特异；DNA电泳梯状条带是生化特征，不属形态变化"},{"q":"急性普通型肝炎肝细胞坏死的特点是","o":["点状坏死","碎片状坏死","桥接坏死","亚大块坏死","大块坏死"],"a":0,"e":"急性普通型肝炎以肝细胞广泛变性为主，坏死轻微，表现为散在单个肝细胞坏死即点状坏死。碎片状坏死和桥接坏死见于慢性肝炎；亚大块坏死和大块坏死是重型肝炎的特点，坏死范围远大于点状坏死"},{"q":"我国门脉性肝硬化的常见原因是","o":["慢性酒精中毒","营养缺乏","化学毒物中毒","病毒性肝炎","黄曲霉素中毒"],"a":3,"e":"我国门脉性肝硬化主要由病毒性肝炎引起，尤其乙型和丙型肝炎，肝细胞反复坏死再生并形成假小叶。慢性酒精中毒是欧美国家肝硬化的常见原因；营养缺乏、化学毒物中毒和黄曲霉素中毒在我国并非主要病因"},{"q":"下列肿瘤中，属于神经外胚叶肿瘤的是","o":["血管肉瘤","脂肪肉瘤","恶性黑色素瘤","基底细胞癌","印戒细胞癌"],"a":2,"e":"恶性黑色素瘤起源于神经嵴来源的黑色素细胞，属神经外胚叶肿瘤，多见于皮肤。血管肉瘤和脂肪肉瘤起源于间叶组织；基底细胞癌起源于表皮基底细胞；印戒细胞癌为腺癌特殊类型，均不属神经外胚叶来源"},{"q":"动脉血pH主要取决于血浆中","o":["[HPO42-] / [H2PO4-]","[HCO3-] / [H2CO3]","[Pr-] / [HPr]","[HCO3-]","[H2CO3]"],"a":1,"e":"动脉血pH取决于血浆碳酸氢盐与碳酸的浓度比值，正常约为20:1，即可维持pH在7.35～7.45。磷酸盐缓冲对和血浆蛋白缓冲对在血液中作用次要；单独HCO3-或H2CO3浓度不能决定pH，二者比值才是关键"},{"q":"慢性肾衰竭患者出血倾向的原因主要是","o":["血小板数量减少","血小板功能异常","凝血物质消耗过多","纤溶系统功能亢进","毛细血管壁通透性增加"],"a":1,"e":"慢性肾衰竭时尿毒症毒素蓄积，可抑制血小板黏附和聚集功能，并影响血小板与血管壁相互作用，导致出血倾向，而血小板数量常无明显减少。凝血物质消耗过多见于DIC；纤溶亢进和毛细血管通透性增加不是主要机制"},{"q":"以下为不利于创伤愈合的因素，除了","o":["感染","异物","电离辐射","老年人","局部血液循环良好"],"a":4,"e":"局部血液循环良好可保证氧和营养物质供应、及时清除代谢产物，有利于创伤愈合，故不属于不利因素。感染、异物可引起持续炎症；电离辐射损伤细胞和组织；老年人组织再生能力差，均延缓愈合"},{"q":"白细胞的趋化作用是指","o":["白细胞附壁","白细胞边集","白细胞阿米巴样运动","白细胞向着化学刺激物的部位定向移动","白细胞向着化学刺激物的部位反向移动"],"a":3,"e":"趋化作用是白细胞在趋化因子浓度梯度引导下，朝化学刺激物所在部位作定向移动，是炎症时白细胞到达病灶的关键。白细胞附壁和边集是渗出前的黏附步骤；阿米巴样运动是移动方式但不强调定向；反向移动与趋化方向相反"},{"q":"炎症早期反应中，最先出现的血管变化是","o":["血管扩张","血流缓慢","血流加快","血管收缩","血流停滞"],"a":3,"e":"炎症早期最先出现的血管变化是短暂血管收缩，由神经反射和体液因子引起，持续数秒至数分钟，随后才出现血管扩张和血流加快。血流缓慢和血流停滞是血管扩张后的改变，出现较晚，并非最先出现的血管反应"},{"q":"Krukenberg瘤的本质是","o":["胃癌","肠癌","卵巢癌","肝癌","转移癌"],"a":4,"e":"Krukenberg瘤是胃癌细胞经种植性或血道转移至卵巢形成的转移性黏液腺癌，镜下见印戒细胞，本质为转移癌而非卵巢原发癌。胃癌、肠癌、肝癌可为原发肿瘤，但该瘤特指卵巢的转移性病变，故卵巢癌的表述不准确"},{"q":"下述哪项不属于DIC的常见原因","o":["败血症","严重挤压伤","恶性肿瘤转移","单核吞噬细胞系统功能抑制","羊水栓塞"],"a":3,"e":"单核吞噬细胞系统功能抑制使激活的凝血因子清除减少，是DIC发生的诱因而非常见病因。败血症、严重挤压伤、恶性肿瘤转移和羊水栓塞均可直接释放促凝物质或激活凝血系统，是DIC的常见原因"},{"q":"肾小球肾炎的炎症性质多为","o":["变质性炎","浆液性炎","纤维素性炎","化脓性炎","增生性炎"],"a":4,"e":"肾小球肾炎主要由免疫复合物沉积激活补体，引起肾小球内细胞增生和炎症细胞浸润，炎症性质以增生性炎为主。变质性炎以变性坏死为主；浆液性炎和纤维素性炎以渗出为主；化脓性炎以中性粒细胞渗出和脓形成为特点，均非肾炎主要性质"},{"q":"低渗性脱水又称为","o":["低容量性高钠血症","低容量性低钠血症","高容量性低钠血症","高容量性高钠血症","等容量性低钠血症"],"a":1,"e":"低渗性脱水时失钠多于失水，血清钠低于正常、血浆渗透压降低，同时体液总量减少，故又称低容量性低钠血症。低容量性高钠血症是高渗性脱水；高容量性低钠血症为水中毒；等容量性低钠血症见于ADH分泌异常，均与之不同"},{"q":"以下是绝大多数良性肿瘤的特征，除了","o":["生长速度慢","浸润性生长","有包膜","一般不转移","很少复发"],"a":1,"e":"绝大多数良性肿瘤生长缓慢、有包膜、边界清楚、一般不转移且很少复发。浸润性生长是恶性肿瘤的特征，良性肿瘤多呈膨胀性或外生性生长，故该项不属于良性肿瘤特征；其余各项均为良性肿瘤的常见表现"},{"q":"急性肾盂肾炎上行性感染的特点不包括","o":["可累及单侧肾脏或两侧肾脏","伴有菌血症或败血症","尿路梗阻是重要诱因","细菌可沿输尿管周围淋巴管上行","致病菌主要为革兰阴性杆菌"],"a":1,"e":"急性肾盂肾炎上行性感染是细菌经尿道、膀胱沿输尿管上行至肾盂，尿路梗阻是重要诱因，致病菌多为革兰阴性杆菌，可累及单侧或双侧肾脏，细菌亦可沿输尿管周围淋巴管上行。菌血症或败血症是血源性感染的特点，不属于上行性感染"},{"q":"以下哪项不是纤维素性炎的好发部位","o":["心包","皮肤","胸膜","气管","结肠"],"a":1,"e":"纤维素性炎以纤维蛋白原渗出为主，好发于黏膜、浆膜和肺，如心包的绒毛心、胸膜的纤维素性炎、气管白喉及结肠菌痢假膜。皮肤不是纤维素性炎的好发部位，其炎症多表现为化脓性炎或浆液性炎，故皮肤为相应选项"},{"q":"下列各项中，不属于低镁血症对机体的影响是","o":["神经肌肉的应激性增高","可出现焦虑、反应过激等症状","可引起心律失常","可拮抗儿茶酚胺的缩血管作用","可致低钙血症和低钾血症"],"a":3,"e":"低镁血症使神经肌肉应激性增高，可出现焦虑、反应过激，并因心肌兴奋性改变引起心律失常，还可导致低钙血症和低钾血症。拮抗儿茶酚胺缩血管作用是高镁血症的表现，镁离子可舒张血管，低镁时不出现该效应"},{"q":"下列哪种类型缺氧不属于等张性缺氧","o":["贫血性缺氧","Hb与氧亲和力异常增高的Hb病","CO中毒性缺氧","高铁血红蛋白血症引起的缺氧","淤血性缺氧"],"a":4,"e":"等张性缺氧即血液性缺氧，因血红蛋白数量或性质改变致血氧容量降低，见于贫血、CO中毒、高铁血红蛋白血症及Hb与氧亲和力异常增高的血红蛋白病。淤血性缺氧属循环性缺氧，由血流淤滞、组织灌流减少引起，不属等张性缺氧"},{"q":"交界性肿瘤是","o":["混合性肿瘤","介于肿瘤与非肿瘤之间的肿块组织","癌前病变","组织形态和生物学行为介于良、恶性肿瘤之间的肿瘤","分化好的恶性肿瘤"],"a":3,"e":"交界性肿瘤的组织形态和生物学行为介于良性与恶性之间，低度恶性，生长缓慢，转移晚，如卵巢黏液性囊腺瘤。混合性肿瘤是含多种组织成分；癌前病变尚非癌；分化好的恶性肿瘤仍为恶性，均不符合交界性肿瘤定义"},{"q":"下列关于肿瘤的认识正确是","o":["肿瘤一定会形成肿块","有肿块就一定是肿瘤","肿瘤是机体细胞异常增殖所形成的新生物","肿瘤就是癌症","肿瘤性增殖是多克隆的"],"a":2,"e":"肿瘤是机体细胞在致瘤因素作用下异常增殖形成的新生物，其增殖自主、与机体不协调。肿瘤不一定形成肿块如白血病；有肿块也可是炎症或增生；肿瘤不等于癌症，癌症仅指恶性上皮性肿瘤；肿瘤性增殖为单克隆性，而非多克隆"},{"q":"血管内皮细胞受损引起DIC,与下述哪项无关","o":["激活内源性凝血系统","红细胞释放ADP","激活外源性凝血系统","激活血小板","激活激肽系统"],"a":1,"e":"血管内皮细胞受损后内皮下胶原暴露激活内源性凝血系统，释放组织因子激活外源性凝血系统，同时激活血小板和激肽系统，共同促发DIC。红细胞释放ADP主要促进血小板聚集，并非内皮损伤直接引起DIC的机制，与内皮受损无直接关联"},{"q":"炎症早期阶段，首先从血管内游出的白细胞是","o":["中性粒细胞","单核细胞","淋巴细胞","浆细胞","嗜酸性粒细胞"],"a":0,"e":"急性炎症早期首先从血管内游出的是中性粒细胞，因其数量多、运动活跃、对趋化因子反应快，是急性化脓性炎的主要细胞。单核细胞出现较晚并分化为巨噬细胞；淋巴细胞和浆细胞多见于慢性炎和病毒性感染；嗜酸性粒细胞见于过敏和寄生虫感染"},{"q":"慢性萎缩性胃炎的镜下特点不包括","o":["固有腺体萎缩，数目减少","固有腺体积变小，不发生囊性扩张","腺上皮可发生肠上皮化生","腺上皮可发生假幽门腺化生","黏膜层可有淋巴滤泡形成"],"a":1,"e":"慢性萎缩性胃炎镜下见固有腺体萎缩、数目减少、体积变小，常伴囊性扩张，可见肠上皮化生、假幽门腺化生及淋巴滤泡形成。腺体不发生囊性扩张的描述与萎缩性胃炎的病理特点不符，故不属于其镜下特点"},{"q":"中毒型细菌性痢疾最主要的临床特点是","o":["常发生于老年人和小儿","常由毒力较强的志贺氏菌引起","临床无明显的腹泻和脓血便","不出现滤泡性肠炎的变化","容易转化为慢性细菌性痢疾"],"a":2,"e":"中毒型细菌性痢疾多见于儿童，由毒力较强菌株引起，全身中毒症状重，可出现中毒性休克，但肠道病变轻，临床上无明显腹泻和脓血便，甚至尚无肠道症状即出现休克。本病易发生滤泡性肠炎且很少转为慢性"},{"q":"下列哪项不属于Alzheimer病变特点","o":["神经斑，多见于海马、杏仁核和新皮质","神经原纤维缠结","颗粒空泡变性","Hirano小体","Lewy小体"],"a":4,"e":"Alzheimer病的典型病变包括神经斑、神经原纤维缠结、颗粒空泡变性及Hirano小体，主要累及海马、杏仁核和新皮质。Lewy小体是帕金森病的特征性包涵体，也见于Lewy体痴呆，不属于Alzheimer病的病变特点"},{"q":"好发于卵巢的腺瘤类型为","o":["管状腺瘤","绒毛状腺瘤","囊腺瘤","纤维腺瘤","多形性腺瘤"],"a":2,"e":"囊腺瘤是腺上皮形成的囊状腺瘤，好发于卵巢，如浆液性囊腺瘤和黏液性囊腺瘤。管状腺瘤和绒毛状腺瘤多见于大肠；纤维腺瘤好发于乳腺；多形性腺瘤常见于唾液腺，均非卵巢好发类型"},{"q":"引起成人肾病综合征最常见的原发性肾小球肾炎类型是","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病","微小病变性肾小球病","膜性肾小球病"],"a":4,"e":"成人肾病综合征最常见的原发性肾小球肾炎是膜性肾小球病，表现为基底膜增厚和上皮下电子致密物沉积，临床以大量蛋白尿、低蛋白血症、水肿和高脂血症为特点。微小病变性多见于儿童；新月体性肾炎表现为快速进行性肾炎；IgA肾病以血尿为主"},{"q":"下列关于肝脂肪变的描述，正确的是","o":["肝淤血时，脂肪变首先发生在小叶周围","磷中毒时，脂肪变主要发生在小叶中央区","轻度肝脂肪变时，肉眼下肝可无明显改变","重度肝脂肪变时，肝脏体积缩小","脂肪变的肝细胞的胞浆疏松，呈空网状"],"a":2,"e":"轻度肝脂肪变时肝细胞内脂滴细小、数量少，肉眼观肝脏可无明显改变，需镜下或特殊染色确认。重度脂肪变时肝脏体积增大、色黄、切面油腻而非缩小；脂肪变胞浆内为脂滴，胞浆疏松呈空网状是细胞水肿的表现"},{"q":"分化好的鳞状细胞癌，镜下常可见到","o":["印戒细胞","“鲱鱼骨”样细胞","黏液池","角化珠","裂隙状血管腔"],"a":3,"e":"分化好的鳞状细胞癌保留了鳞状上皮的分化特点，镜下可见角化珠和细胞间桥，是其特征性表现。印戒细胞和黏液池见于黏液腺癌；“鲱鱼骨”样细胞排列是乳腺癌特点；裂隙状血管腔见于血管肉瘤，均非鳞癌所见"},{"q":"下列关于大叶性肺炎的描述，正确的是","o":["多发生于青壮年男性","常并发肺褐色硬化","病变多见于左肺上叶","外周血白细胞降低","可导致支气管扩张"],"a":0,"e":"大叶性肺炎由肺炎链球菌引起，多见于青壮年男性，因受寒、疲劳等诱因发病，病变累及整个肺叶。肺褐色硬化是慢性肺淤血的表现；病变并非仅好发于左肺上叶；患者白细胞升高而非降低；支气管扩张不是其并发症"},{"q":"家族性肾性尿崩症是由于","o":["腺垂体合成和分泌ADH过多","基因突变使腺苷酸环化酶含量减少","ADHV2受体的酶活性降低","ADHV2受体数目减少或功能缺陷","ADHV2受体减敏"],"a":3,"e":"家族性肾性尿崩症为X连锁遗传，因基因突变导致ADH的V2受体数目减少或功能缺陷，肾脏对ADH不反应，不能浓缩尿液。ADH由下丘脑合成而非腺垂体分泌过多；腺苷酸环化酶含量减少、V2受体酶活性降低及受体减敏均非本病根本机制"},{"q":"由于肾、输尿管结石导致肾盂积水，引起肾萎缩，属于","o":["压迫性萎缩","去神经性萎缩","营养不良性萎缩","内分泌性萎缩","失用性萎缩"],"a":0,"e":"肾、输尿管结石阻塞尿路引起肾盂积水，积液压迫肾实质使肾小管萎缩、肾小球纤维化，属压迫性萎缩。去神经性萎缩因神经损伤；营养不良性萎缩因缺血缺氧；内分泌性萎缩因激素缺乏；失用性萎缩因长期不用，均与本例机制不同"},{"q":"下列属于假膜性炎的疾病是","o":["肠伤寒","肠结核","肠阿米巴病","急性细菌性痢疾","肠血吸虫病"],"a":3,"e":"假膜性炎是黏膜的纤维素性炎，急性细菌性痢疾由志贺菌引起，结肠黏膜表面形成由纤维素、坏死组织和中性粒细胞组成的假膜，属典型假膜性炎。肠伤寒为增生性炎；肠结核为肉芽肿性炎；肠阿米巴病为变质性炎；肠血吸虫病为虫卵肉芽肿"},{"q":"肺腺癌常见特点为","o":["患者女性多见，多为周围型，易发生淋巴道转移","患者男性多见，多为中央型，易发生淋巴道转移","患者女性多见，多为中央型，易发生血道转移","患者女性多见，多为周围型，易发生血道转移","患者男性多见，多为周围型，易发生血道转移"],"a":3,"e":"肺腺癌多见于女性，多发生于周边部，早期易侵犯胸膜和发生血道转移。肺鳞癌多为男性中央型，以淋巴道转移为主；中央型腺癌和女性中央型伴血道转移的组合均不符合腺癌常见特点，男性周围型亦非其典型表现"},{"q":"动脉血pH降低，血浆H2CO3浓度原发性升高见于","o":["AG正常型代谢性酸中毒","AG增高型代谢性酸中毒","呼吸性酸中毒","呼吸性碱中毒","代谢性碱中毒"],"a":2,"e":"呼吸性酸中毒由肺通气不足致二氧化碳排出障碍，血浆H2CO3浓度原发性升高，pH降低。代谢性酸中毒的原发改变是HCO3-减少，AG正常型伴血氯升高，AG增高型血氯正常；呼吸性碱中毒和代谢性碱中毒均使pH升高，与题干不符"},{"q":"可形成苏木素小体的疾病是","o":["风湿病","硬皮病","系统性红斑狼疮","系统性硬化","包涵体肌炎"],"a":2,"e":"苏木素小体是系统性红斑狼疮的特征性病变，由抗核抗体攻击细胞核，使细胞出现均质红染的苏木素样小体，常见于肾小球和血液。风湿病形成Aschoff小体；硬皮病和系统性硬化以胶原纤维增生硬化为主；包涵体肌炎以肌纤维内包涵体为特点"},{"q":"二尖瓣关闭不全时心脏的改变不包括","o":["左心室肥大，扩张","右心室肥大，扩张","左心房肥大，扩张","右心房肥大，扩张","升主动脉结扩张"],"a":4,"e":"二尖瓣关闭不全时收缩期血液反流至左房，引起左房肥大扩张，舒张期容量负荷增加致左室肥大扩张，后期肺动脉高压使右室、右房肥大扩张。升主动脉结扩张是主动脉瓣关闭不全或主动脉硬化的表现，非二尖瓣关闭不全的改变"},{"q":"膜性肾小球病的主要临床表现是","o":["肾病综合征","急性肾炎综合征","慢性肾炎综合征","无症状血尿、蛋白尿","快速进行性肾炎综合征"],"a":0,"e":"膜性肾小球病以肾小球基底膜弥漫性增厚和上皮下电子致密物沉积为特征，临床主要表现为肾病综合征，成人和儿童均可发病。急性肾炎综合征多见于链球菌感染后肾炎；快速进行性肾炎综合征见新月体性肾炎；无症状血尿蛋白尿常见于IgA肾病"},{"q":"慢性支气管炎产生大量黏液痰的组织学基础是","o":["黏液渗出","炎性渗出液","黏膜上皮纤毛粘连、倒伏、脱落","黏液腺增生、肥大，黏液腺化生","黏膜上皮鳞状上皮化生"],"a":3,"e":"慢性支气管炎长期刺激使支气管腺体增生、肥大，黏液腺化生，分泌亢进，产生大量黏液痰，这是其组织学基础。黏液渗出和炎性渗出液量有限；纤毛粘连倒伏脱落影响排痰但不直接生痰；鳞状上皮化生是黏膜修复改变，均非大量黏液痰的主因"},{"q":"关于酒精性肝炎的病理变化，错误的是","o":["肝细胞脂肪变性","肝细胞大片坏死","肝细胞内出现Mellory小体","汇管区炎症细胞浸润","纤维组织增生"],"a":1,"e":"酒精性肝炎表现为肝细胞脂肪变性、肝细胞内Mallory小体形成、汇管区炎症细胞浸润和纤维组织增生。肝细胞大片坏死是重型病毒性肝炎的特征，酒精性肝炎一般无大片坏死，故该项描述错误"},{"q":"再灌注时自由基抑制蛋白质功能的主要环节是","o":["抑制磷酸化","氧化巯基","抑制蛋白质合成","增加蛋白质分解","促进蛋白质糖基化"],"a":1,"e":"再灌注产生的氧自由基极易攻击蛋白质的巯基，使其氧化形成二硫键，导致酶失活和膜蛋白功能障碍，这是自由基抑制蛋白质功能的主要环节。抑制磷酸化或蛋白质合成、增加分解及促进糖基化均非氧自由基损伤蛋白质的主要方式"},{"q":"毛细血管外增生性肾小球肾炎最显著的组织学特点是","o":["新月体形成","肾小动脉壁显著增厚","基底膜增厚","入球小动脉纤维素样坏死","内皮细胞和系膜细胞增生"],"a":0,"e":"毛细血管外增生性肾小球肾炎即新月体性肾炎，最显著的组织学特点是肾小囊壁层上皮细胞增生形成新月体，可导致快速进行性肾衰竭。内皮和系膜细胞增生见于急性弥漫性增生性肾炎；基底膜增厚见于膜性肾病；入球小动脉纤维素样坏死见于恶性高血压"},{"q":"胃溃疡的肉眼特点不包括","o":["溃疡通常只有一个","直径多在2cm以上","圆形或椭圆形","边缘整齐，状如刀切","可深达肌层甚至浆膜层"],"a":1,"e":"胃溃疡肉眼多为单个圆形或椭圆形溃疡，直径通常小于2cm，边缘整齐如刀切，可深达肌层甚至浆膜层。直径多在2cm以上并非胃溃疡特点，巨大溃疡需警惕恶变，故该项不属于胃溃疡的肉眼特征"},{"q":"下列不良生活方式中与食管癌关系密切的是","o":["吸烟","高脂肪、高蛋白、低纤维素的饮食习惯","睡眠不足","不安全的性行为","肥胖"],"a":0,"e":"吸烟是食管癌明确的危险因素，烟草中的亚硝胺等多环芳烃类物质长期刺激食管黏膜，促进癌变。高脂肪高蛋白低纤维饮食主要与结直肠癌相关；睡眠不足、不安全性行为及肥胖与食管癌关系远不如吸烟密切"},{"q":"血液自心腔或血管内溢出，进入器官、组织间隙或体腔称为","o":["破裂性出血","漏出性出血","生理性出血","内出血","外出血"],"a":3,"e":"血液自心腔或血管溢出进入器官、组织间隙或体腔称为内出血，血液未排出体外。破裂性出血和漏出性出血是按发生机制分类；生理性出血如月经；外出血指血液流出体外，均与题干所述部位不符"},{"q":"肛门周围深部脓肿可发生","o":["空洞","溃疡","炎性息肉","瘘管","糜烂"],"a":3,"e":"肛门周围深部脓肿破溃后，若一端通向肛管或直肠、另一端开口于皮肤，形成贯通两个上皮表面的病理性管道，即瘘管。空洞是坏死组织液化排出后的空腔；溃疡为表面缺损；炎性息肉为黏膜增生；糜烂为浅表缺损，均不同"},{"q":"下列各项中，可引起脑内出血的是","o":["高渗性脱水","水中毒","高钾血症","低渗性脱水","等渗性脱水"],"a":0,"e":"高渗性脱水时细胞外液渗透压升高，脑细胞脱水皱缩，颅内血管扩张充血，加之脑组织收缩牵拉血管，可引起脑内出血。水中毒致脑细胞水肿；低渗性和等渗性脱水主要引起循环障碍；高钾血症影响心肌电活动，均非脑出血原因"},{"q":"低钙血症对机体的影响不包括","o":["骨质钙化障碍","心肌兴奋性和传导性升高","神经肌肉兴奋性增高","心肌收缩性增强","婴幼儿免疫力低下"],"a":3,"e":"低钙血症时神经肌肉兴奋性增高，心肌兴奋性和传导性升高，但钙离子内流减少使心肌收缩性减弱而非增强；低钙还影响骨质钙化，婴幼儿可免疫力低下。心肌收缩性增强与低钙的生理作用相悖，故不属于其影响"},{"q":"代谢性酸中毒时过度通气可引起","o":["水肿","水中毒","低渗性脱水","等渗性脱水","高渗性脱水"],"a":4,"e":"代谢性酸中毒时呼吸深快过度通气，经肺排出的水分明显增多，若补水不足可导致高渗性脱水。水肿和水中毒为水过多；低渗性脱水失钠多于失水；等渗性脱水水钠等比例丢失，均与呼吸性失水机制不符"},{"q":"发热时，患者消化系统的改变是","o":["胃肠蠕动增强","食欲旺盛","便秘和腹胀","消化液分泌增加","消化酶活性增强"],"a":2,"e":"发热时交感神经兴奋、消化液分泌减少、消化酶活性降低，胃肠蠕动减弱，加之水分蒸发增多，患者常出现食欲减退、便秘和腹胀。胃肠蠕动增强、食欲旺盛、消化液分泌及消化酶活性增加均与发热时的消化系统改变相反"},{"q":"恶性高血压病肾脏的特征性病变是","o":["肾小球纤维化","肾细动脉壁纤维素样坏死","肾小叶间动脉内膜增厚","肾小球毛细血管内血栓形成","肾小管上皮变性"],"a":1,"e":"恶性高血压病起病急，特征性病变为肾细动脉壁纤维素样坏死，管壁增厚、管腔狭窄，可致肾缺血和肾功能衰竭。肾小球纤维化是慢性肾小球肾炎结局；小叶间动脉内膜增厚见于良性高血压；肾小球毛细血管血栓和肾小管变性均非特征"},{"q":"AG升高见于","o":["高血氯性代谢性酸中毒","正常血氯性代谢性酸中毒","代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒"],"a":1,"e":"AG升高即阴离子间隙增高，见于正常血氯性代谢性酸中毒，因未测定阴离子如乳酸、酮体等增多。高血氯性代谢性酸中毒AG正常；代谢性碱中毒AG正常或轻度升高；呼吸性酸中毒和呼吸性碱中毒以H2CO3原发改变为主，AG无明显升高"},{"q":"血栓的结局不包括","o":["溶解、吸收","钙化","机化","再通","梗死"],"a":4,"e":"血栓的结局包括溶解吸收、机化、再通和钙化，小血栓可被完全溶解吸收，较大血栓由肉芽组织机化。梗死是血管阻塞后局部组织缺血坏死，是血栓形成导致的后果而非血栓本身的结局，故不属于血栓结局"},{"q":"以下哪种病因不会导致呼吸性碱中毒","o":["呼吸肌麻痹","癔症发作","高热","甲状腺功能亢进","严重呕吐"],"a":4,"e":"严重呕吐使胃液大量丢失，氢离子和氯离子丧失，血浆HCO3-相对增多，引起代谢性碱中毒，而非呼吸性碱中毒。癔症发作、高热和甲状腺功能亢进均致通气过度，呼吸肌麻痹早期也可因过度通气出现呼碱，均可引起呼吸性碱中毒"},{"q":"梅毒引起的心血管病变主要见于","o":["主动脉","冠状动脉","肺动脉","颈总动脉","肾动脉"],"a":0,"e":"梅毒引起的心血管病变主要累及主动脉，特别是升主动脉和主动脉弓，表现为梅毒性主动脉炎，可致主动脉瓣关闭不全和主动脉瘤。冠状动脉、肺动脉、颈总动脉和肾动脉虽可受累，但病变远不如主动脉常见和典型"},{"q":"细胞坏死特征性的改变是","o":["胞质浓缩","胞质少、胞膜厚","胞质浓缩、胞膜厚","核固缩、核碎裂、核溶解","核固缩、胞质固缩和细胞膜皱缩"],"a":3,"e":"细胞坏死的特征性改变是核固缩、核碎裂和核溶解，是细胞不可逆损伤的形态标志。胞质浓缩、胞膜皱缩及核固缩同时存在更常见于凋亡；胞质少、胞膜厚也非坏死特征，坏死以核的变化最具诊断意义"},{"q":"不符合风湿性心脏病病理变化的描述是","o":["胶原纤维纤维素样坏死","心肌间质Aschoff小体形成","结缔组织基质黏液样变性","心外膜纤维素渗出","心肌间质中性粒细胞渗出"],"a":4,"e":"风湿性心脏病的基本病变为胶原纤维纤维素样坏死、结缔组织基质黏液样变性、心肌间质Aschoff小体形成及心外膜纤维素渗出。心肌间质炎症以淋巴细胞和浆细胞为主，中性粒细胞渗出是化脓性炎的特点，不符合风湿性心脏病"},{"q":"肾细胞癌的典型临床表现是","o":["尿频、尿急、尿痛","无痛性血尿、腰痛、肾区肿块","腹水","高血压","蛋白尿、血尿"],"a":1,"e":"肾细胞癌典型表现为无痛性血尿、腰痛和肾区肿块三联征，因肿瘤侵犯肾盂肾盏和肾包膜所致。尿频尿急尿痛为尿路感染表现；腹水和高血压非典型症状；蛋白尿血尿缺乏特异性，均非肾癌典型表现"},{"q":"引起肝性脑病的神经毒质，除氨和假性神经递质外还有","o":["蛋氨酸","色氨酸","酪氨酸","谷氨酰胺","硫醇、短链脂肪酸"],"a":4,"e":"肝性脑病的神经毒质除氨和假性神经递质外，还包括硫醇和短链脂肪酸，它们可抑制神经细胞膜Na+-K+-ATP酶，干扰神经传导。蛋氨酸、色氨酸、酪氨酸是氨基酸前体；谷氨酰胺是氨的转运形式，均非直接神经毒质"},{"q":"关于脑动脉粥样硬化的后果，错误的是","o":["可引起动脉瘤形成","可继发脑血栓形成","可诱发脑肿瘤","可引起脑萎缩","可引起脑出血"],"a":2,"e":"脑动脉粥样硬化可致血管狭窄闭塞引起脑萎缩和脑梗死，可继发血栓形成，管壁薄弱处可形成动脉瘤并破裂出血。动脉粥样硬化与脑肿瘤发生无直接因果关系，故可诱发脑肿瘤的选项错误"},{"q":"高原居民对缺氧的代偿主要是通过","o":["心跳加快","肺血管收缩","呼吸加深加快","组织利用氧能力增强","血红蛋白氧离曲线右移"],"a":3,"e":"高原居民长期处于低氧环境，主要依靠组织利用氧能力增强、毛细血管密度增加及血红蛋白增多等慢性代偿适应缺氧。心跳加快和呼吸加深加快是急性缺氧的代偿反应；肺血管收缩属急性期改变；氧离曲线右移利于释氧但非主要方式"},{"q":"肝功能不全患者，出现少尿、无尿、氮质血症，其发生机制与下列哪项无关","o":["肾小球滤过率降低","肾小管重吸收增加","肾动脉收缩","肾小球肾炎","RAS系统激活"],"a":3,"e":"肝功能不全时少尿、无尿和氮质血症即肝肾综合征，机制包括肾动脉收缩、肾血流量减少、肾小球滤过率降低、肾小管重吸收增加及RAS系统激活。肾小球肾炎是独立的肾脏原发疾病，与肝功能不全所致肾功能改变无关"},{"q":"下列不属于脂肪变的是","o":["肝细胞内出现大小不等的脂滴","骨骼肌细胞内出现大小不等的脂滴","心肌细胞内出现大小不等的脂滴","脂肪肉瘤细胞内出现大小不等的脂滴","近曲小管上皮细胞内出现大小不等的脂滴"],"a":3,"e":"脂肪变指非脂肪细胞内出现异常脂滴，常见于肝、心、骨骼肌和肾小管上皮细胞等实质细胞。脂肪肉瘤细胞本身即为脂肪来源的肿瘤细胞，其胞浆脂滴属肿瘤性分化，不属于细胞变性意义上的脂肪变"},{"q":"假膜性炎指的是","o":["浆膜的纤维素性炎","黏膜的纤维素性炎","浆膜的浆液性炎","黏膜的浆液性炎","肺的纤维素性炎"],"a":1,"e":"假膜性炎指发生于黏膜的纤维素性炎，纤维素、坏死组织和中性粒细胞在黏膜表面形成假膜，如菌痢和气管白喉。浆膜的纤维素性炎为绒毛心；浆膜和黏膜的浆液性炎以浆液渗出为主；肺的纤维素性炎是大叶性肺炎"},{"q":"血吸虫虫卵主要沉积的部位是","o":["肝脏、回肠","肝脏、盲肠、升结肠","肝脏、横结肠","肝脏、降结肠","肝脏、乙状结肠及直肠"],"a":4,"e":"血吸虫虫卵主要沉积于肝脏和肠壁，尤以乙状结肠及直肠为著，因成虫寄生于肠系膜下静脉，虫卵顺血流沉积于肝，逆血流沉积于肠壁。回肠、盲肠升结肠、横结肠和降结肠均非虫卵主要沉积部位"},{"q":"休克时细胞首先发生损伤的部位为","o":["生物膜","微丝","微管","核仁","染色质"],"a":0,"e":"休克时最先受损的是细胞膜，缺氧和能量不足使膜离子泵功能障碍、膜通透性增高，细胞肿胀，进而细胞器损伤。微丝、微管和染色质改变较晚；核仁是核内结构，其损伤不是休克细胞损伤的起始部位"},{"q":"反映血液酸碱度的指标是","o":["pH","AG","SB","AB","BE"],"a":0,"e":"pH是反映血液酸碱度的直接指标，表示氢离子浓度的负对数，动脉血正常维持在7.35～7.45。AG用于判断代谢性酸中毒类型；SB和AB为碳酸氢盐指标，反映代谢因素；BE为碱剩余，亦属代谢性指标，均非酸碱度本身"},{"q":"全脑功能不可逆的永久性丧失称为","o":["植物人状态","频死状态","脑死亡","生物学死亡","临床死亡"],"a":2,"e":"脑死亡指包括大脑、小脑和脑干在内的全脑功能不可逆的永久性停止，是判定死亡的科学标准。植物人状态仅大脑皮质功能丧失而脑干功能尚存，非全脑；濒死状态脑功能尚未完全停止且可逆；临床死亡以心跳、呼吸停止为标志，脑功能未必丧失；生物学死亡是脑死亡后器官代谢相继停止的终末阶段"},{"q":"原发性高血压的心脏向心性肥大具有以下特点，除外","o":["左心室腔不扩张，反而缩小","左心室壁增厚度可达1、5～2、0cm","心脏重量增加","心脏外观体积明显增大","左心室乳头肌及肉柱增粗"],"a":3,"e":"向心性肥大由长期压力负荷引起，左心室壁增厚可达1.5～2.0cm，乳头肌与肉柱增粗，心脏重量增加，但心腔不扩张反而缩小，故外观体积增大并不明显，此为错误描述。腔缩小、室壁增厚数值、重量增加、肉柱增粗均为其真实特点，须与离心性肥大的心腔扩张相区别"},{"q":"急性重型肝炎的发病机制可能是","o":["免疫功能缺失","免疫功能低下","免疫功能过强，感染病毒多且毒力强","免疫功能正常，感染病毒数量较少、毒力较弱","免疫耐受"],"a":2,"e":"急性重型肝炎系机体免疫反应过强，短时间内感染大量毒力强的肝炎病毒，致肝细胞广泛坏死。免疫功能低下或缺失、免疫耐受时病毒持续存在但肝细胞损伤轻，多呈慢性迁延或携带状态；免疫功能正常、病毒量少毒力弱者多表现为急性普通型肝炎，病程自限"},{"q":"急性肾衰竭发生的中心环节是","o":["GFR降低","肾小管损伤","尿路阻塞","肾脏炎症性病变","肾脏内分泌功能改变"],"a":0,"e":"急性肾衰竭各种病因（肾前性、肾性、肾后性）最终均导致肾小球滤过率急剧下降，使代谢废物潴留、水电解质紊乱，故GFR降低是中心环节。肾小管损伤是肾性AKI的重要机制但非各类共同中心；尿路阻塞仅为肾后性病因；肾脏炎症性病变与内分泌改变均非中心环节"},{"q":"大量放腹水后，腹腔细动脉反射性扩张而致的充血称为","o":["生理性充血","静脉性充血","炎性充血","慢性充血","减压后充血"],"a":4,"e":"减压后充血指器官长期受压后压力骤然解除，细动脉反射性扩张所致的充血，大量放腹水后腹腔血管即为典型。生理性充血为生理需要时的充血；炎性充血由炎症介质引起；静脉性充血属淤血，为静脉回流受阻；慢性充血是长期淤血状态，均非压力骤减所致"},{"q":"蜂窝织炎是指","o":["局灶性大量中性粒细胞浸润及组织坏死液化","疏松结缔组织的弥漫性化脓性炎症","体腔大量脓液蓄积","病灶中大量浆液或黏液渗出","纤维素为主的渗出性炎"],"a":1,"e":"蜂窝织炎是疏松结缔组织的弥漫性化脓性炎，多由溶血性链球菌引起，中性粒细胞弥漫浸润，界限不清。局灶性中性粒细胞浸润伴坏死液化是脓肿；体腔大量脓液蓄积为积脓；以纤维素渗出为主属纤维素性炎；浆液或黏液渗出则为浆液性或黏液性炎"},{"q":"慢性阻塞性肺疾病患者，用力呼气时出现小气道闭合是由于","o":["用力呼吸导致呼吸肌疲劳","小气道阻力增加","胸内压增高","等压点移向小气道","肺泡扩张压向小气道"],"a":3,"e":"用力呼气时胸内压升高，气道内压与胸内压相等的等压点若移向小气道，因其缺乏软骨支撑，外部压力超过管内压导致气道闭合。COPD患者小气道阻力增高使等压点上移至无软骨支持的小气道。胸内压增高、肺泡扩张压仅为条件；呼吸肌疲劳、小气道阻力增加是诱因而非直接机制"},{"q":"属于启动型的caspase是","o":["caspase-1","caspase-3","caspase-6","caspase-7","caspase-9"],"a":4,"e":"caspase-9是线粒体凋亡途径的启动型caspase，与Apaf-1、细胞色素c组成凋亡体后被激活，进而激活执行型caspase。caspase-3、6、7为执行型，负责裂解底物；caspase-1主要参与炎症因子成熟，属炎症相关caspase，均非启动型"},{"q":"不属于凝固性坏死的病变是","o":["阿米巴肝脓肿","心肌梗死","淋巴结结核","肾梗死","脾梗死"],"a":0,"e":"阿米巴肝脓肿由溶组织内阿米巴分泌溶组织酶引起，属液化性坏死，形成充满脓液的腔。心肌梗死、肾梗死、脾梗死均为缺血所致凝固性坏死，组织轮廓保留；淋巴结结核为干酪样坏死，属凝固性坏死的特殊类型，故其为唯一非凝固性坏死者"},{"q":"引起心肌损害，导致心肌舒缩功能障碍的直接因素是","o":["动脉瓣膜关闭不全","肺动脉高压","高血压病","心肌炎","甲状腺功能亢进"],"a":3,"e":"心肌炎直接侵犯心肌细胞，引起心肌变性、坏死和间质炎症，直接损害舒缩功能。瓣膜关闭不全、高血压、肺动脉高压均属心脏负荷异常，通过长期压力或容量负荷间接影响心肌；甲亢通过代谢率增高加重心脏负担，均为间接因素，非直接心肌损害"},{"q":"低张性缺氧引起肺通气增加的主要机制是","o":["动脉血氧分压降低，刺激颈动脉窦压力感受器","动脉血氧分压降低，刺激主动脉弓压力感受器","动脉血氧分压降低，刺激颈动脉体和主动脉体化学感受器","动脉血氧分压降低，刺激肺牵张感受器","动脉血氧分压降低，刺激中枢化学感受器"],"a":2,"e":"低张性缺氧时动脉血氧分压降低，刺激颈动脉体和主动脉体化学感受器，反射性兴奋呼吸中枢使肺通气增加。中枢化学感受器对CO2和H+敏感而非低氧；颈动脉窦、主动脉弓为压力感受器，感受血压变化；肺牵张感受器参与呼吸节律调节，均非低氧兴奋呼吸的机制"},{"q":"肿瘤淋巴道转移到达淋巴结时，癌细胞最早出现于淋巴结的","o":["边缘窦","副皮质区","皮质区","淋巴滤泡","被膜"],"a":0,"e":"淋巴道转移的癌细胞随淋巴液首先进入淋巴结的边缘窦（被膜下窦），在此停留增殖，再向皮质、髓质扩散。副皮质区为T细胞区，皮质区含淋巴滤泡，均为后续侵犯部位；被膜为结缔组织包膜，非癌细胞最先定植处"},{"q":"慢性轻度缺氧时，血液红细胞数量和血红蛋白增多的最主要机制是","o":["肝细胞生成促红细胞生成素增多","抑制肝、脾对红细胞的破坏","肾小管旁间质细胞产生促红细胞生成素增多","骨髓对促红细胞生成素敏感性增高","交感神经兴奋，脾等储蓄器官血管收缩"],"a":2,"e":"慢性缺氧刺激肾脏肾小管旁间质细胞分泌促红细胞生成素（EPO）增多，促进骨髓红系增殖，使红细胞和血红蛋白增多。EPO主要由肾产生而非肝细胞；抑制破坏、骨髓敏感性增高、脾血管收缩均非主要机制，属次要或错误归属"},{"q":"以下哪一种休克的始动环节不是血管床容量增加","o":["青霉素过敏所致休克","严重心律失常所致休克","高位脊髓损伤所致休克","肺炎链球菌感染所致休克","脑膜炎奈瑟菌败血症所致休克"],"a":1,"e":"严重心律失常致心输出量急剧减少，属心源性休克，其始动环节是心泵功能障碍而非血管床容量增加。青霉素过敏、肺炎链球菌及脑膜炎奈瑟菌感染所致休克均因血管扩张、血管床容量增加；高位脊髓损伤损伤交感中枢致血管扩张，亦属血管床容量增加"},{"q":"阿米巴痢疾患者粪便性状为","o":["黏液脓血便","黏液稀便","果酱样便","水样便","黄色稀便"],"a":2,"e":"阿米巴痢疾因肠黏膜液化坏死形成烧瓶状溃疡，坏死组织和血液混合排出，呈暗红色果酱样便，伴腥臭。黏液脓血便多为细菌性痢疾；水样便见于霍乱或急性肠炎；黏液稀便、黄色稀便均非阿米巴痢疾特征，鉴别关键在于果酱样外观"},{"q":"再灌注性心律失常最常见的类型","o":["房性心律失常","室性心律失常","房室交界部阻滞","房室传导阻滞","房颤"],"a":1,"e":"再灌注性心律失常以室性心律失常最常见，如室性早搏、室性心动过速甚至室颤，与缺血区心肌电活动不均一、自由基及钙超载有关。房性心律失常、房颤及房室交界部阻滞、房室传导阻滞虽可发生，但远不如室性心律失常多见"},{"q":"急性肾盂肾炎血源性感染的特点不包括","o":["累及单侧肾脏","伴有菌血症或败血症","金黄色葡萄球菌最常见","可发生于感染性心内膜炎患者","在皮质和髓质形成小脓肿"],"a":0,"e":"血源性（下行性）急性肾盂肾炎经血流播散，常累及双侧肾脏，伴菌血症或败血症，金黄色葡萄球菌最常见，可在皮质和髓质形成多发性小脓肿，并可由感染性心内膜炎迁延而来。仅累及单侧肾脏是上行性（尿路）感染的特点，故为不包括项"},{"q":"恶性高血压患者死于尿毒症的主要原因是","o":["肾小管坏死","肾小球纤维化","肾细动脉纤维素样坏死","肾细动脉玻璃样变","肾间质出血"],"a":2,"e":"恶性高血压时肾细动脉发生纤维素样坏死，管腔狭窄闭塞，肾缺血急剧进展，导致肾功能衰竭和尿毒症。肾细动脉玻璃样变是良性高血压的病变；肾小管坏死、肾间质出血非主要致死机制；肾小球纤维化为慢性过程，均非恶性高血压尿毒症的主因"},{"q":"呼吸衰竭病人可出现胃肠黏膜糜烂、坏死、溃疡，其发生机制不包括","o":["胃黏膜屏障作用降低","减弱胃壁细胞碳酸酐酶活性","胃酸分泌增多","使胃壁血管收缩","合并DIC"],"a":1,"e":"呼吸衰竭时缺氧和CO2潴留使胃黏膜屏障受损、胃酸分泌增多、胃壁血管收缩缺血，并可合并DIC，从而发生应激性溃疡。碳酸酐酶参与胃酸分泌，其活性减弱反而减少胃酸，不利于溃疡形成；题干将其列为发生机制，属错误归属"},{"q":"“虎斑心”发生的原因是","o":["心结缔组织玻璃样变","心肌脂肪变","心肌细胞坏死","心肌脂肪浸润","心肌细胞水肿"],"a":1,"e":"虎斑心是心肌脂肪变的表现，脂肪变性的心肌细胞呈黄色条纹，与正常暗红色心肌相间，形似虎斑，多见于严重贫血或缺氧。心肌脂肪浸润是脂肪组织浸入心肌间质，多见于右心室；心肌细胞水肿呈浑浊肿胀；坏死、结缔组织玻璃样变均无虎斑样外观"},{"q":"细胞内液中主要的阳离子是","o":["K+","Na+","Ca2+","Fe2+","Mg2+"],"a":0,"e":"细胞内液主要阳离子为K+，维持细胞内渗透压和静息膜电位，由钠钾泵主动摄入。Na+是细胞外液主要阳离子；Ca2+主要储存于肌浆网和线粒体，胞质浓度极低；Fe2+为血红蛋白组成成分；Mg2+虽为细胞内阳离子但含量远低于K+"},{"q":"Ⅱ型糖尿病早期，胰岛的病变特点是","o":["胰岛内淋巴细胞浸润","胰岛进行性破坏，B细胞减少","胰岛B细胞无明显减少","胰岛纤维化","胰岛变小"],"a":2,"e":"Ⅱ型糖尿病早期以胰岛素抵抗为主，胰岛B细胞数量无明显减少，甚至可代偿性增生，胰岛素水平正常或升高。胰岛内淋巴细胞浸润、进行性破坏致B细胞减少、胰岛变小及纤维化均为Ⅰ型糖尿病自身免疫损伤的特点，与Ⅱ型不同"},{"q":"伤寒时哪个阶段最容易发生肠穿孔","o":["潜伏期","坏死期","溃疡期","髓样肿胀期","愈合期"],"a":2,"e":"伤寒溃疡期，回肠集合淋巴结坏死组织脱落形成溃疡，溃疡深达肌层甚至浆膜层，最易并发肠穿孔和肠出血。髓样肿胀期为增生阶段，坏死期组织尚未脱落，潜伏期无肠道病变，愈合期溃疡已肉芽修复，均不易穿孔"},{"q":"代谢性酸中毒时常因哪种离子改变而引起心律失常","o":["Mg2+","K+","Cl-","HCO3-","Ca2+"],"a":1,"e":"代谢性酸中毒时H+进入细胞，K+移出细胞，加上肾排钾增多，常伴高钾血症，高钾可致心脏传导阻滞和心律失常。Ca2+改变主要影响神经肌肉应激性；Cl-、HCO3-、Mg2+的变化并非代酸引起心律失常的主要离子机制"},{"q":"代偿性酸碱平衡紊乱的特点是","o":["H2CO3降低或升高","H2CO3正常","HCO3-降低或升高","HCO3-正常","HCO3-/H2CO3正常"],"a":4,"e":"代偿性酸碱平衡紊乱中，原发改变后机体通过代偿使HCO3-与H2CO3的比值恢复接近20:1，pH维持在正常范围。若比值不能恢复、pH异常则为失代偿。H2CO3或HCO3-单独升高或降低只是某一指标改变，不能作为代偿的判定标准"},{"q":"下列各项中，可以促使细胞外钾进入细胞内的是","o":["酸中毒","细胞外液渗透压升高","α肾上腺素受体激活","胰岛素","剧烈运动"],"a":3,"e":"胰岛素可激活钠钾泵，促进K+进入细胞，临床用于治疗高钾血症。酸中毒时H+入细胞、K+出细胞；α受体激活、剧烈运动使K+释放；细胞外液渗透压升高引起细胞脱水、K+外移，均使血钾升高而非促其入细胞"},{"q":"最易引起感染性休克的病原微生物是","o":["细菌","病毒","真菌","立克次体","支原体"],"a":0,"e":"细菌尤其是革兰阴性菌最常见，其内毒素可激活凝血、补体和血管活性物质释放，引起血管扩张和微循环障碍，是感染性休克最常见病原体。病毒、真菌、立克次体、支原体所致感染较少并发休克，致病机制与发生率均不及细菌"},{"q":"梅毒时下列哪种细胞会恒定出现","o":["淋巴细胞","巨噬细胞","嗜酸性粒细胞","中性粒细胞","浆细胞"],"a":4,"e":"梅毒的基本病变为闭塞性动脉内膜炎和血管周围炎，病灶内恒定出现大量浆细胞浸润，是其病理特征。淋巴细胞、巨噬细胞虽常见于慢性炎症但非梅毒恒定特征；中性粒细胞多见于急性化脓性炎；嗜酸性粒细胞与过敏或寄生虫感染相关"},{"q":"缺氧时氧离曲线的左移是由于","o":["血液温度的升高","酸中毒","血液CO2分压升高","红细胞内2，3-DPG浓度下降","局部氧分压降低"],"a":3,"e":"2,3-DPG降低使血红蛋白与氧亲和力增高，氧离曲线左移，不利于组织释氧。温度升高、酸中毒（H+升高）、CO2分压升高均使曲线右移，促进释氧；局部氧分压降低不影响曲线位置，只改变氧饱和度，均非左移原因"},{"q":"非肾性代谢性酸中毒时肾脏的主要代偿方式是","o":["泌H+、泌NH4+及重吸收HCO3-增加","泌H+、泌NH4+及重吸收HCO3-减少","泌H+、泌NH4+增加而重吸收HCO3-减少","泌H+、泌NH4+增加而重吸收HCO3-不变","泌H+、泌NH4+不变而重吸收HCO3-增加"],"a":0,"e":"非肾性代谢性酸中毒时肾脏通过增强泌H+、泌NH4+和重吸收HCO3-来补充碱储备，是主要代偿方式。泌酸与重吸收碱方向相反会加重酸中毒；把二者割裂或描述为不变，均不符合肾脏代偿机制"},{"q":"阿米巴痢疾肠道溃疡的特点是","o":["口小底大的烧瓶状溃疡","与肠长轴平行的溃疡","与肠长轴垂直的溃疡","边缘隆起火山口状溃疡","表浅地图状溃疡"],"a":0,"e":"阿米巴滋养体溶解组织形成口小底大的烧瓶状溃疡，溃疡间黏膜相对正常。与肠长轴平行的溃疡见于肠结核；与长轴垂直的环形溃疡见于细菌性痢疾；火山口状溃疡多为肿瘤；表浅地图状溃疡见于急性细菌性痢疾或烧伤"},{"q":"下列哪项不属于引起细胞水肿的常见原因","o":["缺血","营养障碍","缺氧","中毒","感染"],"a":1,"e":"细胞水肿常见于缺氧、缺血、中毒、感染等，因ATP生成减少或膜损伤致钠水潴留。营养障碍主要引起脂肪变、萎缩或营养不良性钙化，并非细胞水肿的常见原因；其余四项均为经典病因，故答案为营养障碍"},{"q":"狂犬病的主要病理变化是","o":["硬脑膜炎","软脑膜炎","急性弥散性脑脊髓膜炎","急性局限性脑实质炎症","急性弥漫性脑实质炎症"],"a":2,"e":"狂犬病病毒主要侵犯中枢神经系统，引起急性弥散性脑脊髓膜炎，血管周围淋巴细胞浸润、神经细胞变性，特征性改变为Negri小体。硬脑膜炎、软脑膜炎局限；急性局限性脑实质炎症或弥漫性脑实质炎症均非其以脑膜受累为主的特点"},{"q":"向心性心肌肥大发生的主要原因是","o":["舒张期心室壁张力持续增加","舒张期心室壁张力持续降低","收缩期心室壁张力持续增加","收缩期心室壁张力持续降低","心肌细胞数量增加"],"a":2,"e":"向心性心肌肥大由长期压力负荷（后负荷）增加引起，收缩期心室壁张力持续增高，促使肌节并联增生、室壁增厚而心腔不扩大。舒张期张力增高属容量负荷，导致离心性肥大；心肌细胞数量增加不是肥大机制，肥大是细胞体积增大"},{"q":"慢性肉芽肿性炎的病灶内增生的细胞是","o":["巨噬细胞","淋巴细胞","浆细胞","中性粒细胞","嗜酸性粒细胞"],"a":0,"e":"慢性肉芽肿性炎以巨噬细胞及其演化的上皮样细胞、多核巨细胞局限性增生形成肉芽肿为特征。淋巴细胞、浆细胞为主要浸润的慢性炎细胞但非肉芽肿特征性增生细胞；中性粒细胞属急性炎；嗜酸性粒细胞见于过敏及寄生虫性肉芽肿"},{"q":"心源性休克发病的中心环节是","o":["心输出量降低","心率过快","回心血量过少","心率紊乱","外周血管阻力过高"],"a":0,"e":"心源性休克因心脏泵功能衰竭，心输出量急剧降低，组织灌流不足，是各类心源性休克的中心环节。心率过快或紊乱、回心血量过少为诱因或具体机制；外周血管阻力过高会增加后负荷，多为代偿表现而非中心环节"},{"q":"诊断恶性肿瘤的依据是","o":["局部淋巴结肿大","消瘦","肿块增大快","组织结构和细胞的异型性明显","局部红、肿、热、痛"],"a":3,"e":"异型性是肿瘤组织与正常组织的差异，包括结构异型和细胞异型，异型性越明显分化越低、恶性度越高，是诊断恶性肿瘤的主要组织学依据。淋巴结肿大可由炎症引起；消瘦、肿块增大快为临床表现非特异性；红肿热痛为炎症表现"},{"q":"下列何者可直接导致迁徙性脓肿","o":["菌血症","毒血症","败血症","脓毒败血症","病毒血症"],"a":3,"e":"脓毒败血症指化脓菌入血并随血流播散，在多器官形成迁徙性（转移性）脓肿。菌血症仅血中有菌未必形成脓肿；毒血症为毒素入血；败血症为细菌入血繁殖但无转移性脓肿；病毒血症与细菌性脓肿无关"},{"q":"以下各项中，最符合转移性肿瘤概念的是","o":["远隔器官发生的另一肿瘤","血道转移的结果","可形成癌脐","与原发瘤属同一种类型","多发肿瘤"],"a":3,"e":"转移性肿瘤是原发瘤细胞经血道、淋巴道或种植播散到远隔部位形成的肿瘤，其组织学类型与原发瘤相同。远隔器官另一肿瘤可为独立原发瘤；血道转移只是途径之一；癌脐为特定转移表现；多发肿瘤可为多中心发生，均非转移的本质特征"},{"q":"关于高血压病引起的器官病变，错误的是","o":["常引起左心肥大","可导致心力衰竭","可引起原发性颗粒性固缩肾","可导致视力减退","常引起下肢坏疽"],"a":4,"e":"高血压主要累及心、脑、肾、眼底，引起左心肥大、心力衰竭、原发性颗粒性固缩肾和视网膜病变致视力减退。下肢坏疽是下肢动脉粥样硬化闭塞或糖尿病足的表现，并非高血压病的常见器官病变，故为错误项"},{"q":"发热患者，体温每升高1℃，基础代谢率提高约","o":["5%","10%","13%","20%","30%"],"a":2,"e":"发热时体温每升高1℃，基础代谢率约提高13%，故发热患者能量消耗显著增加，需注意营养补充。5%、10%数值偏低；20%、30%偏高，均不符合体温与代谢率的经典量化关系。临床对持续发热者应相应增加热量与蛋白质供给，以免消耗过度"},{"q":"下列属于细胞凋亡的现象是","o":["高温引起皮肤的烧伤","毒物中毒引起细胞死亡","人胚胎发育过程中指（趾）间隙的形成，出生后退化。","强酸、强碱引起的细胞损伤","严重缺血时细胞死亡"],"a":2,"e":"细胞凋亡是由基因调控的程序性死亡，胚胎发育中指（趾）间蹼状组织的消失即为典型生理性凋亡。高温烧伤、毒物中毒、强酸强碱损伤及严重缺血所致细胞死亡均为病理性坏死，细胞膜破裂伴炎症反应，与凋亡不同"},{"q":"风湿性心脏病最常受累的瓣膜是","o":["二尖瓣","三尖瓣","主动脉瓣","肺动脉瓣","二尖瓣和主动脉瓣"],"a":0,"e":"风湿性心脏病最常累及二尖瓣，其次为二尖瓣与主动脉瓣联合受累，三尖瓣、肺动脉瓣少见。主动脉瓣单独受累不及二尖瓣常见；联合瓣膜病变虽可发生但并非最常见，其余瓣膜受累频率均远低于二尖瓣，故答案为二尖瓣"},{"q":"失血性休克早期，发生微循环变化最主要的机制为","o":["交感－肾上腺髓质系统兴奋","肾素－血管紧张素系统兴奋","血管加压素的释放","内皮素的释放","血栓素A2的释放"],"a":0,"e":"失血性休克早期，交感-肾上腺髓质系统强烈兴奋，儿茶酚胺大量释放，致微血管收缩、微循环缺血，以保证心脑供血。肾素-血管紧张素、血管加压素、内皮素及血栓素A2亦参与缩血管，但均为次要或继发机制，非最主要"},{"q":"肉眼观察，肉芽组织呈颗粒状是由于","o":["炎症细胞灶状集聚","新生的毛细血管呈团块状","新生的毛细血管呈袢状弯曲状","巨噬细胞的灶状集聚","纤维母细胞形成过多"],"a":2,"e":"肉芽组织肉眼呈颗粒状，是因其表面新生毛细血管呈袢状弯曲、扩张充血，形成颗粒样突起。炎症细胞或巨噬细胞灶状集聚不形成颗粒外观；毛细血管团块状、纤维母细胞过多均非颗粒状外观的成因，颗粒状外观与其丰富的毛细血管袢直接相关"},{"q":"深部脓肿向体表或自然管道穿破，形成只有一个开口的病理性盲管，称为","o":["窦道","溃疡","糜烂","瘘管","穿孔"],"a":0,"e":"窦道是深部脓肿向体表或自然管道穿破形成的仅有一个开口的病理性盲管。瘘管的两端均开口、连接两个腔隙或腔与体表；溃疡为皮肤黏膜表面缺损；糜烂为浅表缺损；穿孔为脏器壁全层破裂，均非单口盲管"},{"q":"动脉粥样硬化引起的常见致死性病变是","o":["心肌梗死","脑出血","夹层动脉瘤","肾梗死","脑梗死"],"a":0,"e":"动脉粥样硬化累及冠状动脉致管腔狭窄或血栓闭塞，引起心肌梗死，是常见致死原因。脑出血多与高血压相关；夹层动脉瘤、肾梗死、脑梗死虽可由动脉粥样硬化引起，但发生率及致死常见度均不及心肌梗死"},{"q":"治疗各型休克的中心环节是","o":["纠正酸中毒","选用血管活性药物","改善微循环，提高组织灌流量","改善细胞代谢","治疗器官功能衰竭"],"a":2,"e":"休克的本质是组织灌流不足，治疗中心环节是改善微循环、提高组织灌流量，恢复细胞氧供。纠正酸中毒、改善细胞代谢、处理器官衰竭为重要辅助措施；血管活性药物需在充分补液基础上使用，均非中心环节"},{"q":"细胞亚致死性损伤的形态学改变称为","o":["坏死","化生","变性","肥大","萎缩"],"a":2,"e":"变性是细胞或细胞间质受损后出现的形态学改变，属亚致死性、可逆性损伤，如细胞水肿、脂肪变等。坏死为细胞死亡的不可逆改变；化生为细胞类型转换；肥大、萎缩为适应性改变，均非亚致死性损伤的形态学表现"},{"q":"导致血吸虫性硬化的是其","o":["虫卵","尾蚴","毛蚴","童虫","成虫"],"a":0,"e":"血吸虫性肝硬化由虫卵沉积于肝内门静脉分支周围，引起肉芽肿和纤维组织增生，形成干线型肝硬化。尾蚴为感染阶段；毛蚴、童虫为发育阶段；成虫主要寄生于门静脉系统，其代谢产物损伤较轻，均非肝硬化的主要致病因素"},{"q":"发生在乙状结肠的肿块，出现以下哪种形状则高度怀疑为癌","o":["绒毛状","乳头状","分叶状","火山口状","息肉状"],"a":3,"e":"火山口状（溃疡型）肿块边缘隆起、中央坏死凹陷，是结肠癌的典型大体形态，中央易出血坏死。绒毛状、乳头状多为良性腺瘤或乳头状瘤；分叶状可为良性肿瘤；息肉状多为炎性或腺瘤性息肉，恶变倾向低"},{"q":"关于高血压病脑出血的描述，错误的是","o":["以基底节区域多见","是致命性的并发症","原因是微小动脉瘤形成、破裂","高血压病程各期均可发生脑出血","豆纹动脉破裂出血较多见"],"a":3,"e":"高血压脑出血多发生于高血压病程较晚阶段，长期血压升高致细小动脉硬化、微小动脉瘤形成破裂所致，早期一般不发生。基底节区（豆纹动脉供血）最常见，属致命并发症，微小动脉瘤破裂为主要原因，其余描述均正确"},{"q":"输入大量库存过久的血液容易引起","o":["高钠血症","低钠血症","高镁血症","低钾血症","高钾血症"],"a":4,"e":"库存过久的血液中红细胞膜Na+-K+泵活性下降，细胞内K+外漏至血浆，大量输入可致高钾血症。库存血抗凝剂枸橼酸盐可引起低钙而非高钠、低钠；镁离子变化不显著；高钾而非低钾为其特点，故大量输注库存血时须监测血钾"},{"q":"下列肿瘤中，属于上皮组织良性肿瘤的是","o":["畸胎瘤","乳头状瘤","血管瘤","骨肉瘤","脂肪瘤"],"a":1,"e":"乳头状瘤起源于被覆上皮，呈外生性生长，属上皮组织良性肿瘤，多见于皮肤、黏膜等被覆上皮部位。畸胎瘤为生殖细胞肿瘤；血管瘤、脂肪瘤为间叶组织良性肿瘤；骨肉瘤为间叶组织恶性肿瘤，均非上皮来源良性肿瘤"},{"q":"冠状动脉粥样硬化最常累及的冠状动脉分支是","o":["左旋支动脉","左前降支动脉","左主干动脉","右主干动脉","右旋支动脉"],"a":1,"e":"冠状动脉粥样硬化最常累及左前降支，其次为右冠状动脉、左旋支，左主干病变相对少见。左前降支供血范围大、血流剪切力特点使其易发生粥样斑块，是前壁心肌梗死最常见的责任血管，故其病变是前壁心梗最常见的解剖学基础"},{"q":"自由基是指","o":["极易起氧化还原反应的原子、原子团和分子","具有单价的原子、原子团和分子","外层电子轨道上具有单个未配对电子的原子、原子团和分子","外层电子轨道上具有已配对电子的原子、原子团和分子","极易被电离的原子、原子团和分子"],"a":2,"e":"自由基是外层电子轨道含单个未配对电子的原子、原子团或分子，化学性质活泼，易引发脂质过氧化损伤。仅具单价、易氧化还原或易电离均非自由基定义；已配对电子则为稳定分子，不具备自由基特性"},{"q":"鼻咽癌最常见的组织学类型是","o":["基底样鳞状细胞癌","角化性鳞状细胞癌","腺癌","分化型非角化性癌","未分化型非角化性癌"],"a":4,"e":"鼻咽癌以未分化型非角化性癌最常见，恶性程度高，对放疗敏感，与EB病毒感染密切相关。分化型非角化性癌次之；角化性鳞状细胞癌、基底样鳞状细胞癌较少见；腺癌在鼻咽部罕见，该型虽恶性度高但因放疗敏感疗效相对较好"},{"q":"人体最重要的散热部位是","o":["皮肤","肺","尿","粪","肌肉"],"a":0,"e":"皮肤是人体最重要的散热部位，主要通过辐射、传导、对流和蒸发方式散热，占总散热量的绝大部分。肺通过呼吸散热有限；尿、粪排出的热量极少；肌肉是主要产热器官而非散热部位，临床物理降温与出汗散热均以皮肤为作用部位"},{"q":"炎症过程中，血管中的白细胞和内皮细胞黏附后，白细胞伸出伪足样突起，以阿米巴运动方式挤出内皮细胞间隙，这种现象称为","o":["白细胞浸润","白细胞边集","白细胞激活","白细胞游出","白细胞趋化"],"a":3,"e":"白细胞游出是白细胞黏附于内皮后以阿米巴运动穿过内皮细胞间隙进入组织的过程。白细胞边集是白细胞靠边流动；浸润是游出后在组织间隙聚集；趋化是定向移动；激活是功能状态改变，均非穿出血管壁的动作本身"},{"q":"下列疾病中，不属于肿瘤的是","o":["淋巴瘤","畸胎瘤","动脉瘤","尤文肉瘤","白血病"],"a":2,"e":"动脉瘤是动脉壁局部扩张或膨出，属血管结构性病变，并非肿瘤，无细胞异常增殖的本质特征。淋巴瘤、尤文肉瘤、白血病为恶性肿瘤，畸胎瘤为生殖细胞肿瘤，虽名称含'瘤'但均属肿瘤范畴，故答案为动脉瘤"},{"q":"有关心肌梗死的叙述，错误的是","o":["多由冠状动脉粥样硬化引起","多发生于冠状动脉前降支供血的区域","多为出血性梗死","可引起心脏破裂","可继发附壁血栓"],"a":2,"e":"心肌梗死属贫血性梗死，因冠状动脉闭塞致心肌缺血坏死，组织缺血、含血量少，故呈灰白色而非出血性。出血性梗死多见于肺、肠等双重血供或淤血器官；心梗多由冠脉粥样硬化引起，好发于前降支供血区，可致心脏破裂和附壁血栓，其余均正确"},{"q":"病理诊断羊水栓塞的依据是","o":["肺泡腔内有水肿液","肺泡腔内有角化上皮、胎毛、胎粪等","肺泡壁毛细血管内有角化上皮、胎毛、胎粪等","肺泡腔内出血","肺泡壁毛细血管内有透明血栓"],"a":2,"e":"羊水栓塞的病理诊断依据是在肺泡壁毛细血管及小动脉内见到角化上皮、胎毛、胎粪等羊水成分，为羊水中的有形成分进入母体血液循环的证据。肺泡腔内水肿液或出血非特异性；透明血栓虽常见但不能确诊；角化上皮若在肺泡腔内则为误吸而非栓塞"},{"q":"非少尿型ARF的临床症状不常见的是","o":["尿量在400ml/天以上","尿比重低，尿钠含量少","高钾血症","代谢性酸中毒","氮质血症"],"a":2,"e":"非少尿型急性肾衰竭尿量在400ml/天以上，但仍存在氮质血症、代谢性酸中毒和尿浓缩功能障碍，尿比重低。高钾血症在少尿型更突出，非少尿型因尿量较多排钾尚可，血钾多正常或轻度升高，故不常见"},{"q":"CRF时发生代谢性酸中毒的相关因素不包括","o":["GFR显著降低","肾小管泌H＋、排NH4+功能降低","肾小管重吸收NaHCO3减少","钠水潴留","机体分解代谢增强"],"a":3,"e":"慢性肾衰竭时代谢性酸中毒与GFR降低致酸性代谢产物潴留、肾小管泌H+排NH4+障碍、重吸收NaHCO3减少及分解代谢增强产酸增多有关。钠水潴留主要引起水肿和高血压，与酸中毒发生无直接关系"},{"q":"炎症反应的中心环节是","o":["白细胞的渗出","血管反应","免疫反应","组织增生","吞噬作用"],"a":1,"e":"炎症反应的中心环节是血管反应，包括血管扩张、血管通透性增加及白细胞渗出，为吞噬和清除病因创造条件。免疫反应参与炎症发生但非中心；白细胞渗出、吞噬是血管反应的后续事件；组织增生属慢性炎症修复表现"},{"q":"判定组织坏死，主要依据为","o":["细胞胞质呈红染，均质状","间质胶原纤维肿胀、断裂","细胞核固缩、核碎裂、核溶解","细胞核异型性","细胞肿胀、胞质疏松"],"a":2,"e":"细胞核的变化是细胞坏死的主要形态学标志，表现为核固缩、核碎裂和核溶解，是不可逆损伤的依据。胞质红染均质、间质胶原肿胀断裂为坏死的伴随改变但不是主要依据；核异型性为肿瘤特征；细胞肿胀疏松属可逆性变性"},{"q":"判断细胞凋亡的特征性生化指标是","o":["细胞皱缩","胞浆嗜酸性增强","核固缩","凋亡小体","DNA电泳呈梯状条带"],"a":4,"e":"凋亡细胞DNA在核小体间被特异性切割，电泳呈现180～200bp整倍体的梯状条带，是凋亡的生化特征。细胞皱缩、胞浆嗜酸性增强、核固缩为形态学改变；凋亡小体为形态学特征，均非生化指标"},{"q":"不符合Ⅰ型糖尿病的病因的描述是","o":["与病毒感染有关","与自身免疫有关","与遗传因素有关","与肥胖有关","针对胰岛B细胞"],"a":3,"e":"Ⅰ型糖尿病是自身免疫性疾病，与遗传、病毒感染及针对胰岛B细胞的自身免疫反应有关，导致B细胞破坏、胰岛素绝对缺乏。肥胖是Ⅱ型糖尿病的重要危险因素，与胰岛素抵抗相关，与Ⅰ型病因无关，二者在病因与发病机制上本质不同"},{"q":"在我国按病因、病变及临床表现进行综合分类，最常见的肝硬化类型是","o":["门脉性肝硬化","坏死后性肝硬化","胆汁性肝硬化","淤血性肝硬化","寄生虫性肝硬化"],"a":0,"e":"我国肝硬化按综合分类以门脉性肝硬化最常见，多由病毒性肝炎、酒精中毒等引起，形成小结节、纤维间隔较窄。坏死后性肝硬化多由重型肝炎或药物中毒所致；胆汁性、淤血性、寄生虫性肝硬化均相对少见"},{"q":"胃癌最常见的好发部位是","o":["贲门","胃窦部大弯侧","胃体前壁","胃窦部小弯侧","胃底部"],"a":3,"e":"胃癌最常见于胃窦部小弯侧，其次为贲门，胃体前壁、胃底等部位较少见。胃窦小弯侧黏膜易受幽门螺杆菌感染、胆汁反流及机械摩擦等因素影响，是溃疡和肠化生的好发区，故为癌变高发部位，贲门与胃体胃底的发病率明显低于胃窦小弯"},{"q":"下述导致水钠潴留的机制中，错误的是","o":["心房钠尿肽增加","滤过分数增加","醛固酮增加","抗利尿激素增加","肾小球滤过率减少"],"a":0,"e":"心房钠尿肽具有利钠、利尿、扩血管作用，可抑制肾小管重吸收钠，增加钠水排出，其增加不会导致水钠潴留。滤过分数增加使近曲小管重吸收钠水增多；醛固酮、抗利尿激素促进钠水重吸收；GFR减少致排泄障碍，均可致潴留"},{"q":"属于变质性炎的病理变化是","o":["心外膜渗出纤维素","表皮内水疱形成","蛛网膜下腔脓液积聚","脑软化灶形成","肝小叶汇管区炎细胞浸润"],"a":3,"e":"变质性炎以组织细胞变性坏死为主，脑软化灶是脑组织缺血或中毒后液化坏死形成的软化灶，属变质性炎。心外膜纤维素渗出为纤维素性炎；表皮水疱为浆液性炎；蛛网膜下腔脓液为化脓性炎；汇管区炎细胞浸润为慢性炎表现"},{"q":"下述结核类型中，不属于继发性结核病的是","o":["局灶型肺结核","急性粟粒型肺结核","浸润型肺结核","慢性纤维空洞型肺结核","结核球"],"a":1,"e":"继发性肺结核包括局灶型、浸润型、慢性纤维空洞型、结核球及干酪性肺炎等，多见于成人，常由原发病灶复燃或外源性再感染引起。急性粟粒型肺结核属血行播散型肺结核，多为原发性结核血行播散所致，故不属于继发性肺结核"},{"q":"患者表现为严重水肿、大量蛋白尿和脂尿、低蛋白血症、高脂血症，患者可能有以下哪种临床综合征","o":["肾炎综合征","肾病综合征","急性肾炎综合征","慢性肾炎综合征","Goodpasture综合征"],"a":1,"e":"肾病综合征以大量蛋白尿、低蛋白血症、严重水肿和高脂血症为特征，伴脂尿。肾炎综合征以血尿、高血压、水肿为主；急性肾炎综合征起病急、血尿明显；慢性肾炎综合征病程迁延；Goodpasture综合征为肺出血肾炎综合征，均不符"},{"q":"急性代谢性碱中毒时可出现","o":["中枢神经系统功能抑制","血浆总钙量降低","神经肌肉应激性增高","高钾血症","血红蛋白氧解离曲线右移"],"a":2,"e":"急性代谢性碱中毒时pH升高，血浆游离钙减少，神经肌肉应激性增高，出现手足抽搐。中枢神经系统功能抑制多见于酸中毒或CO2麻醉；碱中毒时血浆总钙量不变但游离钙降低；常伴低钾而非高钾；氧解离曲线左移而非右移"},{"q":"长期应用大剂量糖皮质激素容易诱发DIC是因为","o":["组织凝血活酶大量入血","血管内皮细胞广泛受损","增加溶酶体膜稳定性","单核吞噬细胞系统功能抑制","肝素的抗凝活性减弱"],"a":3,"e":"长期大剂量糖皮质激素可抑制单核吞噬细胞系统功能，使其清除凝血激活物、纤维蛋白及细胞碎屑的能力下降，血液呈高凝状态而易诱发DIC。糖皮质激素并非通过组织因子大量入血、内皮广泛损伤诱发，稳定溶酶体膜是其抗炎机制，肝素抗凝活性减弱非主要机制"},{"q":"心肌梗死灶的形状常为","o":["楔形","节段形","圆形","不规则形","椎体形"],"a":3,"e":"心肌梗死灶形状多不规则，常呈地图状，其范围与冠状动脉供血区域及侧支循环有关。楔形或椎体形多为肾、脾、肺等器官贫血性或出血性梗死形态；节段形、圆形均不符合心梗灶的形态特点，其不规则外形与冠脉分支供血区分布相一致"},{"q":"细胞外液中主要的阳离子是","o":["K+","Na+","Ca2+","Fe2+","Mg2+"],"a":1,"e":"细胞外液主要阳离子为Na+，是维持细胞外液渗透压和血容量的关键离子，由钠钾泵排出细胞。K+为细胞内液主要阳离子；Ca2+在细胞外液浓度虽高但远低于Na+；Fe2+、Mg2+含量均少，非主要阳离子"},{"q":"急性重型肝炎最主要的死因是","o":["DIC","急性肝衰竭","急性肾衰竭","心功能衰竭","上消化道大出血"],"a":1,"e":"急性重型肝炎肝细胞广泛坏死，导致急性肝衰竭，出现黄疸、出血、肝性脑病、肝肾综合征等，为其最主要死因。上消化道大出血、DIC、急性肾衰竭可为严重并发症或合并症，但多继发于肝衰竭，非首要死因；心功能衰竭与此无关"},{"q":"下述关于良性肿瘤形状及生长特点的描述，正确的是","o":["溃疡状，坏死明显","菜花状浸润性生长","树根状生长向周围组织浸润","结节状膨胀性生长，有完整包膜","蟹足状浸润性生长"],"a":3,"e":"良性肿瘤多呈结节状、膨胀性生长，生长缓慢，边界清楚，常有完整包膜，不侵犯周围组织。溃疡状伴坏死、菜花状、蟹足状、树根状浸润性生长均为恶性肿瘤的生长方式，边界不清、易转移，故不属于良性肿瘤特点"},{"q":"下列哪一项不是代谢性碱中毒的原因","o":["肝性脑病","剧烈呕吐","应用利尿剂","盐皮质激素过多","低钾血症"],"a":0,"e":"代谢性碱中毒常见原因包括剧烈呕吐致胃酸丢失、袢利尿剂使用、盐皮质激素过多及低钾血症等。肝性脑病是肝功能衰竭导致的神经精神障碍，其发生与血氨升高、假性神经递质有关，并非代谢性碱中毒的病因"},{"q":"影响气道阻力最主要的因素是","o":["气道内径","气道长度","气体密度","气流速度","气道形态"],"a":0,"e":"气道阻力与气道半径四次方成反比，气道内径是其最主要的影响因素，气道口径轻度缩小即可使阻力显著增加。气道长度、气体密度、气流速度及气道形态虽影响阻力，但作用远小于内径，临床支气管痉挛或分泌物堵塞均通过缩小口径使阻力骤增"},{"q":"低钾血症患者尿液可表现为","o":["反常性碱性尿","反常性酸性尿","中性尿","正常性酸性尿","正常性碱性尿"],"a":1,"e":"低钾血症时肾小管上皮细胞内K+缺乏，H+-K+交换增强，H+排入尿中增多，使尿液呈酸性，称反常性酸性尿。反常性碱性尿见于高钾血症；中性尿、正常酸性尿或碱性尿均未体现低钾时肾排H+增加的特征"},{"q":"疾病的发展方向取决于","o":["病因的数量与强度","存在的诱因","机体的抵抗力","损伤与抗损伤力量的对比","机体自稳调节的能力"],"a":3,"e":"疾病发展过程中损伤与抗损伤力量始终相互斗争，二者的对比决定疾病向康复或恶化、死亡方向发展。病因的数量与强度、诱因、机体抵抗力和自稳调节能力均只是影响这一对比的具体因素，非决定发展方向的根本"},{"q":"休克微循环缺血期的选择性血管收缩可发生于","o":["心、脑、肾","肝、脑、肠","肺、皮肤、脑","心、肺、肝","皮肤、肾、肠"],"a":4,"e":"休克微循环缺血期，交感-肾上腺髓质兴奋释放大量儿茶酚胺，皮肤、肾、胃肠等器官血管α受体丰富，发生选择性收缩，以保证心脑血液供应。心、脑因α受体少且具自身调节，血流量基本不减，故不属于选择性收缩范围"},{"q":"原癌基因激活可引起","o":["抑制细胞生长","细胞发生恶性转化","促进细胞凋亡","DNA修复功能减弱","失去复制能力"],"a":1,"e":"原癌基因在物理、化学或生物因素作用下被激活（如点突变、扩增、重排），转化为癌基因，使细胞过度增殖、分化异常，发生恶性转化。抑制生长、促进凋亡、DNA修复减弱、失去复制能力均与癌基因激活的作用相反"},{"q":"应用左旋多巴治疗肝性脑病的病理生理学基础是","o":["增加正常神经递质形成","与芳香族氨基酸竟争性进入脑内","促进支链氨基酸通过血脑屏障","对抗氨中毒，改善脑内能量代谢","抑制假性神经递质形成"],"a":0,"e":"左旋多巴可透过血脑屏障，在脑内转化为多巴胺等正常神经递质，补充被假性神经递质取代的递质，恢复神经传导。与芳香族氨基酸竞争入脑、促进支链氨基酸转运为其他疗法机制；左旋多巴并不直接对抗氨中毒或抑制假性递质形成"},{"q":"急性呼吸性酸中毒的代偿主要靠","o":["血液非碳酸氢盐缓冲系统","骨骼的缓冲","肾脏的保碱作用","肺脏的深大呼吸","肾脏的排酸作用"],"a":0,"e":"急性呼吸性酸中毒时CO2潴留迅速，肾脏代偿需数日方起作用，故主要靠血液非碳酸氢盐缓冲系统（血红蛋白、血浆蛋白、磷酸盐）缓冲。骨骼缓冲作用缓慢；肾脏保碱、排酸属慢性代偿；肺脏本身为病因所在，深大呼吸不能纠正通气障碍"},{"q":"肺泡表面活性物质减少可造成","o":["肺泡稳定性增加","肺顺应性增加","肺泡表面张力减少","肺泡扩张的弹性阻力增加","肺泡毛细管血浆外渗减少"],"a":3,"e":"肺泡表面活性物质可降低肺泡表面张力，减少吸气阻力并维持肺泡稳定。其减少时表面张力增大，肺泡扩张的弹性阻力增加，肺顺应性降低，肺泡易萎陷。稳定性增加、表面张力减少、血浆外渗减少均与其减少的效应相反"},{"q":"发热体温上升期循环系统的改变是","o":["交感神经兴奋，心率加快，外周血管收缩，血压上升","交感神经兴奋，心率加快，外周血管舒张，血压下降","迷走神经兴奋，心率减慢，外周血管舒张，血压下降","迷走神经兴奋，心率减慢，外周血管收缩，血压上升","心率、血压无变化"],"a":0,"e":"体温上升期因调定点上移，机体产热增加、散热减少，交感神经兴奋，心率加快，外周血管收缩，血压略升，皮肤苍白、畏寒。外周血管舒张、血压下降见于高热持续期或退热期；迷走神经兴奋、心率减慢不符合体温上升期的表现"},{"q":"在pH7、4的碳酸盐-碳酸缓冲系统中，[HCO3-]/[H2CO3]的比值是","o":["1:20","20：1","1：5","10：1","1：10"],"a":1,"e":"根据Henderson-Hasselbalch方程，血液pH=6.1+lg([HCO3-]/[H2CO3])，pH为7.4时比值为20:1，是维持正常酸碱平衡的关键比值。1:20、1:5、1:10方向颠倒或数值错误；10:1对应pH约7.1，均不符"},{"q":"伤寒杆菌的致病作用主要依赖于","o":["外毒素","内毒素","Vi抗原","“O”抗原","“H”抗原"],"a":1,"e":"伤寒杆菌的致病作用主要依赖内毒素，内毒素可致发热、白细胞减少、中毒性心肌炎及肠壁坏死溃疡等。外毒素并非伤寒杆菌主要致病物质；Vi抗原与菌体'O''H'抗原主要为表面抗原，用于血清学鉴定，非主要致病因子"},{"q":"发热的本质特征是","o":["产热增多","散热减少","产热和散热功能紊乱","支配外周血管的神经障碍","体温调定点上移"],"a":4,"e":"发热是致热原作用下体温调节中枢调定点上移，机体主动调节使产热和散热在高水平达到新平衡，体温升高。产热增多或散热减少仅为体温升高的方式，可见于中暑等；产热散热功能紊乱、外周血管神经障碍均非发热的本质"},{"q":"创伤可引起DIC，其主要机制是","o":["激活凝血因子Ⅻ","组织因子大量释放入血","激发创伤性休克","大量红细胞和血小板受损","激活纤溶系统"],"a":1,"e":"创伤时组织损伤释放大量组织因子（因子Ⅲ）入血，启动外源性凝血途径，引起弥散性血管内凝血。激活凝血因子Ⅻ为内源性途径启动方式，多见于血管内皮损伤；激发休克、血小板和红细胞受损、激活纤溶均非创伤致DIC的主要机制"},{"q":"常发生于较小支气管上皮，且多见于中青年女性的肺癌组织学类型是","o":["细支气管肺泡细胞癌","大细胞癌","小细胞癌","腺癌","鳞癌"],"a":3,"e":"肺腺癌多起源于较小支气管上皮，周围型多见，中青年女性发病率较高，与吸烟关系相对较小。细支气管肺泡细胞癌为腺癌亚型；大细胞癌、小细胞癌多见于男性吸烟者，多为中央型；鳞癌亦以男性吸烟者多见"},{"q":"肾小管重吸收HCO3-并产生NH4+的主要部位在","o":["远曲小管","近曲小管","髓袢升支粗段","髓袢升支细段","集合管"],"a":1,"e":"近曲小管是重吸收HCO3-和生成NH4+的主要部位，谷氨酰胺在此脱氨产生NH4+并泌入管腔，同时重吸收HCO3-。远曲小管和集合管也有泌H+、泌NH4+作用但量少；髓袢升支粗段主要重吸收NaCl，非HCO3-重吸收的主要部位"},{"q":"质地最硬的肿瘤是","o":["血管瘤","平滑肌瘤","骨瘤","脂肪瘤","腺瘤"],"a":2,"e":"骨瘤由成熟骨组织构成，质地坚硬如骨，是质地最硬的肿瘤，多见于颅骨与下颌骨，生长缓慢。血管瘤富含血液、质软；平滑肌瘤、脂肪瘤、腺瘤质地均较软，其中脂肪瘤最软，均远不及骨瘤坚硬，故答案为骨瘤"},{"q":"尿毒症区别于急、慢性肾衰竭的主要改变是","o":["严重氮质血症","肾性高血压","代谢性酸中毒","贫血","自身中毒症状"],"a":4,"e":"尿毒症是肾衰竭晚期，除水电解质紊乱和氮质血症外，出现尿毒素蓄积引起的自身中毒症状，涉及消化、神经、心血管等多系统，是区别于一般急、慢性肾衰竭的主要特点。严重氮质血症、代谢性酸中毒、贫血、肾性高血压在肾衰竭时均可出现，非尿毒症独有"},{"q":"氰化物抑制细胞的生物氧化，使组织利用氧能力减弱的机制是","o":["与氧化型细胞色素氧化酶结合","与还原型细胞色素氧化酶结合","增高线粒体内膜对H+的通透性","抑制ATP合成酶的活性","造成氧化磷酸化脱偶联"],"a":0,"e":"氰化物可与氧化型细胞色素氧化酶（细胞色素aa3）的Fe3+结合，阻断电子传递，使呼吸链中断，组织不能利用氧，形成静脉血性缺氧。与还原型酶结合说法错误；增高内膜H+通透性、抑制ATP合成酶、氧化磷酸化脱偶联均为解偶联剂或寡霉素等的作用机制"},{"q":"下列哪一项不符合创面一期愈合的条件","o":["组织缺损少、创缘整齐","经缝合后创面对合严密","经清创、扩创处理后的创面","无感染","炎症反应轻微"],"a":2,"e":"一期愈合需组织缺损少、创缘整齐、对合严密、无感染、炎症反应轻微，愈合快、瘢痕小。经清创、扩创处理的创面往往组织缺损较多、创缘不整，属二期愈合条件，二期愈合瘢痕大、愈合慢，故不符合一期愈合"},{"q":"肺癌脑转移的途径是","o":["血道转移","直接蔓延","淋巴道转移","种植性转移","医源性转移"],"a":0,"e":"肺癌细胞侵入肺静脉或毛细血管后经血循环到达脑，形成脑转移，血道转移是肺癌脑转移的主要途径。直接蔓延多侵犯邻近胸壁、纵隔；淋巴道转移常至肺门、纵隔淋巴结；种植性转移多见于胸膜腔；医源性转移罕见，均非脑转移途径"},{"q":"有关慢性炎症的描述，错误的是","o":["病程长","起病缓慢","以渗出性病变为主","以巨噬细胞、淋巴细胞浸润为主","可由急性炎症迁延而来，也可隐匿发生"],"a":2,"e":"慢性炎症病程长、起病缓慢，可由急性炎症迁延或隐匿发生，以巨噬细胞、淋巴细胞、浆细胞浸润为主，伴组织增生和修复。以渗出性病变为主是急性炎症的典型特征，属血管反应的表现，故该描述错误"},{"q":"可导致急性肝功能不全的疾病是","o":["肝胆疾患","门脉性肝硬化","肝癌晚期","急性重型肝炎","阿米巴肝损害"],"a":3,"e":"急性重型肝炎起病急骤，肝细胞广泛坏死，短期内发生严重肝功能损害，导致急性肝功能不全，出现黄疸、出血、肝性脑病等。门脉性肝硬化、肝癌晚期、肝胆疾患多致慢性肝功能不全；阿米巴肝损害为局灶性病变，一般不引起急性肝功能不全"},{"q":"关于肿瘤的发病机制，错误的说法是","o":["肿瘤是细胞增殖过度的疾病","肿瘤是细胞凋亡不足的疾病","肿瘤是细胞分化不足的疾病","Bcl-2基因高表达提示肿瘤预后良好","p53基因突变或缺失增加肿瘤发病率"],"a":3,"e":"Bcl-2为抑制凋亡基因，其高表达使肿瘤细胞逃避凋亡、持续存活，常提示肿瘤恶性度高、预后不良，而非预后良好。肿瘤本质为增殖过度、凋亡不足和分化异常；p53基因突变或缺失削弱细胞周期监控和凋亡诱导，增加肿瘤发病率，其余说法正确"},{"q":"当多巴胺在锥体外系被假性神经递质所取代时，患者主要出现哪项临床表现","o":["精神错乱","昏睡","扑翼样震颤","语无伦次","昏迷"],"a":2,"e":"肝性脑病时假性神经递质（苯乙醇胺、羟酪胺）取代锥体外系多巴胺，致神经传导障碍，出现扑翼样震颤。精神错乱、语无伦次、昏睡、昏迷为肝性脑病不同阶段的意识障碍表现，并非假性神经递质取代锥体外系多巴胺的特征性表现"},{"q":"关于反应性淋巴结炎的描述，错误的是","o":["淋巴滤泡数量增多，体积增大，大小不等","生发中心可见大量核分裂象","副皮质区增宽，可见活化的T免疫母细胞","滤泡之间可见正常的淋巴组织","淋巴结反应性增生，淋巴结结构破坏"],"a":4,"e":"反应性淋巴结炎时淋巴滤泡增多增大、大小不等，生发中心核分裂象多见，副皮质区增宽并见活化T免疫母细胞，滤泡间仍见正常淋巴组织，淋巴结基本结构保持完整。故淋巴结结构破坏的说法错误，结构破坏是淋巴结肿瘤性病变的特点"},{"q":"促进细胞凋亡的基因是","o":["Fas","Bcl-2","突变型p53","Bcl-XL","ras"],"a":0,"e":"Fas是死亡受体，与Fas配体结合后激活caspase级联反应，启动外源性凋亡途径。Bcl-2、Bcl-XL为抗凋亡基因，抑制细胞色素c释放；突变型p53多丧失野生型p53的促凋亡功能；ras为原癌基因，主要促进细胞增殖而非凋亡"},{"q":"动脉粥样硬化肉眼可见的最早期病变是","o":["纤维斑块","粥瘤","脂纹","钙化","溃疡形成"],"a":2,"e":"脂纹是动脉粥样硬化肉眼可见的最早病变，表现为动脉内膜黄色斑点或条纹，由泡沫细胞聚集形成，可随年龄增长出现且可逆。纤维斑块为脂纹进一步发展；粥瘤、钙化、溃疡形成均为更晚期病变，出现时间较晚"},{"q":"缺氧是指","o":["低氧血症","血氧分压降低","血氧含量降低","组织氧供减少和/或氧利用障碍","细胞\"窒息\""],"a":3,"e":"缺氧是因氧供减少或组织利用氧障碍，导致组织细胞代谢、功能甚至形态结构异常的过程，涵盖供氧不足与用氧障碍两方面。低氧血症、血氧分压或含量降低仅为低张性等缺氧类型的表现；细胞'窒息'是严重缺氧的后果，均不能概括缺氧的全部内涵"},{"q":"慢性阻塞性肺气肿的病变基础是","o":["细支气管炎及细支气管周围炎","炎症细胞释放水解酶","肺泡壁缺氧","先天性抗弹力酶缺乏","黏膜上皮鳞状上皮化生"],"a":0,"e":"慢性阻塞性肺气肿以细支气管炎及细支气管周围炎为病变基础，炎症致小气道狭窄、阻塞，呼气时气体排出受阻，肺泡内压升高致肺泡壁破坏融合。炎症细胞释放水解酶、肺泡壁缺氧、抗弹力酶缺乏等参与发病但非病变基础；鳞状上皮化生为气道上皮的适应性改变"},{"q":"大叶性肺炎时不会出现的并发症是","o":["肺肉质变","肺褐色硬化","肺脓肿、脓胸","败血症","感染性休克"],"a":1,"e":"肺褐色硬化是慢性肺淤血（如左心衰竭）时肺间质纤维组织增生、含铁血黄素沉积所致，与大叶性肺炎无关，属循环障碍性病变。大叶性肺炎并发肺肉质变（机化）、肺脓肿脓胸、败血症及感染性休克，均为其已知并发症"},{"q":"下列关于乳头状瘤的描述，错误的是","o":["由被覆上皮发生","呈外生性生长","乳头的轴心是肿瘤的间质","恶变后发展为鳞状细胞癌","肿瘤根部可有蒂与正常组织相连"],"a":3,"e":"乳头状瘤由被覆上皮发生，呈外生性生长，乳头轴心为含血管的结缔组织间质，根部常有蒂与正常组织相连。其恶变一般形成相应上皮的癌，如移行上皮乳头状瘤恶变为移行细胞癌，而非鳞状细胞癌，故该描述错误"},{"q":"高镁血症可引起心律失常，主要是通过","o":["兴奋性和传导性降低","兴奋性升高和自律性降低","兴奋性降低和自律性增高","兴奋性和自律性升高","兴奋性和传导性升高"],"a":0,"e":"高镁血症时Mg2+竞争性抑制Ca2+内流，降低心肌兴奋性和传导性，导致心动过缓、传导阻滞等心律失常。兴奋性或自律性升高的各项描述与高镁的抑制作用相反，不符合其电生理效应，严重高镁还可致呼吸抑制甚至心脏停搏"},{"q":"阿米巴滋养体引起的组织坏死属于","o":["凝固性坏死","干酪样坏死","湿性坏疽","液化性坏死","纤维素样坏死"],"a":3,"e":"阿米巴滋养体分泌溶组织酶，溶解肠黏膜及肝组织，使组织液化形成烧瓶状溃疡或阿米巴肝脓肿，属液化性坏死。凝固性坏死多见于缺血性梗死；干酪样坏死为结核特征；湿性坏疽为肢体或内脏坏死合并腐败菌感染；纤维素样坏死见于变态反应性血管炎"},{"q":"体温上升期的热代谢特点是","o":["产热＞散热","散热＞产热","产热与散热在较高水平上保持相对平衡","产热障碍","散热障碍"],"a":0,"e":"体温上升期因致热原使体温调定点上移，机体产热大于散热，体温迅速上升，临床表现为寒战、皮肤苍白。散热大于产热为退热期特点；产热与散热在高水平平衡为高热持续期；产热或散热障碍分别见于一过性产热增加或中暑，均非体温上升期特征"},{"q":"下述关于急性肾盂肾炎的病变部位，错误的是","o":["累及肾小管","累及肾小球","累及肾间质","累及肾皮质","累及肾盂"],"a":1,"e":"急性肾盂肾炎是肾盂、肾间质和肾小管的急性化脓性炎，主要累及肾盂、肾皮质及髓质的间质和肾小管，可形成多发性小脓肿。肾小球一般不受累或其病变轻微，肾小球病变主要见于各类肾小球肾炎，故累及肾小球为错误描述"},{"q":"有关健康的正确提法是","o":["不生病就是健康","健康是指体格健全","健康是指没有疾病和衰弱现象","健康是指身心良好状态","健康是指躯体上、精神上和社会上的完好状态"],"a":4,"e":"世界卫生组织定义健康不仅是无疾病或衰弱，而是躯体上、精神上和社会适应方面的完好状态。不生病、体格健全或仅无疾病均为片面的生物医学模式认识；身心良好状态未涵盖社会适应维度，均不完整"},{"q":"急性代谢性酸中毒时，机体最主要的代偿方式是","o":["血液缓冲系统","细胞内外离子交换","肺的代偿","肾脏的代偿","骨骼的缓冲"],"a":2,"e":"急性代谢性酸中毒时，H+升高刺激外周和中枢化学感受器，使呼吸加深加快（Kussmaul呼吸），肺排出CO2增多，是机体最主要的代偿方式。血液缓冲系统作用迅速但缓冲容量有限；细胞内外离子交换可致高钾；肾脏代偿起效慢，需数小时至数日；骨骼缓冲更缓慢"},{"q":"急性细菌性痢疾初期结肠呈","o":["浆液性炎","出血性炎","脓肿","卡他性炎","蜂窝织炎"],"a":3,"e":"急性细菌性痢疾初期结肠黏膜呈急性卡他性炎，表现为黏膜充血、水肿及浆液渗出，随后发展为纤维素性炎（假膜性炎），形成特征性假膜，假膜脱落形成地图状溃疡。浆液性炎、出血性炎、脓肿、蜂窝织炎均非菌痢初期的典型病变"},{"q":"细胞内液中主要的阴离子是","o":["HPO42-","Cl-","SO42-","HCO3-","有机酸根离子"],"a":0,"e":"细胞内液主要阴离子为HPO42-（磷酸氢根）和蛋白质阴离子，它们与K+共同维持细胞内渗透压。Cl-是细胞外液主要阴离子；SO42-、HCO3-及有机酸根离子在细胞内含量均远低于HPO42-，非主要阴离子"},{"q":"下列细胞器中，对缺氧最敏感的是","o":["线粒体","溶酶体","滑面内质网","粗面内质网","高尔基体"],"a":0,"e":"线粒体是氧化磷酸化的场所，缺氧时最先受损，表现为肿胀、嵴断裂和基质空泡变，故对缺氧最敏感。溶酶体在缺氧晚期才破裂释放水解酶，滑面内质网与粗面内质网主要参与脂质和蛋白质合成，高尔基体负责加工转运，三者对缺氧的耐受性均强于线粒体"},{"q":"伤寒患者发病后第一周内做何种培养易获得细菌阳性","o":["粪便","尿","痰","血","胃液"],"a":3,"e":"伤寒沙门菌经血进入单核巨噬细胞系统，发病第一周菌血症最明显，血培养阳性率最高。粪便和尿培养的阳性率多在病程第二至三周才升高，痰与胃液并非伤寒杆菌的主要排泄途径，这些选项对应的采样时机与本病菌血症规律不符"},{"q":"转移性钙化最常见于下列哪种疾病","o":["甲状旁腺切除","骨折","甲状腺功能亢进","甲状旁腺功能亢进","结核性坏死"],"a":3,"e":"转移性钙化因全身钙磷代谢障碍、血钙升高，钙盐沉积于正常组织，最常见于甲状旁腺功能亢进、骨肿瘤和维生素D中毒。甲状旁腺切除致低钙，不发生此类钙化；骨折与结核性坏死属营养不良性钙化，沉积于坏死组织；甲亢与钙盐沉积无直接关系"},{"q":"严重肝硬化患者，若出现少尿、无尿、氮质血症，提示该患者出现了","o":["肝性性脑","肝肾综合征","内毒素血症","肝功能不全综合征","门脉高压征"],"a":1,"e":"肝肾综合征是严重肝病时的功能性肾衰竭，肾本身无器质性病变，临床以少尿、无尿和氮质血症为特征。肝性脑病以意识障碍为主，内毒素血症为肠源性内毒素入血，门脉高压征表现为腹水和静脉曲张，肝功能不全综合征概念过泛，均不特指此肾功能表现"},{"q":"病毒性肝炎时出现的毛玻璃样肝细胞，其胞质中含有大量","o":["HAV","HBsAg","HBcAg","HCV","HDV"],"a":1,"e":"毛玻璃样肝细胞见于乙型肝炎，胞质内滑面内质网增生并含大量HBsAg，光镜下呈毛玻璃状。HBcAg主要定位于肝细胞核，HAV、HCV、HDV感染不形成这种胞质改变，这些选项涉及的病毒抗原定位与HBsAg不同"},{"q":"大量空气迅速进入血液循环引起死亡的原因是","o":["心脏破裂","心肌梗死","肺梗死","急性心力衰竭","脑栓塞"],"a":3,"e":"大量空气迅速入血，在右心室内与血液混合形成泡沫状，阻碍血流排出，导致急性心力衰竭和窒息死亡。心脏破裂多为心肌梗死并发症，心肌梗死源于冠脉闭塞，肺梗死为肺动脉栓塞所致，脑栓塞引起神经症状，均非空气栓塞的致死机制"},{"q":"肝淤血的主要病变是","o":["肝小叶中央静脉及肝窦扩张充血，小叶中央区肝细胞变性、萎缩","肝小叶间静脉扩张充血，小叶周边部肝细胞变性、萎缩","肝小叶间静脉扩张充血，小叶间结缔组织增生","肝窦扩张充血，小叶间胆管和结缔组织增生","肝小叶间动静脉淤血，小叶间结缔组织增生"],"a":0,"e":"肝淤血时血液淤积于小叶中央静脉及周围肝窦，中央区肝细胞因缺氧变性、萎缩甚至坏死，长期可发展为淤血性肝硬化。小叶间静脉属门静脉分支，其扩张并非肝淤血特征；小叶间胆管和结缔组织增生属胆管病变，这些选项把淤血部位错置于小叶周边或间质"},{"q":"最常见的前列腺癌是","o":["黏液癌","移行细胞癌","腺癌","鳞状细胞癌","透明细胞癌"],"a":2,"e":"前列腺癌绝大多数起源于外周带腺上皮，组织学类型为腺癌。黏液癌和透明细胞癌在前列腺少见，移行细胞癌多源于膀胱尿路上皮，鳞状细胞癌极为罕见，均非前列腺癌的主要类型"},{"q":"十二指肠溃疡区别于胃溃疡的特点，下述正确的是","o":["临床上较少见","溃疡病灶更大","更易发生穿孔","更易发生出血","更易发生癌变"],"a":2,"e":"十二指肠溃疡好发于球部，溃疡小而深，易穿透肠壁发生穿孔，这是其区别于胃溃疡的突出特点。胃溃疡溃疡较大且癌变率较高；十二指肠溃疡临床上更常见，出血为两者共有的并发症，癌变极罕见，这些选项混淆了两者的好发特点"},{"q":"下列肿瘤中，属于恶性肿瘤的是","o":["脂肪瘤","乳头状瘤","葡萄胎","成熟型畸胎瘤","精原细胞瘤"],"a":4,"e":"精原细胞瘤是睾丸最常见的恶性肿瘤，起源于生殖细胞，对放射治疗敏感。脂肪瘤、乳头状瘤和成熟型畸胎瘤均为良性肿瘤；葡萄胎属异常妊娠的良性病变，仅有恶变倾向，均不属于恶性肿瘤"},{"q":"关于神经鞘瘤的病理特点，错误的是","o":["起源于胚胎期神经嵴来源的神经膜细胞","是最常见的外周神经良性肿瘤","肉眼见肿瘤包膜完整，常与神经粘连","是椎管内最常见的肿瘤","多发生于皮肤和皮下的的良性肿瘤"],"a":4,"e":"神经鞘瘤源于胚胎期神经嵴的神经膜细胞，是最常见的外周神经良性肿瘤，也是椎管内最常见肿瘤，包膜完整且常与神经干粘连。多发生于皮肤和皮下的是神经纤维瘤而非神经鞘瘤，该项张冠李戴"},{"q":"体内调节酸碱平衡作用强而持久的是","o":["血液的缓冲作用","肺的呼吸调节作用","肾脏的排酸保碱作用","组织细胞的缓冲作用","肝脏的调节作用"],"a":2,"e":"肾脏通过排氢保碱及重吸收碳酸氢盐调节酸碱平衡，作用强大而持久，是维持酸碱平衡的最终环节。血液缓冲系统反应最快但易耗竭，肺通过调节二氧化碳排出仅针对挥发性酸，组织细胞缓冲能力有限，肝脏不直接主导酸碱调节"},{"q":"急性普通型肝炎的病变特点是","o":["变性广泛，坏死轻微","变性广泛，淤胆明显","变性广泛，坏死严重","坏死广泛，炎细胞浸润明显","坏死广泛，Kupffer细胞增生活跃"],"a":0,"e":"急性普通型肝炎以肝细胞广泛变性为主，如气球样变和嗜酸性变，坏死轻微，仅见点状坏死。坏死广泛见于重型肝炎，淤胆明显为淤胆型肝炎特点，Kupffer细胞增生活跃非其典型改变，这些选项夸大了坏死程度或继发改变"},{"q":"结核性“冷脓肿”的本质属于","o":["液化性坏死","脂肪坏死","湿性坏疽","液化的干酪样坏死物质","脓肿"],"a":3,"e":"结核性冷脓肿是干酪样坏死物液化形成的，局部无红、热、痛等急性炎症表现，故称冷脓肿。液化性坏死多见于脑和胰腺，脂肪坏死见于急性胰腺炎及乳腺外伤，湿性坏疽为坏死合并腐败菌感染，一般脓肿为中性粒细胞浸润的脓腔，均与之不同"},{"q":"不符合克汀病的描述是","o":["头颅较大","智力正常","黏液水肿","身材矮小","鼻根宽平"],"a":1,"e":"克汀病因先天性甲状腺功能低下，表现为智力低下、身材矮小、头颅较大、鼻根宽平及黏液水肿。智力正常不符合克汀病，智力低下才是其核心特征，其余各项均为呆小症的典型表现"},{"q":"细菌进入血液中并大量繁殖，产生毒素，引起全身中毒症状，称之为","o":["毒血症","菌血症","病毒血症","败血症","脓毒败血症"],"a":3,"e":"败血症指细菌侵入血液并大量繁殖、产生毒素，引起全身中毒症状。毒血症仅有毒素入血而细菌不在血中繁殖，菌血症为细菌入血但无明显中毒症状，病毒血症的病原体为病毒，脓毒败血症还伴多发性化脓灶，各概念按细菌繁殖和脓肿形成区分"},{"q":"急性肾盂肾炎最常见的致病因子是","o":["金黄色葡萄球菌","大肠杆菌","链球菌","HIV","HBV"],"a":1,"e":"急性肾盂肾炎最常见致病菌为大肠杆菌，多经尿路逆行上行感染。金黄色葡萄球菌常致血源性肾脓肿，链球菌多引起肾小球肾炎，HIV和HBV为病毒，与细菌性肾盂肾炎的发病无关"},{"q":"下列关于二尖瓣狭窄的描述，错误的是","o":["左心室肥大，扩张","右心室肥大，扩张","左心房肥大，扩张","右心房肥大，扩张","肺淤血，水肿"],"a":0,"e":"二尖瓣狭窄时左房血液流入左室受阻，左房压力升高而肥大扩张，继而肺淤血、肺动脉高压及右室右房肥大扩张。左室因充盈减少并不肥大扩张，该项与二尖瓣狭窄的血流动力学改变相反"},{"q":"引起高磷血症的原因不包括","o":["肾功能衰竭","VitD中毒","甲状旁腺功能亢进","急性酸中毒","淋巴性白血病"],"a":2,"e":"高磷血症见于肾功能衰竭排磷减少、维生素D中毒促进磷吸收、急性酸中毒使磷移出细胞及淋巴性白血病等。甲状旁腺功能亢进时PTH促进尿磷排泄，反而引起低磷血症，故不属于高磷血症的原因"},{"q":"分化最低、恶性度最高的肺癌类型是","o":["类癌","腺鳞癌","小细胞癌","黏液癌","胶样腺癌"],"a":2,"e":"小细胞癌分化最低、恶性程度最高，起源于支气管黏膜嗜银细胞，生长迅速且早期发生转移。类癌分化较好、恶性度低，腺鳞癌、黏液癌和胶样腺癌属腺癌亚型，其分化程度和恶性度均不及小细胞癌"},{"q":"不同类型的休克，DIC形成的早晚不一，早期即可能出现DIC的休克类型是","o":["失血性休克","失液性休克","过敏性休克","感染性休克","心源性休克"],"a":3,"e":"感染性休克尤其内毒素性休克，内毒素可直接激活凝血系统并损伤血管内皮，早期即可发生DIC。失血性和失液性休克早期以代偿为主，过敏性休克主要因血管扩张和通透性增加，心源性休克源于泵衰竭，DIC出现较晚或不典型"},{"q":"关于气性坏疽的描述，不正确的是","o":["干性坏疽合并厌氧菌感染所致","较深的开放性创伤合并厌氧菌感染所致","坏死组织呈蜂窝状","坏死区按之有捻发音","常伴有严重的全身中毒症状"],"a":0,"e":"气性坏疽是深部开放性创伤合并产气荚膜梭菌等厌氧菌感染所致的湿性坏疽特殊类型，坏死组织呈蜂窝状，按之有捻发音，全身中毒症状严重。干性坏疽多为四肢末端缺血性坏死，干燥且不易合并厌氧菌感染，把气性坏疽归为干性坏疽不当"},{"q":"目前认为，动脉粥样硬化发生的始动环节是","o":["平滑肌细胞迁入内膜","内皮细胞慢性损伤","内皮下单核细胞浸润","血小板聚集","纤维组织增生"],"a":1,"e":"目前认为内皮细胞慢性损伤是动脉粥样硬化的始动环节，损伤后通透性增加、黏附分子表达，脂质得以进入内膜。平滑肌细胞迁入内膜、单核细胞浸润、血小板聚集和纤维组织增生均为损伤后的后续过程，而非始动因素"},{"q":"结核病发生干酪样坏死主要是由于","o":["结核分枝杆菌直接作用","动脉阻塞导致局部缺血","腐败菌感染","结核菌数量多，毒力强，超敏反应强烈","胰脂酶的作用"],"a":3,"e":"干酪样坏死是结核病的特征性病变，因结核菌数量多、毒力强，机体超敏反应强烈，组织坏死彻底而呈奶酪样。结核菌直接作用并非主因，动脉阻塞致缺血为梗死机制，腐败菌感染形成坏疽，胰脂酶作用导致脂肪坏死，均与其机制不同"},{"q":"瘢痕疙瘩是指在瘢痕形成过程中发生哪种变化","o":["瘢痕组织过度增生","瘢痕组织粘连","瘢痕组织收缩","瘢痕组织形成过少","瘢痕组织玻璃样变性"],"a":0,"e":"瘢痕疙瘩是瘢痕形成过程中胶原和结缔组织过度增生，超出原损伤范围而隆起增厚。瘢痕粘连指与周围组织黏着，瘢痕收缩可致挛缩畸形，形成过少导致愈合不良，玻璃样变性为陈旧瘢痕的常见改变，均非瘢痕疙瘩的本质"},{"q":"霍奇金淋巴瘤最常发生的部位是","o":["腹膜后淋巴结","腹股沟淋巴结","颈部淋巴结","纵隔淋巴结","腋下淋巴结"],"a":2,"e":"霍奇金淋巴瘤最常原发于颈部淋巴结，其次为纵隔、腋下和腹膜后，常沿淋巴道有序扩散。腹膜后、腹股沟、纵隔和腋下淋巴结虽可受累，但发生率均低于颈部，颈部是其最典型的首发部位"},{"q":"食管癌最常见的好发部位是","o":["食管颈段","贲门","食管中段生理性狭窄处","食管上段生理性狭窄处","食管下段生理性狭窄处"],"a":2,"e":"食管癌好发于食管中段，其次为下段，上段最少，与食物通过生理性狭窄处反复摩擦刺激有关。贲门属胃食管交界，该处癌多为贲门癌；颈段及食管上、下段狭窄处的发病率均低于中段"},{"q":"动脉血流中断可引起液化性坏死的器官是","o":["心脏","肺脏","脾脏","脑","肾脏"],"a":3,"e":"脑组织脂质丰富而蛋白质少，缺血坏死后易软化、液化，形成液化性坏死。心、脾、肾梗死因蛋白质丰富、组织致密，多为凝固性坏死；肺组织疏松含气，梗死常呈出血性，均非液化性坏死"},{"q":"神经细胞卫星现象是指在变性坏死的神经细胞周围围绕着增生的","o":["小胶质细胞","星形胶质细胞","少突胶质细胞","淋巴细胞","中性白细胞"],"a":2,"e":"卫星现象指变性坏死的神经细胞周围围绕增生的少突胶质细胞，是中枢神经损伤的常见改变。小胶质细胞包围吞噬坏死神经元为噬神经细胞现象，星形胶质细胞主要增生形成胶质瘢痕，淋巴细胞和中性粒细胞属炎症细胞，均不构成卫星现象"},{"q":"下列哪项不是类风湿性关节炎的关节病理改变","o":["滑膜细胞肥大增生，呈多层","滑膜下慢性炎症细胞浸润","关节软骨表面血管翳形成","Aschoff小体形成","关节肿胀、畸形"],"a":3,"e":"Aschoff小体是风湿热的特征性肉芽肿，见于风湿性心肌炎，不属于类风湿关节炎的关节病变。类风湿关节炎以滑膜细胞肥大增生呈多层、滑膜下慢性炎细胞浸润、关节软骨表面血管翳形成及关节肿胀畸形为特点"},{"q":"血吸虫结肠病变一般不发生","o":["肠黏膜溃疡","肠黏膜息肉","肠腔梗阻","肠壁虫卵结节","肠出血和穿孔"],"a":4,"e":"血吸虫结肠病变以虫卵结节、黏膜溃疡、息肉形成和肠腔梗阻为主，晚期肠壁增厚。肠出血和穿孔并非血吸虫病的常见并发症，其溃疡较浅、演进缓慢，一般不致穿孔，这与细菌性痢疾等急性肠道炎症不同"},{"q":"大叶性肺炎患者咳痰铁锈色痰出现在","o":["充血水肿期","红色肝变期","灰色肝变期","溶解消散期","恢复期"],"a":1,"e":"大叶性肺炎红色肝变期肺泡腔内充满红细胞、纤维素和中性粒细胞，红细胞破坏后含铁血黄素混入痰液，形成铁锈色痰。充血水肿期痰少，灰色肝变期红细胞减少、痰呈灰白色，溶解消散期和恢复期痰液变稀，均非铁锈色痰的典型时期"},{"q":"活动性风湿性心脏病时，阿绍夫小体常见部位是","o":["心内膜下","心外膜内","心瓣膜内","心肌间质","心肌传导系统"],"a":3,"e":"阿绍夫小体是风湿热的特征性肉芽肿，活动性风湿性心肌炎时多见于心肌间质，尤以小血管旁常见。心内膜下、心瓣膜内和心外膜虽可受累，但心肌间质是小体最常见、最典型的部位，心肌传导系统并非其好发部位"},{"q":"休克早期患者的神志一般为","o":["昏迷","昏睡","淡漠","半昏迷","清醒"],"a":4,"e":"休克早期脑灌注基本维持，患者神志清楚，但可有烦躁不安。昏迷、昏睡和半昏迷为休克中晚期脑灌注严重不足的表现，淡漠多见于休克期，均不属于休克早期的神志状态"},{"q":"消化性溃疡最常出现的并发症是","o":["穿孔","出血","幽门狭窄","癌变","机化"],"a":1,"e":"出血是消化性溃疡最常见的并发症，因溃疡侵蚀基底血管所致，表现为呕血和黑便。穿孔发生率低于出血，幽门狭窄由瘢痕收缩引起，癌变主要见于胃溃疡且发生率低，机化属愈合过程，均非最常见并发症"},{"q":"风湿性瓣膜病常见的联合瓣膜损害发生在","o":["二尖瓣和三尖瓣","二尖瓣和主动脉瓣","三尖瓣和主动脉瓣","三尖瓣和肺动脉瓣","主动脉瓣和肺动脉瓣"],"a":1,"e":"风湿性心脏病最常累及二尖瓣，其次为主动脉瓣，二者联合受损最常见。三尖瓣和肺动脉瓣受累较少，且多继发于左心瓣膜病变和肺动脉高压，故含三尖瓣或肺动脉瓣的组合均不如二尖瓣合并主动脉瓣常见"},{"q":"细菌性痢疾主要累及","o":["空肠","回肠下段","升结肠","乙状结肠","回肠上段"],"a":3,"e":"细菌性痢疾主要累及大肠，以乙状结肠和直肠病变最重，形成假膜性炎和溃疡。空肠和回肠上段属小肠，回肠下段是伤寒的好发部位，升结肠虽属大肠但病变不如乙状结肠显著"},{"q":"胃溃疡的肉眼表现一般是","o":["2cm以上的较浅溃疡，边缘不整齐","2cm以上的较不规则溃疡，底部不平坦有坏死","2cm以上的火山口状或不规则溃疡","2cm以内的圆形溃疡，幽门侧边缘呈耸直状","2cm以内的圆形溃疡，边缘整齐，底部平坦"],"a":4,"e":"胃溃疡多见于胃小弯，直径多在2cm以内，呈圆形或椭圆形，边缘整齐、底部平坦洁净。直径超过2cm、边缘不整齐、底部不平坦有坏死或呈火山口状的溃疡是溃疡型胃癌的特点，把恶性溃疡的肉眼特征误用于胃溃疡不当"},{"q":"急性肾损伤定义肾功能或结构方面异常的时间为","o":["不超过1周","不超过1个月","不超过2个月","不超过3个月","不超过6个月"],"a":3,"e":"急性肾损伤指短期内肾功能急剧恶化，定义为肾功能或结构异常持续不超过3个月，以与病程超过3个月的慢性肾脏病相区别。不超过1周、1个月和2个月均非急慢性分界，6个月已属慢性肾病范畴"},{"q":"引起细胞损伤的生化机制，不包括","o":["细胞内钙超载","病原微生物侵入","遗传变异","氧自由基积聚","三磷酸腺苷耗竭"],"a":1,"e":"细胞损伤的生化机制包括ATP耗竭、氧自由基积聚、细胞内钙超载和遗传变异等内在代谢障碍。病原微生物侵入属于外源性生物性致病因素，而非细胞损伤的生化机制，其余各项均为常见的生化环节"},{"q":"机体感染结核杆菌后，发生原发性肺结核的原因是","o":["感染的细菌数量大","机体对结核菌处于过敏状态","细菌毒力强","病人年龄小","机体对结核杆菌缺乏免疫力"],"a":4,"e":"原发性肺结核见于初次感染结核杆菌、机体缺乏特异性免疫力的个体，多见于儿童。感染细菌数量大和毒力强只影响病变严重程度，过敏状态见于继发性肺结核，年龄小并非决定因素，缺乏免疫力才是发病关键"},{"q":"下列描述中，不符合萎缩特点的是","o":["细胞数量减少","细胞体积缩小","细胞内有脂褐素","细胞核固缩","间质增多"],"a":3,"e":"萎缩指发育正常的器官或细胞体积缩小、数量减少，胞质内可见脂褐素沉积，间质可代偿性增多。细胞核固缩是细胞凋亡或坏死的表现，不属于萎缩的特点，其余各项均为萎缩的常见形态学改变"},{"q":"最常见的肠外阿米巴病是","o":["肺脓肿","肝脓肿","脑脓肿","脓胸","心包炎"],"a":1,"e":"阿米巴原虫经肠壁血道播散，最常侵犯肝脏形成阿米巴肝脓肿，是肠外阿米巴病最常见的类型。肺脓肿、脑脓肿和脓胸多继发于肝脓肿，心包炎更为罕见，均不如肝脓肿常见"},{"q":"主动脉粥样硬化病变最严重的部位是","o":["主动脉弓","胸主动脉","腹主动脉","升主动脉","主动脉瓣"],"a":2,"e":"主动脉粥样硬化以腹主动脉病变最重，其次为主动脉弓和胸主动脉，病变多见于血管后壁及分支开口处。升主动脉和主动脉瓣受累较轻，腹主动脉因血流动力学特点最易发生粥样硬化"},{"q":"氨中毒导致肝性脑病时，与脑水肿发生相关的细胞是","o":["肝库普弗细胞","肝细胞","脑星形胶质细胞","神经细胞","小胶质细胞"],"a":2,"e":"高氨血症时脑星形胶质细胞摄取氨合成谷氨酰胺，谷氨酰胺增多使细胞内渗透压升高、细胞肿胀，是肝性脑病脑水肿的关键机制。Kupffer细胞和肝细胞位于肝脏，神经细胞与小胶质细胞并非氨代谢的主要场所"},{"q":"CRF时水钠代谢失调的机制不包括","o":["肾小管对尿的浓缩和稀释功能降低","渗透性利尿","原尿流速快致重吸收减少","代谢产物蓄积抑制肾小管重吸收","GFR显著降低"],"a":4,"e":"慢性肾衰时水钠代谢失调主要源于肾小管浓缩稀释功能降低、渗透性利尿、原尿流速加快致重吸收减少及代谢产物蓄积抑制重吸收。GFR显著降低是肾功能衰竭本身的指标，并非这里所指的水钠代谢失调的特异机制"},{"q":"与良性高血压引起的脑部病变无关的是","o":["脑出血","脑水肿","脑血栓栓塞","脑内微梗死灶","脑内微小动脑瘤形成"],"a":2,"e":"良性高血压的脑部病变包括脑出血、脑水肿、脑内微梗死灶及微小动脉瘤形成，长期小动脉硬化可致脑软化。脑血栓栓塞多源于动脉粥样硬化斑块或心源性栓子，并非良性高血压直接引起"},{"q":"动脉粥样硬化斑块中不含有的成分是","o":["苏丹Ⅲ染色阳性物质","中性粒细胞","纤维组织增生伴透明样变","泡沫细胞","无定形坏死物质"],"a":1,"e":"粥样斑块由泡沫细胞、细胞外脂质、无定形坏死物、纤维组织增生伴透明样变及胆固醇结晶构成，苏丹Ⅲ染色阳性。中性粒细胞是急性炎症细胞，不参与粥样斑块的慢性构成，其余成分均为斑块的典型表现"},{"q":"贫血性梗死常发生于","o":["心、脑、肠","脾、肠、肺","脾、肾、心","肺、肠、脑","心、脑、肺"],"a":2,"e":"贫血性梗死发生于组织致密、侧支循环不丰富的器官，如脾、肾、心，梗死区呈灰白色。脑梗死多为液化性坏死，肺和肠组织疏松且有双重血供，梗死常为出血性，含肺或肠的组合均不符合贫血性梗死"},{"q":"心力衰竭的最常见诱因是","o":["呼吸道感染","分娩","高钾血症","酸中毒","创伤及手术"],"a":0,"e":"呼吸道感染是心力衰竭最常见的诱因，感染增加机体代谢需求、加重心脏负荷并可损伤心肌。分娩、创伤手术、高钾血症和酸中毒亦可诱发心衰，但发生率均低于呼吸道感染"},{"q":"下列描述符合视网膜母细胞瘤的是","o":["好发于中年人，白色人种多见","来源于视网膜胚基","常见出血、坏死等继发病变","基本不发生转移，预后较好","镜下可见异型的梭形细胞呈“鲱鱼骨”样排列"],"a":1,"e":"视网膜母细胞瘤起源于视网膜胚基，是儿童常见的眼内恶性肿瘤，常伴出血、坏死和钙化。好发于中年人且白色人种多见不符合本病，其多见于婴幼儿；鲱鱼骨样排列为其他梭形细胞肿瘤的表现"},{"q":"垂体腺瘤和垂体腺癌鉴别诊断的主要依据是","o":["瘤细胞形态","肿瘤大小","肿瘤细胞的染色特性","有否侵犯周围组织和发生转移","肿瘤是否分泌激素"],"a":3,"e":"垂体腺瘤与垂体腺癌的鉴别主要依据生物学行为，即是否侵犯周围组织和发生转移，而非瘤细胞形态、大小或染色特性。腺瘤边界清楚且不转移，腺癌呈浸润性生长并可转移；是否分泌激素与良恶性无关"},{"q":"肝性脑病最常见的诱发因素是","o":["感染","便秘","消化道出血","碱中毒","镇静麻醉类药物"],"a":2,"e":"消化道出血是肝性脑病最常见的诱因，血液在肠道内分解产生大量氨，吸收入血后诱发脑病。感染、便秘、碱中毒和镇静麻醉类药物亦可诱发，但消化道出血因产氨量大而居首位"},{"q":"低渗性脱水对机体的影响不包括","o":["易发生休克","无口渴感","肾外因素所致失钠者，尿Na+含量减少","有明显脱水体征","早期ADH分泌增多，晚期ADH分泌减少"],"a":4,"e":"低渗性脱水时细胞外液渗透压降低，早期ADH分泌受抑制而减少，晚期血容量明显不足时ADH才增多。易发生休克、无口渴感和明显脱水体征均为其特点，肾外失钠者尿钠减少，所述ADH变化规律正好相反"},{"q":"不符合炎症性增生的描述是","o":["具有抗损伤的作用","具有修复功能","可引起间质增生","可引起实质增生","对机体有益无害"],"a":4,"e":"炎症性增生具有抗损伤和修复作用，可引起实质细胞和间质细胞增生，但过度增生可致组织器官功能障碍，并非有益无害。其余各项均为炎症增生的作用或表现，唯有有益无害的绝对化表述不符合"},{"q":"大叶性肺炎最常见的致病菌是","o":["腺病毒","肺炎支原体","大肠杆菌","肺炎杆菌","肺炎链球菌"],"a":4,"e":"大叶性肺炎最常见的致病菌是肺炎链球菌，其次为肺炎杆菌等。腺病毒和肺炎支原体多引起间质性肺炎，大肠杆菌常见于革兰阴性杆菌肺炎，这些病原体引起的病变类型与大叶性肺炎不同"},{"q":"与肝癌发生有关的因素很多，目前已知的因素中不包括","o":["华支睾吸虫感染","乙型肝炎","丙型肝炎","幽门螺杆菌","黄曲霉毒素"],"a":3,"e":"肝癌的相关因素包括乙型和丙型肝炎病毒感染、黄曲霉毒素及华支睾吸虫感染等。幽门螺杆菌与胃癌和消化性溃疡关系密切，与原发性肝癌无明确关系，故不属于已知的相关因素"},{"q":"引起低钙血症的原因不包括","o":["维生素D的缺乏","PTH缺乏","慢性肾功能衰竭","高镁血症","急性胰腺炎"],"a":3,"e":"低钙血症见于维生素D缺乏、PTH缺乏、慢性肾功能衰竭及急性胰腺炎时脂肪坏死消耗钙。高镁血症主要抑制神经肌肉兴奋性，并非低钙血症的常见病因，临床上低镁血症更易引起低钙"},{"q":"细动脉壁的玻璃样变最常发生于","o":["急性弥漫性增生性肾小球肾炎","急性肾盂肾炎","快速进行性肾小球肾炎","急进型高血压","缓进型高血压"],"a":4,"e":"细动脉壁玻璃样变是缓进型高血压的特征性病变，因长期血压升高使血浆蛋白渗入血管壁并沉积。急进型高血压以纤维素样坏死为主，急性弥漫性增生性肾炎、快速进行性肾炎和急性肾盂肾炎均无此种细动脉改变"},{"q":"呼吸衰竭并发功能性肾衰竭的机制是","o":["产生广泛性肾小球器质性损伤","酸中毒导致血清K＋浓度增高","肾小球超滤状态","肾血流量严重减少","产生急性肾小管坏死"],"a":3,"e":"呼吸衰竭时缺氧和高碳酸血症反射性引起肾血管收缩，肾血流量严重减少，导致功能性肾衰竭，肾本身并无器质性损伤。广泛肾小球损伤和急性肾小管坏死属器质性病变，酸中毒致高血钾和肾小球超滤状态均非主要机制"},{"q":"造成阻塞性通气不足的原因是","o":["呼吸及活动受限","胸廓顺应性降低","肺顺应性降低","气道阻力增加","弥散障碍"],"a":3,"e":"阻塞性通气不足由气道狭窄或阻塞导致气道阻力增加引起，如支气管痉挛和痰液堵塞。呼吸及活动受限、胸廓和肺顺应性降低属于限制性通气不足的原因，弥散障碍影响气体交换而非通气"},{"q":"急性细菌性痢疾的典型肠道病变为","o":["化脓性炎","卡他性炎","假膜性炎","出血性炎","蜂窝织炎"],"a":2,"e":"急性细菌性痢疾是志贺菌引起的假膜性炎，肠黏膜表面形成由纤维素、中性粒细胞和坏死组织构成的假膜，脱落后形成地图状溃疡。化脓性炎、卡他性炎、出血性炎和蜂窝织炎均非菌痢的典型病变"},{"q":"心的后负荷增高时，心脏的主要代偿方式是","o":["Frank-Starling机制","心肌肥厚","心脏扩大","交感神经兴奋性增加","肾素-血管紧张素-醛固酮系统激活"],"a":1,"e":"心脏后负荷即压力负荷增高时，心室需克服更大阻力收缩，心肌发生向心性肥厚以增强收缩力。Frank-Starling机制是前负荷增加的代偿，心脏扩大属容量负荷增加的表现，交感兴奋和肾素-血管紧张素-醛固酮系统激活为神经体液代偿"},{"q":"肝性脑病时，血浆芳香族氨基酸增多的危害是","o":["支链氨基酸浓度减少","能量物质减少","导致酸中毒","导致碱中毒","导致假性神经递质增多"],"a":4,"e":"肝性脑病时芳香族氨基酸入脑增多，经脱羧生成苯乙醇胺和羟苯乙醇胺等假性神经递质，取代正常儿茶酚胺而致脑功能紊乱。支链氨基酸减少是伴随变化，能量物质减少和酸碱失衡并非其主要危害"},{"q":"下列哪一种酸碱平衡紊乱时易发生肺性脑病","o":["代谢性酸中毒","呼吸性酸中毒","代谢性碱中毒","呼吸性碱中毒","混合性碱中毒"],"a":1,"e":"呼吸性酸中毒时PaCO2升高，二氧化碳易透过血脑屏障并在脑脊液中生成氢离子，引起脑血管扩张、脑水肿和颅内压升高，导致肺性脑病。代谢性酸中毒、代谢性碱中毒、呼吸性碱中毒及混合性碱中毒均不以二氧化碳潴留为核心"},{"q":"帕金森病的临床表现不包括","o":["震颤、肌强直","步态不稳","记忆力减退，情感障碍","假面具样面容","起步及止步困难"],"a":2,"e":"帕金森病主要表现为静止性震颤、肌强直、运动迟缓和步态不稳，可有假面具样面容及起步、止步困难。记忆力减退和情感障碍属认知与精神损害，并非帕金森病的核心表现，多见于痴呆或精神疾病"},{"q":"关于家族性高胆固醇血症的描述，正确的是","o":["LDL受体缺陷","自身免疫性受体病","高胆固醇饮食所致","G蛋白偶联受体异常","继发性LDL受体异常病"],"a":0,"e":"家族性高胆固醇血症是常染色体显性遗传病，由LDL受体基因突变致受体缺陷，LDL清除障碍，血胆固醇显著升高。它不是自身免疫性受体病，也非G蛋白偶联受体异常；高胆固醇饮食和继发性LDL受体异常均属获得性因素"},{"q":"下列关于AIDS机会性感染的描述，不正确的是","o":["肺部可感染卡氏肺孢菌","中枢神经系统可感染弓形虫","消化道可感染白色念珠菌","感染所致的炎症反应较严重","可表现为假膜性炎、化脓性炎"],"a":3,"e":"AIDS患者CD4阳性T细胞严重减少，机会性感染时炎症反应往往轻微或缺如，病原体大量繁殖而组织反应不明显。卡氏肺孢菌致肺炎、弓形虫侵犯中枢、白色念珠菌致消化道感染均为常见机会感染，可呈假膜性炎或化脓性炎，故反应严重之说不当"},{"q":"干线型肝硬化的病理改变不包括","o":["明显的汇管区纤维化","形成明显的假小叶","肝脏变小、变硬","窦前性门脉高压","可形成粗大隆起的结节"],"a":1,"e":"干线型肝硬化即血吸虫性肝硬化，以汇管区明显纤维化、窦前性门脉高压、肝变小变硬及粗大隆起结节为特点，虫卵结节沿门静脉分支分布。纤维组织沿汇管区呈树枝状增生，一般不形成典型的假小叶，此为与门脉性肝硬化的区别"},{"q":"高度选择性蛋白尿见于","o":["局灶性节段性肾小球硬化","膜性肾小球病","膜增生性肾小球肾炎","脂性肾病","新月体性肾小球肾炎"],"a":3,"e":"脂性肾病即微小病变性肾小球病，因足细胞损伤、电荷屏障破坏而出现高度选择性蛋白尿，以白蛋白为主。膜性肾小球病和膜增生性肾小球肾炎多为非选择性蛋白尿，局灶节段性硬化和新月体性肾炎蛋白尿选择性低"},{"q":"肉芽组织的主要成分是","o":["成纤维细胞、血管内皮细胞、炎症细胞","异物巨细胞、成纤维细胞、类上皮细胞","血管内皮细胞、成纤维细胞、类上皮细胞","表皮细胞、成纤维细胞、异物巨细胞","炎症细胞、成纤维细胞、异物巨细胞"],"a":0,"e":"肉芽组织由新生的毛细血管、成纤维细胞和炎症细胞构成，肉眼呈鲜红颗粒状，是机化和创伤修复的基础。异物巨细胞和类上皮细胞是肉芽肿性炎的成分，表皮细胞参与被覆上皮修复，均非肉芽组织的主要成分"},{"q":"下述CRF时钙磷代谢失调的表现中，哪一项是错误的","o":["血钙降低","血磷降低","PTH增多","甲状旁腺功能亢进","肾性骨病"],"a":1,"e":"慢性肾衰时磷排泄障碍致血磷升高，血钙降低，继发PTH增多和甲状旁腺功能亢进，长期可致肾性骨病。血磷降低与排磷障碍相反，其余各项均符合慢性肾衰钙磷代谢失调的表现"},{"q":"恶性高血压时，细动脉内有细丝网状或小条块状的红染无结构物质，其改变可能是","o":["玻璃样变","淀粉样变","黏液样变","纤维素样坏死","干酪样坏死"],"a":3,"e":"恶性高血压时细动脉壁发生纤维素样坏死，镜下呈细丝网状或小条块状红染无结构物质，是其特征性改变。玻璃样变见于缓进型高血压，淀粉样变、黏液样变和干酪样坏死各有不同形态与病因，均不符合此描述"},{"q":"炎症最常见的原因是","o":["物理性因子","化学性因子","生物性因子","组织坏死","变态反应"],"a":2,"e":"炎症最常见的原因是生物性因子，包括细菌、病毒、真菌和寄生虫等感染。物理性因子、化学性因子、组织坏死和变态反应也可引起炎症，但发生率均不及生物性因子"},{"q":"维生素B1缺乏引起心力衰竭的机制是","o":["心肌结构受损","能量储存障碍","能量利用障碍","能量生成障碍","心肌兴奋-收缩耦联障碍"],"a":3,"e":"维生素B1是丙酮酸脱氢酶的辅酶成分，缺乏时糖代谢受阻、ATP生成减少，心肌因能量生成障碍而收缩无力，导致心力衰竭。能量储存障碍、能量利用障碍和兴奋-收缩耦联障碍属于其他机制，心肌结构受损并非脚气病心的主要环节"},{"q":"以下哪一项是肾衰竭的最终表现形式","o":["少尿无尿","高钾血症","自身中毒症状","肾性高血压","氮质血症"],"a":2,"e":"肾衰竭时代谢废物蓄积并伴水电解质和酸碱平衡紊乱，最终表现为全身各系统的自身中毒症状，是肾功能丧失的终末表现。少尿无尿、高钾血症、氮质血症和肾性高血压均为具体表现或中间环节，不能概括最终形式"},{"q":"单纯型代谢性酸中毒时，不可能出现下列哪种变化","o":["pH降低","PaCO2降低","SB降低","BB降低","BE负值减小"],"a":4,"e":"单纯型代谢性酸中毒时HCO3-减少，表现为pH降低、标准碳酸氢盐和缓冲碱降低、碱剩余负值增大，PaCO2因代偿而降低。碱剩余负值减小提示体内碱增多，与代谢性酸中毒方向相反，不可能出现"},{"q":"原位癌是指","o":["癌细胞累及上皮全层，但末突破基底膜","光镜下才能见到的微小癌","癌细胞累及上皮层下三分之一","没有发生转移的癌","早期癌"],"a":0,"e":"原位癌指癌细胞累及上皮全层但未突破基底膜，无间质浸润和转移，属早期癌。光镜下才能见到的微小癌强调体积，累及上皮下三分之一为轻度异型增生，没有转移的癌不一定是原位癌，早期癌概念更宽，均非其准确定义"},{"q":"高动力型（高排低阻型）休克最常见于","o":["失血性休克","创伤性休克","感染性休克","失液性休克","心源性休克"],"a":2,"e":"高动力型即高排低阻型休克以心输出量增加、外周阻力降低为特点，最常见于感染性休克早期，因血管扩张和动静脉短路开放所致。失血性、失液性和心源性休克均为低排高阻型，创伤性休克也以低动力为主"},{"q":"急性白血病的特征病变是","o":["外周血白细胞数目增高","淋巴结肿大","脾肿大","骨髓内原始和幼稚细胞大量堆积","肝肿大"],"a":3,"e":"急性白血病的特征是骨髓内原始和幼稚细胞大量增殖堆积，抑制正常造血并浸润髓外组织。外周血白细胞增高、淋巴结、脾和肝肿大为常见表现，但并非特征性病变，部分病例白细胞数可不增高"},{"q":"因微循环血管壁通透性增加，血液通过扩大的内皮细胞间隙和受损的基膜漏出血管外，称为","o":["出血倾向","生理性出血","淤血性出血","破裂性出血","漏出性出血"],"a":4,"e":"漏出性出血因微血管壁通透性增加，血液经扩大的内皮细胞间隙和受损基膜漏出血管外，常见于淤血、缺氧、过敏和DIC。出血倾向为临床表现，生理性出血如月经，淤血性出血因静脉压升高，破裂性出血由血管壁破裂所致"},{"q":"肿瘤分级所依据的主要原则是","o":["肿瘤分化程度的高低、异型性大小和转移情况","肿瘤的大小、浸润的深度和转移情况","肿瘤分化程度的高低、异型性大小和病理性核分裂象的多少","肿瘤的大小、异型性大小和转移情况","肿瘤的异型性大小、病理性核分裂象的多少和浸润的深度"],"a":2,"e":"肿瘤分级依据分化程度的高低、异型性大小和病理性核分裂象的多少，反映肿瘤的恶性程度。肿瘤大小和浸润深度、有无转移均属分期范畴，含这些项目的选项混淆了分级与分期"},{"q":"钡中毒可引起低钾血症，其机制是","o":["结肠分泌钾增加","促进钾往细胞内移","钾从细胞内流出受阻","小肠吸收钾减少","剧烈呕吐丢失钾"],"a":2,"e":"钡中毒可阻断钾通道，使细胞内钾外流受阻，从而引起低钾血症。结肠分泌钾增加、小肠吸收钾减少和剧烈呕吐丢失钾虽可致低钾，但并非钡中毒机制；促进钾向细胞内移见于胰岛素使用或碱中毒，均不符合"},{"q":"下列肿瘤中，属于良性肿瘤的是","o":["平滑肌瘤","血管肉瘤","神经母细胞瘤","精原细胞瘤","淋巴瘤"],"a":0,"e":"平滑肌瘤是常见的良性间叶组织肿瘤。血管肉瘤、神经母细胞瘤、精原细胞瘤和淋巴瘤均为恶性肿瘤，分别属于血管、神经外胚层、生殖细胞和淋巴造血组织的恶性病变"},{"q":"休克晚期组织微循环灌流的特点是","o":["少灌多流、流多于灌","多灌多流、灌多于流","少灌少流、灌少于流","多灌少流、灌多于流","不灌不流、血流停滞"],"a":4,"e":"休克晚期即微循环衰竭期，微血管麻痹扩张并对血管活性物质失去反应，毛细血管内血流停滞、不灌不流，可发生DIC和多器官衰竭。少灌少流、灌少于流为休克早期，多灌少流、灌多于流为休克期，均不符合晚期"},{"q":"DIC患者最初常表现为","o":["少尿","出血","呼吸困难","贫血","休克"],"a":1,"e":"DIC早期因凝血因子和血小板大量消耗，加之继发性纤溶亢进，常以出血为首发表现，如皮肤黏膜瘀斑和穿刺处渗血。少尿、呼吸困难、休克和贫血可随后出现，但出血是最常见的初始症状"},{"q":"肝细胞桥接坏死主要见于","o":["肝硬化","急性重型肝炎","急性普通型肝炎","慢性普通型肝炎","肝细胞癌"],"a":3,"e":"桥接坏死是慢性普通型肝炎的特征性病变，坏死灶连接中央静脉与汇管区或两个汇管区，提示病变慢性化和活动性。急性普通型肝炎以点状坏死为主，急性重型肝炎为大片坏死，肝硬化与肝癌并非其特指病变"},{"q":"乙型脑炎的病理变化不包括","o":["神经细胞变性坏死","小脓肿形成","以淋巴细胞浸润为主的血管套形成","筛网状软化灶形成","胶质细胞增生"],"a":1,"e":"流行性乙型脑炎是病毒性脑炎，特征为神经细胞变性坏死、淋巴细胞浸润形成的血管套、筛网状软化灶及胶质细胞增生。小脓肿形成是化脓性脑膜炎或细菌性脑脓肿的表现，病毒性脑炎不形成脓肿"},{"q":"下列哪一项符合脓毒败血症的描述","o":["细菌大量入血，但不引起中毒症状","细菌的毒素入血，出现中毒症状","细菌的毒素入血，不出现中毒症状","细菌随血流运行，在内脏引起多个脓肿，出现中毒症状","细菌入血繁殖，产生毒素，出现中毒症状"],"a":3,"e":"脓毒败血症指化脓菌入血繁殖并随血流运行，在肺、肝、肾等内脏形成多个转移性脓肿，伴严重中毒症状。仅毒素入血并中毒为毒血症，细菌入血繁殖产毒为败血症，不出现中毒症状或仅毒素入血者均不符合脓毒败血症"},{"q":"BE负值增大可见于","o":["代谢性酸中毒","代谢性碱中毒","急性呼吸性酸中毒","慢性呼吸性酸中毒","急性呼吸性碱中毒"],"a":0,"e":"碱剩余负值增大表示体内碱储备减少，是代谢性酸中毒的典型血气改变。代谢性碱中毒时碱剩余正值增大，急性呼吸性酸中毒时碱剩余基本正常，慢性呼吸性酸中毒和呼吸性碱中毒的变化方向与代偿机制均不同"},{"q":"关于一氧化碳中毒的叙述，下列哪一项不正确","o":["CO和Hb结合生成的碳氧血红蛋白（HbCO）无携氧能力","CO抑制红细胞内的糖酵解，使2，3-DPG减少，氧离曲线左移","吸入气中CO浓度为0、1%时，可致中枢神经系统和心脏难以恢复的损伤","呼吸加深变快，肺通气量增加","皮肤、黏膜呈樱桃红色"],"a":3,"e":"一氧化碳中毒时碳氧血红蛋白无携氧能力，且氧离曲线左移导致组织缺氧，但动脉血氧分压正常，呼吸中枢兴奋性不高，呼吸并无明显加深加快。皮肤黏膜樱桃红色、2,3-DPG减少及高浓度CO致中枢和心脏难以恢复的损伤均正确"},{"q":"室间隔缺损可引起心负荷过重，表现为","o":["心室前负荷增加","心室前负荷降低","心室后负荷增加","心室后负荷降低","心房前负荷增加"],"a":0,"e":"室间隔缺损时血液从左室经缺损分流至右室，再经肺循环回流，使左、右心室的容量负荷即前负荷增加，心脏扩大。后负荷增高见于主动脉瓣狭窄和高血压，前负荷降低与心房前负荷增加均不符合室缺的血流动力学改变"},{"q":"关于炎症的说法，正确的是","o":["炎症反应均对机体有利","任何机体均可发生炎症","炎症是一种防御反应","损伤必然导致炎症","炎症是活体组织的损伤反应"],"a":2,"e":"炎症是具有血管系统的活体组织对损伤因子的防御反应，以变质、渗出和增生为主要变化。炎症并非均对机体有利，过度反应可致损伤；无血管的机体不能发生；损伤不一定都引起炎症；炎症是防御反应而非单纯损伤反应"},{"q":"调节体温的高级中枢位于","o":["大脑皮层","海马回","视前区－下丘脑前部","延髓","脊髓"],"a":2,"e":"视前区-下丘脑前部是体温调节的高级中枢，含温度敏感神经元，整合产热与散热过程。大脑皮层参与行为性体温调节，海马回与记忆有关，延髓和脊髓仅有低级反射中枢，均非体温调节的高级中枢"},{"q":"尿崩症容易引起","o":["高渗性脱水","水中毒","水肿","低渗性脱水","等渗性脱水"],"a":0,"e":"尿崩症因抗利尿激素缺乏或作用障碍，排出大量低渗尿，水分丢失远多于电解质，导致高渗性脱水，表现为口渴、多尿和低比重尿。水中毒和低渗性脱水的渗透压变化与之相反，水肿和等渗性脱水亦不符合其失水特点"},{"q":"下列肿瘤中，常呈浸润性生长的是","o":["腺瘤","平滑肌瘤","乳头状瘤","脂肪瘤","毛细血管瘤"],"a":4,"e":"毛细血管瘤由增生的毛细血管构成，虽属良性肿瘤但常呈浸润性生长，边界不清。腺瘤、平滑肌瘤、乳头状瘤和脂肪瘤多呈膨胀性生长，边界清楚并有包膜，与毛细血管瘤的生长方式不同"},{"q":"炎症局部的基本病理变化是","o":["组织、细胞变性坏死","组织炎性充血和水肿","红、肿、热、痛、功能障碍","变质、渗出、增生","血液中白细胞增多、炎区白细胞浸润"],"a":3,"e":"炎症局部的基本病理变化是变质、渗出和增生，三者相互联系。变性坏死和炎性充血水肿只是部分表现，红肿热痛与功能障碍为临床体征，白细胞增多和浸润属于渗出的一部分，均不能全面概括基本病变"},{"q":"肝性脑病时氨清除不足的主要原因是","o":["尿素生成增多","谷氨酰胺合成障碍","鸟氨酸循环障碍","肾小管分泌减少","谷氨酸合成障碍"],"a":2,"e":"氨在肝内经鸟氨酸循环合成尿素而清除，肝性脑病时该循环发生障碍，致氨清除不足、血氨升高。尿素生成增多会促进氨的清除，谷氨酰胺合成和肾小管分泌属次要途径，谷氨酸合成障碍仅影响氨的暂时结合，均非主要原因"},{"q":"早期胃癌是指","o":["黏膜内癌","未侵及肌层的癌","黏膜下癌","无淋巴结转移的癌","未侵及基底膜的癌"],"a":1,"e":"早期胃癌指癌组织限于黏膜层或黏膜下层、未侵及肌层，与有无淋巴结转移无关。黏膜内癌和黏膜下癌仅为其亚型，未侵及基底膜是原位癌，无淋巴结转移不是判定标准，故未侵及肌层最为准确"},{"q":"下列肿瘤中，属于间叶组织肿瘤的是","o":["基底细胞癌","视网膜母细胞瘤","淋巴管瘤","恶性黑色素瘤","囊腺瘤"],"a":2,"e":"淋巴管瘤起源于淋巴管，属间叶组织良性肿瘤。基底细胞癌、视网膜母细胞瘤和恶性黑色素瘤起源于上皮或神经外胚层，囊腺瘤为腺上皮来源，均非间叶组织肿瘤"},{"q":"急性弥漫性增生性肾小球肾炎肾小球的形态学改变不包括","o":["毛细血管球细胞数量增加","内皮细胞增生","单核细胞和中性粒细胞浸润","系膜细胞增生","毛细血管腔扩张充血"],"a":4,"e":"急性弥漫性增生性肾小球肾炎以毛细血管球内皮细胞和系膜细胞增生、中性粒细胞与单核细胞浸润为特点，增生的细胞压迫毛细血管腔使其狭窄甚至闭塞。毛细血管腔扩张充血并非其改变，反与病理特征相反"},{"q":"肾小球肾炎是以肾小球损害为主的","o":["变态反应性疾病","营养缺乏性疾病","遗传性疾病","先天性疾病","精神性疾病"],"a":0,"e":"肾小球肾炎是以肾小球损害为主的变态反应性疾病，多由抗原抗体复合物沉积或抗基底膜抗体介导引起。营养缺乏、遗传、先天和精神因素均不是肾小球肾炎的主要发病机制"},{"q":"肝功能不全引起低钾血症的主要原因是","o":["机体利用钾增多","钾向细胞内转移","醛固酮增加，钾排出增多","稀释性低钾血症","钾的摄入减少"],"a":2,"e":"肝功能不全时醛固酮灭活减少、血中醛固酮增多，促进远曲小管排钾，是低钾血症的主要原因。机体利用钾增多、钾向细胞内转移、稀释性低钾和摄入减少虽可致低钾，但均非肝功能不全的主要机制"},{"q":"下列哪一项不是引起低渗性脱水的原因","o":["长期连续使用利尿剂","呕吐、腹泻","肾上腺皮质功能亢进","大面积烧伤","慢性间质性肾炎"],"a":2,"e":"低渗性脱水因失钠多于失水，见于长期使用利尿剂、呕吐腹泻、大面积烧伤和慢性间质性肾炎等肾性或肾外失钠情况。肾上腺皮质功能亢进时醛固酮增多、保钠排钾，不易引起失钠性脱水"},{"q":"引起高镁血症最常见的原因是","o":["肾功能衰竭","摄镁过多","PTH分泌增多","醛固酮分泌减少","甲状腺功能减退"],"a":0,"e":"镁主要经肾脏排泄，肾功能衰竭时排镁减少，是高镁血症最常见的原因。摄镁过多、甲状腺功能减退和醛固酮分泌减少可致血镁升高，但远不如肾衰常见；PTH分泌增多虽促进镁重吸收，亦非首要原因"},{"q":"DIC导致器官功能障碍的主要原因是","o":["微血栓形成致脏器缺血","继发性纤溶亢进致脏器出血","代谢性酸中毒","FDP生成","裂体细胞增多"],"a":0,"e":"DIC时微循环中广泛微血栓形成，阻塞血管导致脏器缺血、缺氧和功能障碍，是器官损害的主要原因。继发性纤溶亢进和FDP生成主要引起出血，裂体细胞为微血管病性溶血的表现，代谢性酸中毒是后果而非主要原因"},{"q":"鼻咽癌最好发鼻咽部的","o":["外侧壁","前壁","咽隐窝","顶部","前壁和咽隐窝"],"a":3,"e":"鼻咽癌最常发生于鼻咽顶部，其次为外侧壁和咽隐窝，前壁最少见。咽隐窝虽为常见部位之一，但发生率低于顶部；外侧壁、前壁及前壁加咽隐窝的组合均非最好发部位"},{"q":"PaCO2轻微升高即可兴奋呼吸中枢，其机制主要是","o":["CO2直接刺激中枢化学感受器","CO2可增加脑脊液H+，进而刺激中枢化学感受器","H+刺激颈动脉体化学感受器","CO2刺激颈动脉体化学感受器","CO2刺激主动脉体化学感受器"],"a":1,"e":"二氧化碳易透过血脑屏障，在脑脊液中与水结合生成氢离子，氢离子刺激中枢化学感受器而兴奋呼吸中枢，故PaCO2轻微升高即可明显兴奋呼吸。二氧化碳直接刺激中枢作用弱，刺激颈动脉体和主动脉体等外周感受器需PaCO2明显升高"},{"q":"引起儿童肾病综合征最常见的原发性肾小球肾炎类型是","o":["急性弥漫性增生性肾小球肾炎","新月体性肾小球肾炎","IgA肾病","微小病变性肾小球病","膜性肾小球病"],"a":3,"e":"微小病变性肾小球病是儿童肾病综合征最常见的原发性肾小球疾病，光镜下肾小球基本正常，电镜下见足细胞足突广泛融合，表现为选择性蛋白尿。急性弥漫性增生性肾炎多呈急性肾炎综合征，新月体性肾炎为急进性，IgA肾病以血尿为主，膜性肾小球病多见于成人"},{"q":"急性肾盂肾炎最有诊断意义的临床表现是","o":["发热、寒战、血液白细胞增多","腰痛、肾区叩击痛","脓尿、菌尿、白细胞管型尿","氮质血症","尿频、尿急、尿痛"],"a":2,"e":"急性肾盂肾炎是肾盂和肾实质的化脓性炎，尿中出现脓尿、菌尿和白细胞管型，提示感染累及肾实质，最具诊断意义。发热寒战、腰痛叩击痛和尿路刺激征虽常见但非特异，氮质血症提示肾功能受损而非诊断依据"},{"q":"来自左心和体循环动脉系统的栓子，随血流运行可阻塞于","o":["肾小静脉","骨静脉","肝静脉","脑小动脉","肺小动脉"],"a":3,"e":"左心和体循环动脉系统的栓子随血流进入体循环动脉，易阻塞脑、肾、脾和下肢等处的小动脉，脑小动脉栓塞可致脑梗死。肺小动脉栓塞的栓子来自右心和体循环静脉，肾小静脉、肝静脉和骨静脉属静脉系统，均非左心栓子的去向"},{"q":"亚急性感染性心内膜炎最常侵犯的部位是","o":["风湿性心内膜炎受累的二尖瓣","先心病室间隔缺损处","梅毒性主动脉炎受累的主动脉瓣膜","动脉粥样硬化受累的主动脉瓣膜","无损伤的心瓣膜"],"a":0,"e":"亚急性感染性心内膜炎多侵犯已有病变的瓣膜，最常见于风湿性心内膜炎受累的二尖瓣和主动脉瓣。室间隔缺损处、梅毒性主动脉炎及动脉粥样硬化受累瓣膜亦可发生但较少，无损伤的正常心瓣膜极少受累"},{"q":"下列哪种病损属于一期梅毒","o":["阴茎硬下疳","梅毒疹","睾丸树胶样肿","脊髓痨","马鞍鼻"],"a":0,"e":"一期梅毒主要表现为硬下疳，多见于阴茎和外阴等处，为无痛性溃疡。梅毒疹属二期梅毒，睾丸树胶样肿为三期梅毒表现，脊髓痨和马鞍鼻亦属晚期梅毒损害，均非一期病变"},{"q":"不符合原发性高血压病病因的描述是","o":["与交感神经兴奋性增强有关","与遗传因素有关","与慢性肾小球肾炎有关","与膳食的高钠低钾有关","与大量饮酒有关"],"a":2,"e":"原发性高血压的病因与遗传因素、交感神经兴奋性增强、高钠低钾膳食及大量饮酒等有关。慢性肾小球肾炎引起的是继发性高血压，不属于原发性高血压的病因，其余各项均为原发性高血压的相关因素"},{"q":"股骨骨折后，出现胸闷、气短、咯血，最常见的原因是","o":["脂肪栓塞","细胞栓塞","血栓栓塞","细菌栓塞","空气栓塞"],"a":0,"e":"股骨等长骨骨折时骨髓脂肪组织破坏，脂肪滴进入血流并栓塞肺血管，出现胸闷、气短和咯血，重者可致呼吸衰竭。血栓栓塞多见于深静脉血栓，空气栓塞与静脉损伤有关，细胞栓塞和细菌栓塞均不符合骨折后的临床表现"},{"q":"在抗GBM抗体介导的新月体性肾小球肾炎，免疫荧光检查IgG会以哪种方式沉积","o":["系膜区沉积","沿基底膜呈颗粒状沉积","上皮下沉积","内皮下沉积","沿基底膜呈线状沉积"],"a":4,"e":"抗GBM抗体介导的新月体性肾小球肾炎，免疫荧光可见IgG沿肾小球基底膜呈连续线状沉积，因抗原即基底膜本身。颗粒状沉积为免疫复合物型肾炎，系膜区、上皮下和内皮下沉积分别对应不同的复合物沉积部位，均非抗GBM抗体的特征"},{"q":"休克肾的主要临床表现不包括","o":["少尿","高血钾","肾性贫血","代谢性酸中毒","血尿素氮升高"],"a":2,"e":"休克肾由肾灌注不足引起急性肾功能衰竭，表现为少尿、高血钾、代谢性酸中毒和血尿素氮升高。肾性贫血是慢性肾脏病因促红细胞生成素减少所致，不属于休克肾的急性表现"},{"q":"艾滋病人继发感染，机会最大的病原微生物是","o":["卡氏肺孢菌","葡萄球菌","病毒","结核杆菌","真菌"],"a":0,"e":"艾滋病患者CD4阳性T细胞显著减少，卡氏肺孢菌是最常见的机会性感染病原体，常引起肺孢子菌肺炎。葡萄球菌、结核杆菌和真菌亦可感染，但机会少于卡氏肺孢菌，病毒并非此处所指的主要机会致病微生物"},{"q":"在肉芽组织内具有收缩功能，又能产生基质和胶原的细胞是","o":["成纤维细胞","中性粒细胞","巨噬细胞","血管内皮细胞","肌母细胞"],"a":0,"e":"成纤维细胞在肉芽组织中合成胶原和基质，其中部分分化为肌成纤维细胞而具有收缩功能，促进创口愈合。中性粒细胞和巨噬细胞主要参与吞噬防御，血管内皮细胞形成新生血管，肌母细胞为骨骼肌前体细胞，均不符合"},{"q":"消化性溃疡病不可能出现的后果是","o":["通过完全再生愈合","出血","穿孔","幽门梗阻","癌变"],"a":0,"e":"消化性溃疡深达肌层，损伤累及腺体和平滑肌，只能通过肉芽组织增生和瘢痕形成而愈合，不能完全再生。出血、穿孔、幽门梗阻和癌变均为其并发症，其中癌变主要见于胃溃疡，均可出现"},{"q":"急性呼吸性酸中毒的主要代偿机制是","o":["肺代偿","肾脏重吸收NaHCO3增多","肾脏泌H＋增多","细胞内缓冲和细胞内外离子交换","肾脏产NH3增多"],"a":3,"e":"急性呼吸性酸中毒时CO2迅速潴留，肾脏代偿需数日才起效，急性期主要靠细胞内缓冲（血红蛋白缓冲）及细胞内外离子交换（H+入细胞、K+出细胞）快速代偿。肾脏泌H＋、重吸收NaHCO3及产NH3均属慢性代偿，需时较长，是常见易混点。肺本身为原发障碍部位，无法承担代偿"},{"q":"尿毒症最常见的症状发生在","o":["神经系统","消化系统","心血管系统","呼吸系统","免疫系统"],"a":0,"e":"尿毒症时尿素、肌酐等毒性物质蓄积，最先且最常累及神经系统，表现为疲乏、失眠、淡漠、意识障碍乃至尿毒症脑病。消化系统症状如恶心、呕吐虽常见，但并非最早最常见；心血管、呼吸、免疫系统损害多属病程后期表现"},{"q":"发生收缩性心力衰竭时心室射血分数","o":["增加","减少","不变","先增加后减少","先减少后增加"],"a":1,"e":"收缩性心衰因心肌收缩力减弱，心室收缩末期容积增大，每搏输出量下降，射血分数（每搏量/舒张末期容积）减小，是收缩功能障碍的核心指标。增加见于高动力状态；不变、先增后减、先减后增均不符合收缩功能持续受损的特点"},{"q":"干酪样肺炎的病理变化特点不包括","o":["病变肺组织实变","病变肺组织切面淡黄色","可形成结核球","可形成空洞","镜下可见大片干酪样坏死灶"],"a":2,"e":"干酪样肺炎为结核杆菌引起的渗出坏死性炎，病变肺组织实变，切面呈淡黄色干酪样，镜下见大片干酪样坏死灶，可液化形成空洞。结核球是局限性干酪样坏死灶被纤维包裹形成的球形病灶，属另一类型，并非干酪样肺炎的病变特点，故不包括"},{"q":"慢性肾盂肾炎的肾脏病变不会出现","o":["肾小管内充满均质红染物质，形似甲状腺滤泡","肾小球纤维化、玻璃样变","双肾大小不等","肾表面有不规则瘢痕形成","颗粒性肾固缩"],"a":4,"e":"慢性肾盂肾炎是肾小管间质的慢性化脓性炎，见肾小管内充满均质红染管型形似甲状腺滤泡、肾小球纤维化玻璃样变、双肾大小不等及表面不规则瘢痕。颗粒性肾固缩是弥漫性肾小球肾炎的表现，肾盂肾炎形成的是不规则瘢痕肾，二者不同，故不会出现"},{"q":"上消化道出血诱发肝性脑病的主要机制是","o":["引起失血性休克","血液经肠道细菌作用而产生氨","脑组织缺血缺氧","破坏血脑屏障，假性神经递质入脑","血液苯乙胺和酪胺增加"],"a":1,"e":"上消化道出血时血液进入肠道，血红蛋白经肠道细菌分解产生大量氨，氨吸收入血后入脑引发肝性脑病，这是最主要机制。失血性休克、脑缺血缺氧为非特异诱因；假性神经递质及苯乙胺、酪胺增多属另一学说，并非出血诱发的主要途径"},{"q":"糖尿病肾脏损害，最常见的是","o":["弥漫性肾小球硬化","肾小管-间质性损害","细动脉硬化","肾乳头坏死","结节性肾小球硬化"],"a":0,"e":"糖尿病肾病最常见的病理改变是弥漫性肾小球硬化，表现为系膜基质弥漫性增多、基底膜增厚，临床出现蛋白尿。结节性肾小球硬化虽具特征性但较少见；肾小管间质损害、细动脉硬化、肾乳头坏死均可发生，但都不是最常见类型"},{"q":"冠状动脉粥样硬化不会引起","o":["心肌缺血","心肌脂肪浸润","心肌间出血","心肌纤维化","心肌变性坏死"],"a":1,"e":"冠状动脉粥样硬化致心肌缺血，可引起心肌变性、坏死（梗死）、纤维化及心肌间出血。心肌脂肪浸润是心外膜下脂肪组织向心肌间质伸入，属脂肪浸润，与冠脉粥样硬化无直接因果关系，是本题的否定项"},{"q":"下列细胞中，哪一种细胞无再生能力","o":["鳞状上皮细胞","间皮细胞","肝细胞","平滑肌细胞","神经元细胞"],"a":4,"e":"神经元属永久性细胞，出生后不再分裂，损伤后由胶质细胞增生修复，无再生能力。鳞状上皮、间皮为被覆上皮，肝细胞、平滑肌细胞属稳定细胞，均保留较强再生能力，受损后可再生修复"},{"q":"慢性支气管炎最常见的并发症是","o":["肺炎","肺脓肿","支气管扩张症","肺气肿","肺结核"],"a":3,"e":"慢性支气管炎长期气道阻塞、细支气管壁破坏，使肺泡壁断裂融合，最常并发阻塞性肺气肿。支气管扩张症、肺脓肿、肺炎、肺结核也可发生，但都不如肺气肿常见，肺气肿是慢支最主要、最常见的结局"},{"q":"不符合漏出液特点的是","o":["液体静置后不凝固","液体比重低","液体内蛋白含量低","液体内细胞数较少","液体混浊，可为脓性或血性"],"a":4,"e":"漏出液因非炎症因素（血浆胶体渗透压降低、静脉回流受阻）形成，蛋白含量低、比重低、细胞少、静置不凝固且清亮透明。液体混浊、脓性或血性是渗出液特点，见于炎症、感染或肿瘤，故不符合漏出液"},{"q":"I型呼吸衰竭造成机体损害的始动发病环节是","o":["低氧血症","酸碱平衡紊乱","高碳酸血症","血氯降低","血钾升高"],"a":0,"e":"I型呼吸衰竭仅有低氧血症而无高碳酸血症，其机体损害的始动环节是低氧血症，导致全身组织器官缺氧。高碳酸血症是II型呼衰表现；酸碱平衡紊乱、血氯降低、血钾升高均为继发改变，并非始动因素"},{"q":"若SB正常，且AB>SB，则表明可能存在","o":["代谢性碱中毒","AG增高型代谢性酸中毒","AG正常型代谢性酸中毒","呼吸性碱中毒","急性呼吸性酸中毒"],"a":4,"e":"SB正常而AB大于SB，说明CO2潴留使AB升高，肾脏尚未来得及代偿、SB仍正常，符合急性呼吸性酸中毒。代谢性碱中毒时AB、SB均升高且SB不正常；呼吸性碱中毒则AB小于SB，均不符"},{"q":"溃疡病上腹部节律性疼痛的原因是","o":["胃痉挛","食物滞留发酵","胃酸刺激溃疡局部神经末梢","肠梗阻","弥漫性腹膜炎"],"a":2,"e":"溃疡病节律性疼痛是胃酸分泌高峰时，胃酸刺激溃疡底部及边缘暴露的神经末梢所致，呈进食—疼痛—缓解的节律。胃痉挛、食物滞留发酵可加重不适但非节律性主因；肠梗阻、弥漫性腹膜炎为并发症，表现为持续剧痛而非节律性痛"},{"q":"梅毒的致病病原体是","o":["病毒","霉菌","衣原体","螺旋体","支原体"],"a":3,"e":"梅毒由梅毒螺旋体（苍白螺旋体）感染引起，病原体属螺旋体。病毒、霉菌（真菌）、衣原体、支原体分别引起其他感染性疾病，均非梅毒的病原体"},{"q":"动脉粥样硬化的危险因素不包括","o":["吸烟","糖尿病","高血压","高脂血症","中枢神经系统功能紊乱"],"a":4,"e":"动脉粥样硬化的明确危险因素为高脂血症、高血压、吸烟、糖尿病等。中枢神经系统功能紊乱不是公认危险因素，是本题否定项；其余四项均为促进动脉粥样硬化发生发展的重要危险因素"},{"q":"自由基引起细胞膜损伤，主要是由于","o":["自由基引起核酸断裂","自由基使多糖发生氧化","自由基引发脂质过氧化","自由基催化氨基酸氧化","自由基与蛋白质发生交联"],"a":2,"e":"自由基主要攻击细胞膜上的多不饱和脂肪酸，引发脂质过氧化链式反应，破坏膜结构与功能，这是细胞膜损伤的主要机制。核酸断裂、多糖氧化、氨基酸氧化及蛋白质交联也可发生，但都不是膜损伤的主要原因"},{"q":"下列哪项因素与心肌收缩功能降低无关","o":["心肌细胞死亡","心肌细胞肥大","ATP生成不足","肌浆网释放Ca2+减少","细胞外Ca2+内流受阻"],"a":1,"e":"心肌细胞肥大是心肌对负荷增加的适应性反应，早期收缩功能可维持甚至增强，并非直接导致收缩功能降低的因素。心肌细胞死亡、ATP生成不足、肌浆网释放Ca2+减少、细胞外Ca2+内流受阻均直接削弱心肌收缩能力"},{"q":"下列描述不符合急性感染性心内膜炎的是","o":["瓣膜赘生物体积大、污秽、易脱落","常伴有败血症","多发生于已有病变的心瓣膜","表现为急性化脓性炎","可引起心瓣膜穿孔，溃疡形成"],"a":2,"e":"急性感染性心内膜炎多由毒力强的化脓菌引起，常侵犯正常心瓣膜，赘生物大、污秽、易脱落，伴败血症，呈急性化脓性炎，可致瓣膜穿孔溃疡。多发生于已有病变的心瓣膜是亚急性感染性心内膜炎的特点，不符合急性"},{"q":"下列有关血栓形成的论述，错误的是","o":["下肢血栓多于上肢血栓","静脉血栓多于动脉血栓","延续性血栓尾部多为红色血栓","动脉瘤内血栓多为混合血栓","毛细血管内血栓多为白色血栓"],"a":4,"e":"毛细血管内血栓主要是微血栓，由纤维蛋白构成，属透明血栓。白色血栓多见于动脉及心瓣膜，由血小板构成；静脉延续性血栓尾部为红色血栓，动脉瘤内多为混合血栓；下肢血栓多于上肢、静脉血栓多于动脉，均正确"},{"q":"应激时，血浆中某些蛋白质浓度迅速变化，这类蛋白质被称为","o":["热休克蛋白","急性期反应蛋白","血浆铜蓝蛋白","纤维连接蛋白","C反应蛋白"],"a":1,"e":"应激时血浆中某些蛋白质浓度迅速改变，这类蛋白称急性期反应蛋白，如C反应蛋白、纤维蛋白原。热休克蛋白为细胞内应激蛋白而非血浆蛋白；血浆铜蓝蛋白、纤维连接蛋白只是具体成员，C反应蛋白仅为其中一种，不能概括整类"},{"q":"病毒性肺炎的病理变化不包括","o":["肺间质充血水肿","淋巴细胞和巨噬细胞浸润","肺泡腔内透明膜形成","病毒包涵体","干酪样坏死灶"],"a":4,"e":"病毒性肺炎表现为肺间质充血水肿，淋巴细胞和巨噬细胞浸润，肺泡腔内可形成透明膜，并可见病毒包涵体。干酪样坏死灶是结核病的特征性病变，不属于病毒性肺炎的病理变化，故不包括"},{"q":"非肾性因素引起的高渗性脱水对机体的影响不包括","o":["口渴","细胞内液向细胞外液转移","细胞外液容量增加","尿少，尿比重增加","醛固酮和ADH分泌增加"],"a":2,"e":"高渗性脱水时失水多于失钠，细胞外液渗透压升高，水由细胞内移向细胞外，但总体液量减少，细胞外液容量并不增加，反而减少。口渴、细胞内外转移、尿少尿比重升高、醛固酮和ADH分泌增加均为其表现"},{"q":"判断酸碱平衡紊乱是否为代偿性的指标是","o":["SB","AB","pH","BE","PaCO2"],"a":2,"e":"代偿与否的判断在于pH是否正常：pH在正常范围说明经代偿酸碱已恢复，属完全代偿；pH异常则为失代偿。SB、AB、BE、PaCO2只是反映代谢或呼吸因素的具体指标，单独不能判断是否代偿"},{"q":"以变质为主的炎症病灶中，实质细胞的主要变化是","o":["增生和变性","变性和坏死","增生和再生","坏死和萎缩","萎缩和变性"],"a":1,"e":"变质是以实质细胞变性、坏死为主的炎症改变，故实质细胞主要表现为变性和坏死，如水肿、脂肪变及坏死。增生、再生属增生性改变；萎缩为适应性改变，均不是变质性炎的主要变化"},{"q":"细胞老化时，胞浆内常有下列哪种物质沉积","o":["钙盐","胆红素","脂褐素","含铁血黄素","黑色素"],"a":2,"e":"细胞老化时胞质内可见脂褐素（老年色素）沉积，为自噬溶酶体内未被消化的细胞器碎片残体，随年龄增多。钙盐沉积为钙化，含铁血黄素为出血后铁沉积，胆红素、黑色素各有特定来源，均非细胞老化的特征"},{"q":"影响肿瘤生长速度的因素不包括","o":["肿瘤细胞生长分数","肿瘤细胞倍增时间","肿瘤细胞生成与死亡","肿瘤内血管形成","肿瘤细胞组织来源"],"a":4,"e":"肿瘤生长速度取决于生长分数、倍增时间、细胞生成与死亡之比以及肿瘤内血管形成。肿瘤细胞的组织来源决定肿瘤类型和分化方向，与生长速度无直接关系，故为例外项"},{"q":"下述导致呼吸衰竭的原因中，属于限制性通气不足的是","o":["中央气道阻塞","外周气道阻塞","肺泡膜面积减少","胸廓顺应性降低","弥散膜厚度增加"],"a":3,"e":"限制性通气不足因肺或胸廓顺应性降低、呼吸肌活动障碍使肺扩张受限所致，胸廓顺应性降低属此类。中央与外周气道阻塞属阻塞性通气不足；肺泡膜面积减少、弥散膜厚度增加属弥散障碍"},{"q":"发热患者体温下降期可出现","o":["Na+潴留","Cl-潴留","水潴留","脱水","出汗减少"],"a":3,"e":"体温下降期（退热期）通过大量出汗散热，汗液丢失可导致脱水，严重时伴电解质紊乱。Na+、Cl-潴留和水潴留是高热持续期的表现；出汗减少与退热期出汗增多相悖，均非本期的改变"},{"q":"下列关于肿瘤大体形态的描述，正确的是","o":["肿瘤通常为多发","小的肿瘤一般是良性的","肿瘤只有在显微镜下才可观察","肿瘤的大小与肿瘤的性质、发生部位等有关","巨大肿瘤都是恶性的"],"a":3,"e":"肿瘤大小与肿瘤性质、发生部位、生长时间等有关，这是正确描述。肿瘤通常为单发而非多发；小的肿瘤不一定是良性；大体标本肉眼可见，并非只在显微镜下才能观察；巨大肿瘤也不一定都是恶性"},{"q":"判断肿瘤良恶性最可靠的依据是","o":["生长部位","生长时间","肿瘤大小","分化程度","有无核分裂象"],"a":3,"e":"分化程度是判断肿瘤良恶性最可靠的依据，分化越接近正常组织越倾向良性，分化越差、异型性越大越倾向恶性。生长部位、时间、大小的参考价值有限；有无核分裂象虽有意义，但不能单凭它定论，须综合分化程度"},{"q":"甲状腺瘤与甲状腺肿的区别是","o":["前者有完整包膜，压迫周围组织","前者滤泡大小不一","前者发生于青年女性","前者可伴发甲亢","前者可有大量胶质贮积"],"a":0,"e":"甲状腺瘤（腺瘤）为良性肿瘤，有完整包膜，生长时压迫周围甲状腺组织，与周围分界清楚。甲状腺肿为弥漫性增生，无包膜、不压迫周围组织。滤泡大小不一、伴甲亢、大量胶质贮积在结节性甲状腺肿中也可见，并非本质区别"},{"q":"ARDS病人发生呼吸衰竭的主要机制是","o":["渗透性肺水肿","肺顺应性降低","肺泡通气血流比例失调","中央性气道阻塞","小气道阻塞"],"a":2,"e":"ARDS因肺泡—毛细血管膜损伤导致渗透性肺水肿和肺不张，部分肺泡通气不足而血流仍通过，形成肺内分流，通气/血流比例失调是呼吸衰竭的主要机制。渗透性肺水肿、肺顺应性降低为病理基础，但导致缺氧的核心环节是比例失调"},{"q":"关于肝硬化晚期腹水的形成原因，下列哪一项是错误的","o":["侧支循环形成","肝窦内压升高","肝细胞合成蛋白功能低下","抗利尿激素、醛固酮在血内水平增高","肝淋巴液滤入腹腔"],"a":0,"e":"肝硬化腹水形成与肝窦内压升高、肝细胞合成白蛋白低下使胶体渗透压降低、抗利尿激素和醛固酮升高致水钠潴留、肝淋巴液滤入腹腔有关。侧支循环形成是门脉高压的结果，主要引起食管胃底静脉曲张，并非腹水形成的直接原因"},{"q":"肾盂肾炎的炎症性质是","o":["变质性炎","浆液性炎","化脓性炎","纤维素性炎","增生性炎"],"a":2,"e":"肾盂肾炎是细菌感染肾小管及肾盂黏膜引起的化脓性炎，以中性粒细胞浸润为主，可形成脓肿。变质性炎、浆液性炎、纤维素性炎、增生性炎均不是其炎症性质，化脓性炎才是本质"},{"q":"关于炎性渗出，下列描述中错误的是","o":["渗出液体潴留于浆膜腔时，称为炎性积液","渗出液不能自行凝固","渗出液对机体具有防御意义","纤维素性渗出物若吸收不全可发生机化，引起粘连","液体渗出早于细胞成分的渗出"],"a":1,"e":"渗出液含较多纤维蛋白原和细胞，静置后可自行凝固，故“不能自行凝固”的说法错误，不凝固是漏出液特点。渗出液潴留浆膜腔称炎性积液，有防御意义，纤维素机化可致粘连，液体渗出早于细胞渗出，均正确"},{"q":"血吸虫急性虫卵结节中的Charcot-Leyden结晶来源于","o":["中性粒细胞","淋巴细胞","巨噬细胞","嗜酸性粒细胞","肥大细胞"],"a":3,"e":"血吸虫急性虫卵结节中Charcot-Leyden结晶是嗜酸性粒细胞崩解后，其胞质颗粒形成的菱形结晶。中性粒细胞、淋巴细胞、巨噬细胞、肥大细胞均不产生此结晶，故来源是嗜酸性粒细胞"},{"q":"急性炎症时导致局部组织肿胀的最主要原因是","o":["血流加速","静脉阻塞","充血渗出","组织增生","组织坏死崩解"],"a":2,"e":"急性炎症时细动脉扩张充血、血管通透性升高，液体和细胞渗出到组织间隙形成炎性水肿，是局部肿胀最主要的原因。血流加速、静脉阻塞为伴随改变；组织增生属慢性炎症表现；组织坏死崩解不是肿胀主因"},{"q":"局部组织、器官内动脉血输入量增多的状态称","o":["出血","水肿","淤血","充血","栓塞"],"a":3,"e":"局部组织或器官内动脉血输入量增多称充血，即动脉性充血。淤血是静脉回流受阻致血液淤积；出血为血液流出血管外；水肿为组织间隙液体积聚；栓塞为异物阻塞血管，均非动脉血输入增多"},{"q":"内脏器官的坏死组织经自然管道排出后，留下的空腔称为","o":["瘘","窦","溃疡","空洞","糜烂"],"a":3,"e":"内脏器官坏死组织液化后经自然管道（如支气管、输尿管）排出，留下的空腔称空洞。窦是深部组织通向体表的盲管；瘘为连接两空腔器官或器官与体表的管道；溃疡为皮肤黏膜表面缺损；糜烂为浅表缺损，均不同"},{"q":"慢性肾小球肾炎时，与高血压的发生密切相关的激素是","o":["肾上腺素","糖皮质激素","肾素","前列腺素","血管紧张素"],"a":2,"e":"慢性肾小球肾炎时肾缺血刺激球旁细胞分泌肾素，激活肾素—血管紧张素—醛固酮系统，引起血管收缩和水钠潴留，是肾性高血压的关键。肾上腺素、糖皮质激素、前列腺素无关；血管紧张素虽参与，但始动和关键调节激素是肾素"},{"q":"过量使用胰岛素引起低钾血症的机制是","o":["促进肾脏对钾的排泄","结肠分泌钾增加","促进细胞外钾离子向细胞内转移","肾小管重吸收钾减少","促进醛固酮的分泌"],"a":2,"e":"胰岛素促进细胞摄取葡萄糖，同时激活Na+-K+-ATP酶，使细胞外钾转入细胞内，导致血钾降低。胰岛素并不促进肾脏排钾、结肠分泌钾或醛固酮分泌，反而可轻度减少肾排钾，故细胞内转移是关键机制"},{"q":"一种分化成熟的细胞类型被另一种分化成熟的细胞类型所替代的过程，称为","o":["化生","分化","机化","再生","增生"],"a":0,"e":"化生是一种已分化成熟的细胞类型被另一种分化成熟的细胞类型所替代的过程，如支气管鳞状上皮化生。分化是细胞发育成熟过程；机化为坏死组织被肉芽组织取代；再生为损伤后修复；增生为细胞数量增多，均不符"},{"q":"风湿性关节炎不引起的病变是","o":["关节积液","关节红肿","关节活动受限","关节软骨破坏","关节疼痛"],"a":3,"e":"风湿性关节炎主要表现为滑膜的浆液性炎，有关节红肿、疼痛、积液和活动受限，但一般不破坏关节软骨，愈后不留畸形。关节软骨破坏是类风湿关节炎的特点，二者易混，故风湿性关节炎不引起此病变"},{"q":"发生动脉粥样硬化的血管主要是","o":["细动脉","小动脉","细、小动脉","大、中型动脉","中等动脉"],"a":3,"e":"动脉粥样硬化主要发生于大、中型动脉，如主动脉、冠状动脉、颈动脉、股动脉等。细动脉、小动脉及细、小动脉主要发生高血压相关的细动脉硬化，中等动脉不如大中动脉典型，均非本病主要部位"},{"q":"静脉石是指","o":["静脉内钙盐沉积","静脉血栓钙盐沉积","静脉血栓","静脉血栓机化","静脉内胆盐沉积"],"a":1,"e":"静脉石是静脉内血栓发生钙盐沉积（钙化）形成的坚硬结石，多见于下肢静脉。静脉内单纯钙盐沉积、静脉血栓、血栓机化都不是静脉石的定义；胆盐沉积更与静脉石无关"},{"q":"流行性出血热主要的宿主和传染源是","o":["鸡","鼠","猫","猪","狗"],"a":1,"e":"流行性出血热（肾综合征出血热）由汉坦病毒引起，主要宿主和传染源是鼠类，如黑线姬鼠、褐家鼠。鸡、猫、猪、狗均不是本病的主要宿主和传染源"},{"q":"肾病综合征的主要临床症状不包括","o":["大量蛋白尿","低白蛋白血症","高度水肿","高脂血症","高血压"],"a":4,"e":"肾病综合征的四大表现为大量蛋白尿、低白蛋白血症、高度水肿、高脂血症。高血压不是其基本特征，多见于肾炎综合征或作为并发症出现，故不包括在主要临床症状内"},{"q":"抑制细胞凋亡的基因是","o":["Fas","Bcl-2","野生型p53","Bax","Rb"],"a":1,"e":"Bcl-2是经典的抑制凋亡基因，通过稳定线粒体膜、阻止细胞色素C释放而抑制凋亡。Fas为死亡受体、野生型p53、Bax均促进凋亡；Rb为抑癌基因，主要调控细胞周期，并非抑制凋亡的主体"},{"q":"血气分析反映酸碱平衡呼吸性因素的关键指标是","o":["BE","PaCO2","AB","SB","BB"],"a":1,"e":"PaCO2反映肺泡通气状况，是酸碱平衡中呼吸性因素的关键指标，升高提示呼吸性酸中毒，降低提示呼吸性碱中毒。BE、SB、BB属代谢性指标；AB受呼吸和代谢双重影响，均非呼吸性因素的关键指标"},{"q":"严重低钾血症引起机体死亡的主要原因是","o":["碱中毒","肠麻痹","肾功能衰竭","心肌收缩性减弱","呼吸肌麻痹"],"a":4,"e":"严重低钾血症使神经肌肉兴奋性降低，可发生呼吸肌麻痹导致窒息死亡，是最严重的致死原因，也可因心律失常致死。碱中毒、肠麻痹、肾功能衰竭、心肌收缩性减弱虽为低钾表现，但都不是主要致死原因"},{"q":"高钙血症对机体的影响不包括","o":["神经肌肉兴奋性下降","肾小管损伤","心肌兴奋性和传导性升高","转移性钙化","低镁血症"],"a":2,"e":"高钙血症使神经肌肉兴奋性下降、肾小管损伤、转移性钙化，并可伴低镁血症；对心肌则使兴奋性和传导性降低，而非升高，故“升高”不属于其影响。高钙确可致心律失常，但方向是兴奋性和传导性降低"},{"q":"循环性缺氧导致细胞缺氧的机制","o":["动脉氧分压降低","单位时间内毛细血管血量减少","血氧容量降低","血液氧饱和度降低","Hb氧饱和度为50%的时候氧分压降低"],"a":1,"e":"循环性缺氧因休克、心衰、血管阻塞等循环障碍，使单位时间内流经毛细血管的血量减少，组织供氧不足。动脉氧分压降低属低张性缺氧；血氧容量降低属血液性缺氧；氧饱和度降低也不是循环性缺氧的机制"},{"q":"下列关于肿瘤发生分子机制的描述，错误的是","o":["点突变导致的原癌基因激活最常见的类型是碱基替换","乳腺癌中HER2的扩增提示患者预后不良","抑癌基因功能丧失可导致肿瘤的发生","凋亡在肿瘤发生、发展过程中具有双重作用","绝大多数恶性肿瘤细胞都含有较低的端粒酶活性"],"a":4,"e":"绝大多数恶性肿瘤细胞端粒酶活性高而非低，借此维持端粒长度获得无限增殖能力，故该描述错误。原癌基因点突变以碱基替换最常见、HER2扩增提示乳腺癌预后不良、抑癌基因失活致肿瘤、凋亡具双重作用，均正确"},{"q":"葡萄球菌感染灶内浸润的炎症细胞主要是","o":["单核细胞","中性粒细胞","嗜酸性粒细胞","淋巴细胞","嗜碱性粒细胞"],"a":1,"e":"葡萄球菌为化脓性细菌，感染灶内以中性粒细胞浸润为主，属急性化脓性炎。单核细胞、淋巴细胞多见于病毒或慢性感染；嗜酸性粒细胞见于过敏及寄生虫感染；嗜碱性粒细胞少见，均非主要浸润细胞"},{"q":"透壁性心肌梗死的好发部位是","o":["左室后壁","右心室","左室侧壁","室间隔","左室前壁及心尖部"],"a":4,"e":"透壁性心肌梗死最常见于左室前壁及心尖部，多由冠状动脉前降支阻塞引起。左室后壁、左室侧壁、室间隔、右心室也可发生梗死，但发生率均低于左室前壁及心尖部"},{"q":"肝性脑病的正确概念是","o":["肝功能衰竭所致的神经精神综合征","肝脏疾病并发脑部疾病","肝功能衰竭并发脑水肿","肝功能衰竭所致昏迷","肝功能衰竭所致的精神紊乱性疾病"],"a":0,"e":"肝性脑病是严重肝病或肝功能衰竭引起的，以代谢紊乱为基础、以神经精神症状为主要表现的综合征，涵盖从轻微性格改变到昏迷的连续过程。仅称昏迷或精神紊乱都不全面；也不是肝脏疾病并发的独立脑病，不一定伴脑水肿"},{"q":"电镜观察毛玻璃样肝细胞，HBsAg主要存在于","o":["滑面内质网","粗面内质网","线粒体","高尔基体","溶酶体"],"a":0,"e":"毛玻璃样肝细胞胞质内HBsAg大量积聚，电镜下主要位于滑面内质网，光镜下胞质呈毛玻璃状。粗面内质网、线粒体、高尔基体、溶酶体都不是HBsAg的主要积聚部位，故滑面内质网为正确答案"},{"q":"近曲小管重吸收功能障碍可导致","o":["多尿、低渗尿","蛋白尿、血尿","管型尿","肾小管性酸中毒","肾性尿崩症"],"a":3,"e":"近曲小管重吸收HCO3-障碍可导致近端型肾小管性酸中毒。多尿、低渗尿及肾性尿崩症主要与集合管、远曲小管浓缩功能障碍有关；蛋白尿、血尿、管型尿多为肾小球疾病表现，均非近曲小管重吸收障碍的直接后果"},{"q":"参与瘢痕修复过程最重要的细胞是","o":["上皮细胞","渗出的白细胞","单核巨噬细胞","血管内皮细胞","成纤维细胞"],"a":4,"e":"瘢痕修复以肉芽组织为基础，成纤维细胞合成并分泌胶原纤维，是形成瘢痕最重要的细胞。上皮细胞参与创面覆盖；渗出的白细胞、单核巨噬细胞参与炎症和清创；血管内皮细胞形成新生毛细血管，均非瘢痕形成的核心"},{"q":"下列情况中，可导致限制性通气障碍的是","o":["声带麻痹","支气管炎","胸膜增厚","气管异物","肺通气/血流比例失调"],"a":2,"e":"胸膜增厚限制肺的扩张，使肺顺应性降低，属限制性通气障碍。声带麻痹、气管异物属阻塞性通气障碍；支气管炎影响气道通畅；肺通气/血流比例失调属换气障碍，均非限制性通气障碍"},{"q":"I型呼吸衰竭与II型呼吸衰竭血气变化的差异主要在于","o":["是否出现肺泡气氧分压变化","是否出现动脉血氧分压变化","是否出现静脉血氧分压变化","是否出现静脉血二氧化碳分压变化","是否出现动脉血二氧化碳分压变化"],"a":4,"e":"I型呼衰仅有动脉血氧分压降低而PaCO2正常或降低；II型呼衰同时有低氧血症和PaCO2升高。故二者差异在于是否出现动脉血二氧化碳分压变化，与肺泡气、静脉血氧分压及静脉血二氧化碳分压无关"},{"q":"槟榔肝的形成是因为","o":["肝细胞脂肪变性和肝细胞坏死","肝细胞脂肪变性和肝窦淤血","肝细胞脂肪变性和结缔组织增生","肝窦出血和肝细胞坏死","肝窦淤血和出血"],"a":1,"e":"槟榔肝见于慢性肝淤血，肝小叶中央静脉及周围肝窦淤血呈暗红色，周边肝细胞因缺氧发生脂肪变呈黄色，红黄相间形似槟榔切面。肝细胞坏死、出血、结缔组织增生均不是槟榔肝的典型构成"},{"q":"低镁血症可引起心律失常，主要是通过","o":["兴奋性和自律性降低","兴奋性升高和自律性降低","兴奋性降低和自律性增高","兴奋性和自律性升高","兴奋性和传导性降低"],"a":3,"e":"低镁血症时Mg2+对Na+内流的阻滞作用减弱，使心肌兴奋性和自律性升高，易发生心律失常。兴奋性和自律性降低、兴奋性降低而自律性增高、传导性降低都不符合低镁血症的心电生理改变"},{"q":"我国最常见的性病是","o":["淋病","尖锐湿疣","梅毒","AIDS","软性下疳"],"a":0,"e":"我国法定报告的传染病中，淋病发病率长期居性病首位，是最常见的性病。尖锐湿疣、梅毒、AIDS、软性下疳的发病率均低于淋病，故淋病为我国最常见性病"},{"q":"急性细菌性痢疾假膜脱落发生于","o":["发病后1周左右","发病后2周左右","发病后3周左右","发病后4周左右","发病后5周左右"],"a":0,"e":"急性细菌性痢疾早期为急性卡他性炎，随后形成纤维素性假膜，约在发病后1周假膜脱落形成地图状溃疡，出现典型脓血便。其余时间点与假膜脱落的典型病程不符"},{"q":"多发生于儿童的NHL是","o":["CLL/SLL","PTCL-NOS","DLBCL","B-ALL","T-ALL"],"a":3,"e":"B-ALL（B细胞急性淋巴细胞白血病/淋巴母细胞淋巴瘤）是儿童最常见的类型，多发生于儿童。CLL/SLL、PTCL-NOS多见于成人；DLBCL以中老年多见；T-ALL发病率低于B-ALL"},{"q":"体内碱性物质的主要来源是","o":["柠檬酸盐","蔬菜和水果中的有机酸盐","苹果酸盐","氨基酸脱氨后生成的氨","草酸盐"],"a":1,"e":"体内碱性物质主要来自蔬菜和水果中的有机酸盐，如柠檬酸盐、苹果酸盐、草酸盐，它们代谢后生成HCO3-，使尿液碱化。氨基酸脱氨生成的氨属酸性物质来源；其余选项只是具体的有机酸盐，不能概括主要来源"},{"q":"下列恶性肿瘤中，好发于儿童的是","o":["横纹肌肉瘤","脂肪肉瘤","恶性黑色素瘤","皮肤鳞状细胞癌","平滑肌肉瘤"],"a":0,"e":"横纹肌肉瘤是儿童最常见的软组织肉瘤，多见于儿童及青少年。脂肪肉瘤、恶性黑色素瘤、皮肤鳞状细胞癌、平滑肌肉瘤均主要见于成年人，不是好发于儿童的恶性肿瘤"},{"q":"关于纤维素性炎的描述，错误的是","o":["肠黏膜的纤维素性炎可形成假膜","胸膜的纤维素性炎易导致粘连","心外膜的纤维素性炎常形成绒毛心","肺的纤维素性炎不会导致机化","气管的纤维素性炎可导致窒息"],"a":3,"e":"肺的纤维素性炎若纤维素渗出过多、中性粒细胞渗出过少，不能被完全溶解吸收，可发生机化形成肺肉质变，故“不会导致机化”错误。肠黏膜假膜、胸膜粘连、心外膜绒毛心、气管阻塞致窒息均正确"},{"q":"梅毒树胶样肿不同于结核结节是由于","o":["无干酪样坏死","有异物巨细胞","坏死不如结核彻底","周围有淋巴细胞浸润","没有类上皮细胞"],"a":2,"e":"梅毒树胶样肿的坏死不像结核干酪样坏死那样彻底，组织中仍可见组织轮廓和弹力纤维，钙化也少见，这是它与结核结节的主要区别。树胶样肿同样可有类上皮细胞、异物巨细胞及周围淋巴细胞浸润，也可出现类似干酪样坏死"},{"q":"临床上导致低钾血症最常见的原因是","o":["频繁呕吐、腹泻","大量出汗","速尿、利尿酸等的使用","肾上腺皮质功能亢进","碱中毒"],"a":0,"e":"临床上低钾血症最常见于频繁呕吐、腹泻等消化道丢失，消化液含钾丰富，大量丢失使血钾降低。大量出汗、速尿利尿酸等利尿剂、肾上腺皮质功能亢进、碱中毒也可致低钾，但都不如消化道丢失常见"},{"q":"在DIC的高凝期，常用肝素抗凝治疗，其机制是","o":["抑制血小板黏附、聚集","提高抗凝物质的浓度","提高纤溶酶的活性，促进微血栓溶解","阻断凝血酶生成，防止微血栓形成","促进纤维蛋白原降解"],"a":3,"e":"肝素通过增强抗凝血酶Ⅲ活性，抑制凝血因子Ⅱa、Ⅹa等活化，阻断凝血酶生成，从而防止微血栓形成，适用于DIC高凝期。抑制血小板黏附聚集、提高纤溶酶活性、促进纤维蛋白原降解都不是肝素的主要抗凝机制"},{"q":"链球菌感染后肾小球肾炎一般属于","o":["毛细血管内增生性肾小球肾炎","新月体性肾小球肾炎","膜性肾小球病","膜增生性肾小球肾炎","微小病变性肾小球病"],"a":0,"e":"链球菌感染后肾小球肾炎即急性弥漫性增生性肾小球肾炎，病理类型为毛细血管内增生性肾小球肾炎，以内皮细胞和系膜细胞增生为特征，多表现为急性肾炎综合征。新月体性、膜性、膜增生性、微小病变均为其他类型"},{"q":"下列关于骨肉瘤的描述，错误的是","o":["好发人群为青年人","好发于四肢长骨的干骺端","X线下可见Codman三角","一般不引起病理性骨折","生长较快，容易经血道转移到肺"],"a":3,"e":"骨肉瘤生长快、破坏骨组织，也常引起病理性骨折，故“一般不引起病理性骨折”错误。骨肉瘤好发于青年、四肢长骨干骺端，X线可见Codman三角，生长快、易经血道转移到肺，均正确"},{"q":"缺氧性细胞损伤，以下哪一项是错误的","o":["线粒体氧化磷酸化功能降低","溶酶体肿胀、破裂","细胞内ATP含量降低","细胞膜对离子通透性增高，钠内流，钾、钙外流","线粒体嵴断裂崩解"],"a":3,"e":"缺氧时细胞膜通透性增高、钠泵失灵，表现为钠内流、钾外流，但钙是内流造成细胞内钙超载，而非钙外流，故该项错误。线粒体氧化磷酸化降低、溶酶体肿胀破裂、ATP降低、线粒体嵴断裂均正确"},{"q":"下列关于肿瘤对机体影响的表述，错误的是","o":["局部压迫和阻塞是良性肿瘤对机体的主要影响","恶性肿瘤也可引起局部压迫和阻塞的症状","肿瘤因其良恶性、大小及发生部位不同，对机体的影响也不同","恶性肿瘤由于分化不成熟，生长速度快，易浸润转移，常引起严重后果","良性肿瘤由于分化较成熟，生长缓慢，无浸润转移，不会引起严重后果"],"a":4,"e":"良性肿瘤虽分化成熟、生长缓慢、不浸润转移，但长于颅内、心、脊髓等要害部位或分泌大量激素时，也可引起严重后果甚至危及生命，故该项错误。其余关于良恶性肿瘤对机体影响的表述均正确"},{"q":"恶性肿瘤向邻近器官侵犯的主要方式为","o":["淋巴道播散","直接蔓延","血管播散","种植播散","接触播散"],"a":1,"e":"恶性肿瘤向邻近器官组织连续生长侵犯的主要方式是直接蔓延。淋巴道播散、血道播散是远处转移的途径；种植播散为体腔内脏器间的转移；接触播散并非规范术语，均非侵犯邻近器官的主要方式"},{"q":"下列各项促进细胞内钙超载发生的机制中，错误的是","o":["细胞膜损伤","儿茶酚胺减少","Na+-Ca2+交换异常","钙泵功能障碍","线粒体功能障碍"],"a":1,"e":"细胞内钙超载的机制包括细胞膜损伤、Na+-Ca2+交换异常、钙泵功能障碍、线粒体功能障碍等；儿茶酚胺增多而非减少，通过受体促进Ca2+内流参与钙超载，故“儿茶酚胺减少”错误"},{"q":"下列关于类风湿关节炎病理变化的描述，不正确的是","o":["主要表现为增生性滑膜炎","病灶中淋巴细胞主要是CD4+Th细胞","最常累及的关节是大关节","可致关节软骨和关节囊破坏","全身多种器官组织可被累及"],"a":2,"e":"类风湿关节炎最常累及手足小关节，如近端指间关节、掌指关节，呈对称性多关节炎，而非大关节，故该项错误。增生性滑膜炎、CD4+Th细胞浸润、软骨和关节囊破坏、全身多器官受累均正确"},{"q":"呼吸衰竭病人一定伴随的缺氧类型是","o":["低张性缺氧","血液性缺氧","循环性缺氧","组织性缺氧","混合型缺氧"],"a":0,"e":"呼吸衰竭时肺通气或换气功能障碍，必致动脉血氧分压降低，属低张性缺氧，是呼衰必有环节。血液性、循环性、组织性缺氧可由其他原因引起，并非呼衰必有；混合型缺氧也不一定出现"},{"q":"脑动脉粥样硬化成形小动脉瘤最常见于","o":["大脑中动脉","大脑前动脉","大脑后动脉","Willis环","基底动脉"],"a":3,"e":"脑动脉粥样硬化常见于基底动脉、颈内动脉及Willis环，形成的动脉瘤尤其囊状动脉瘤最好发于Willis环的分支处。大脑中动脉、大脑前动脉、大脑后动脉及基底动脉也可发生，但不如Willis环典型"},{"q":"亚急性感染性心内膜炎多不引起","o":["慢性瓣膜病","局灶性肾小球肾炎","败血性梗死","紫癜","脾肿大"],"a":2,"e":"亚急性感染性心内膜炎赘生物较小、不易脱落、毒力较弱，常引起慢性瓣膜病、局灶性肾小球肾炎、紫癜、脾肿大等。败血性梗死由感染性栓子栓塞引起，多见于急性感染性心内膜炎，亚急性多不引起"},{"q":"机体缺血再灌注损伤最常见的器官是","o":["脑","心脏","肺","肾","肠"],"a":1,"e":"缺血再灌注损伤最常发生于心脏，即心肌再灌注损伤，也可见于脑、肾、肠等器官。心肌对缺血缺氧敏感，且溶栓、搭桥等再灌注治疗常见，故心脏是机体缺血再灌注损伤最常见的器官"},{"q":"与Burkitt淋巴瘤有关的病毒是","o":["EB病毒","麻疹病毒","疱疹病毒","腺病毒","HTLV-1"],"a":0,"e":"Burkitt淋巴瘤与EB病毒感染密切相关，尤其非洲儿童型。麻疹病毒、疱疹病毒、腺病毒均非其相关病毒；HTLV-1与成人T细胞白血病/淋巴瘤有关，与Burkitt淋巴瘤无关"},{"q":"碱中毒时出现手足搐搦的主要原因是","o":["血K+降低","血Cl-降低","血Ca2+降低","血Na+降低","血Mg2+降低"],"a":2,"e":"碱中毒时pH升高，血浆游离钙与蛋白结合增多，使血中游离Ca2+降低，神经肌肉兴奋性增高，出现手足搐搦。血K+、Cl-、Na+、Mg2+降低均非手足搐搦发生的直接主要原因"},{"q":"炎性充血主要是指","o":["细动脉扩张导致局部血管内血量增多","静脉回流障碍导致局部血管内血量增多","炎区内的血管、细胞、组织间隙均含血量增多","炎区小血管破裂","血液聚集于浆膜腔"],"a":0,"e":"炎性充血是炎症早期细动脉扩张，使局部血管内血量增多，属动脉性充血，是炎症红、热的基础。静脉回流障碍导致的是淤血；炎区血管、细胞、间隙均含血量增多的说法不准确；血管破裂为出血；血液聚集浆膜腔为积液"},{"q":"下列病变中，不属于癌前疾病（病变）的是","o":["黏膜白斑","乳腺纤维囊性病","病毒性肝炎","慢性萎缩性胃炎","皮肤慢性溃疡"],"a":2,"e":"癌前疾病（病变）包括黏膜白斑、乳腺纤维囊性病、慢性萎缩性胃炎、皮肤慢性溃疡、结肠多发性腺瘤性息肉等。病毒性肝炎虽可发展为肝硬化和肝癌，但一般不列为典型癌前病变，本题作为例外"},{"q":"下列各项水电解质紊乱中最容易引起休克的是","o":["高渗性脱水","水中毒","水肿","低渗性脱水","等渗性脱水"],"a":3,"e":"低渗性脱水失钠多于失水，细胞外液低渗使水分向细胞内转移，导致细胞外液尤其血容量明显减少，最易发生循环衰竭和休克。高渗性脱水时细胞内液外移可部分维持血容量；水中毒、水肿为水过多；等渗性脱水介于两者之间"},{"q":"继发性肺结核病，结核分枝杆菌播散的途径主要是","o":["淋巴道播散","直接蔓延","血行播散","支气管播散","消化道播散"],"a":3,"e":"继发性肺结核多见于成人，病变较局限，易经支气管播散，在肺内形成新旧不一的病灶。淋巴道播散和血行播散主要见于原发性肺结核；直接蔓延、消化道播散均较少见，不是主要播散途径"},{"q":"下列哪项不属于萎缩范畴","o":["老年女性的子宫缩小","老年男性的睾丸缩小","青春期以后的胸腺","呆小病","脊髓灰质炎患儿的下肢消瘦无力"],"a":3,"e":"呆小病因先天性甲状腺功能低下导致发育迟缓和智力低下，属发育障碍，不属于萎缩。老年女性子宫、老年男性睾丸、青春期后胸腺均为生理性萎缩；脊髓灰质炎患儿下肢消瘦无力为病理性萎缩"},{"q":"一高原性缺氧患者，血气分析结果显示PaCO2 与HCO3－均降低，最可能的诊断为","o":["呼吸性碱中毒","代谢性碱中毒","代谢性酸中毒","呼吸性酸中毒","呼吸性碱中毒合并代谢性酸中毒"],"a":0,"e":"高原低氧刺激通气增强，CO2排出过多致PaCO2降低，肾脏代偿性排出HCO3-使其降低，二者一致且为代偿过程，符合呼吸性碱中毒。代谢性碱中毒时HCO3-升高；呼吸性酸中毒时PaCO2升高；若合并代谢性酸中毒则pH明显异常"},{"q":"病毒性肺炎的特点不包括","o":["常见病因是流感病毒","属间质性肺炎","以中性粒细胞浸润为主","肺泡上皮细胞内可见病毒包含体","肺泡腔内壁透明膜形成"],"a":2,"e":"病毒性肺炎常见病因是流感病毒，属间质性肺炎，浸润细胞以淋巴细胞、单核细胞为主，肺泡上皮细胞内可见病毒包涵体，肺泡腔内壁可形成透明膜。以中性粒细胞浸润为主是细菌性肺炎特点，故不包括"},{"q":"大叶性肺炎自然进程中，听诊可闻及湿性啰音的时期是","o":["充血水肿期，红色肝变期","红色肝变期，灰色肝变期","灰色肝变期，溶解消散期","溶解消散期，恢复期","充血水肿期，溶解消散期"],"a":4,"e":"大叶性肺炎充血水肿期肺泡腔内有水肿液，溶解消散期渗出物被溶解液化，这两期肺泡内液体较多，听诊可闻湿性啰音。红色肝变期、灰色肝变期肺泡腔充满纤维素和细胞，实变明显，叩诊浊音、听诊支气管呼吸音，湿啰音不明显"},{"q":"肉芽组织演变为瘢痕组织的过程中，常可见到的病理改变是","o":["毛细血管的数量逐渐增多","胶原纤维的的数量逐渐增多","成纤维细胞的数量逐渐增多","炎性细胞的数量逐渐增多","组织内的水分逐渐增多"],"a":1,"e":"肉芽组织成熟为瘢痕组织时，毛细血管、成纤维细胞逐渐减少，炎性细胞消失，组织内水分减少，而胶原纤维不断增多并排列致密，最终形成瘢痕。其余各项均为增多，与肉芽组织演变为瘢痕的规律相反"},{"q":"下列关于高渗性脱水的描述，错误的是","o":["失水>失钠 ，血清Na+浓度>150mmol/L","血浆渗透压>310 mOsm/L","细胞外液量和细胞内液量均减少","易引起微循环衰竭","又称低容量性高钠血症"],"a":3,"e":"高渗性脱水以失水为主，细胞外液渗透压升高，水从细胞内移出，血容量减少不明显，不易发生微循环衰竭，后者是低渗性脱水的特点。失水大于失钠、血钠大于150mmol/L、渗透压大于310mOsm/L、又称低容量性高钠血症均正确"},{"q":"关于风湿病的临床表现，不正确的是","o":["风湿性脑病可出现小舞蹈症","风湿性心脏病可致心动过速","风湿性心脏病可闻心脏杂音","风湿性关节炎常导致关节畸形","皮肤环形红斑有助于临床早期诊断"],"a":3,"e":"风湿性关节炎为滑膜浆液性炎，表现为游走性大关节炎，愈后不留关节畸形，故“常导致关节畸形”错误，这是类风湿关节炎的特点。风湿性脑病出现小舞蹈症、风湿性心脏病致心动过速及心脏杂音、皮肤环形红斑有助早期诊断，均正确"},{"q":"血浆氨基酸失衡学说中所说的芳香族氨基酸包括","o":["亮氨酸、异亮氨酸和缬氨酸","苯丙氨酸、酪氨酸和色氨酸","亮氨酸、缬氨酸和色氨酸","异亮氨酸、色氨酸和缬氨酸","苯丙氨酸和异亮氨酸"],"a":1,"e":"芳香族氨基酸包括苯丙氨酸、酪氨酸和色氨酸，在肝性脑病时血中升高，与支链氨基酸比例失衡。亮氨酸、异亮氨酸、缬氨酸属支链氨基酸，其余混排选项均把支链氨基酸误列为芳香族氨基酸"},{"q":"肝性脑病病人血浆氨基酸失衡，主要是由于","o":["肝脏对雌激素的灭活作用减弱","肝脏对糖皮质激素的灭活作用减弱","肝脏对肾上腺素的灭活作用减弱","肝脏对胰高血糖素的灭活作用减弱","肝脏对胰岛素和胰高血糖素的灭活作用减弱"],"a":4,"e":"肝功能衰竭时对胰岛素和胰高血糖素灭活减弱：胰高血糖素升高促进蛋白分解、芳香族氨基酸增多，胰岛素升高促进支链氨基酸进入肌肉被利用，使血中支链氨基酸减少，形成氨基酸失衡。仅列单一激素灭活减弱均不全面"},{"q":"管状腺瘤的病理学特点是","o":["常发生在乳腺、腮腺","呈结节状，境界清楚，常有包膜","肿瘤呈囊性，切面可见单房或多房囊腔","常呈息肉状外生性生长，可有蒂，或与黏膜广基性相连","由腺上皮细胞、肌上皮细胞、黏液样成分和软骨样组织等构成"],"a":3,"e":"管状腺瘤是结肠、直肠常见良性肿瘤，肉眼多呈息肉状外生性生长，可有蒂或与黏膜广基相连。常发生在乳腺、腮腺的是多形性腺瘤；结节状有包膜见于甲状腺腺瘤；囊性多房囊腔见于囊腺瘤；腺上皮、肌上皮、黏液软骨样为多形性腺瘤特点"},{"q":"严重感染导致DIC发生的主要机制是","o":["激活凝血酶原，促进凝血酶生成","损伤血管内皮细胞，激活FⅫ","释放大量组织因子入血","抗凝物质灭活增加","单核吞噬细胞系统功能低下"],"a":1,"e":"严重感染尤其革兰阴性菌，内毒素损伤血管内皮细胞，暴露胶原激活FⅫ，启动内源性凝血途径，是感染致DIC的重要机制。释放大量组织因子多见于产科、肿瘤；激活凝血酶原、抗凝物质灭活、单核吞噬系统功能低下为参与因素，但非主要始动机制"},{"q":"降钙素的作用是","o":["促进肾小管对钙的吸收、骨钙的溶解和成骨作用","抑制肾小管对钙的吸收、骨钙的溶解和成骨作用","促进肾小管对钙的吸收，抑制骨钙的溶解和成骨作用","抑制肾小管对钙的吸收，促进骨钙的溶解和成骨作用","抑制肾小管对钙的吸收和骨钙的溶解，促进成骨作用"],"a":4,"e":"降钙素由甲状腺C细胞分泌，可降低血钙，作用为抑制肾小管对钙的重吸收、抑制破骨细胞即骨钙溶解、促进成骨使钙沉积于骨。其余选项在肾小管吸收、骨钙溶解和成骨三个方向上均有错误"},{"q":"急性弥漫性增生性肾小球肾炎的透射电镜特点是","o":["基底膜分层形成双规现象","基底膜大量电子致密物沉积","上皮下形成“驼峰”样电子致密物沉积","内皮下大量电子致密物沉积","系膜区大量电子致密物沉积"],"a":2,"e":"急性弥漫性增生性肾小球肾炎（链球菌感染后）电镜可见脏层上皮下“驼峰”样电子致密物沉积，是本病特征。基底膜分层双轨见于膜增生性肾炎；基底膜内、内皮下、系膜区大量沉积分别见于膜性、狼疮性等肾炎，均非本病特点"},{"q":"信号转导系统对靶蛋白调节最重要的方式是","o":["蛋白质的糖基化","DNA的甲基化","DNA的乙酰化","蛋白质与核受体的结合","蛋白质可逆的磷酸化"],"a":4,"e":"信号转导中蛋白激酶和磷酸酶通过对靶蛋白进行可逆磷酸化与去磷酸化，快速调节其活性，是最重要的调节方式。糖基化、DNA甲基化、乙酰化属其他修饰；蛋白质与核受体结合是类固醇激素的作用方式，均非最普遍方式"},{"q":"系统性红斑狼疮特异性的抗体检测指标是","o":["抗双链DNA抗体","抗组蛋白抗体","抗粒细胞抗体","抗核仁抗原抗体","抗“O”抗体"],"a":0,"e":"抗双链DNA抗体对系统性红斑狼疮有较高特异性，是诊断及活动性监测的重要指标。抗组蛋白抗体多见于药物性狼疮；抗粒细胞抗体、抗核仁抗原抗体并非SLE特异指标；抗“O”抗体用于链球菌感染的诊断"},{"q":"严重慢性支气管炎经常导致","o":["胸膜炎","肺癌","阻塞性肺气肿","气胸","支气管扩张症"],"a":2,"e":"严重慢性支气管炎因小气道阻塞和肺泡壁破坏，常并发阻塞性肺气肿。胸膜炎、肺癌、气胸、支气管扩张症也可发生，但都不如阻塞性肺气肿常见和直接，阻塞性肺气肿是慢支最常见的后果"},{"q":"大叶性肺炎最特征性的病理变化，是在肺泡腔内出现","o":["肺炎链球菌","红细胞","白细胞","纤维素","水肿液"],"a":3,"e":"大叶性肺炎属纤维素性炎，最特征性的改变是肺泡腔内大量纤维素渗出。肺炎链球菌是病因而非特征性病理变化；红细胞见于红色肝变期；白细胞、水肿液虽可出现，但都不具特征性，纤维素才是本质"},{"q":"下列对于萎缩的病理变化的描述中，错误的是","o":["组织、器官体积缩小，重量减轻","组织器官的颜色变深","组织器官的质地柔软","光镜下，实质细胞数量减少","光镜下，间质结缔组织增生"],"a":2,"e":"萎缩的组织器官体积缩小、重量减轻、颜色变深，光镜下实质细胞数量减少、间质结缔组织相对增生，质地因纤维组织增多而变韧变硬，而非柔软，故“质地柔软”错误。其余各项均为萎缩的典型病理变化"},{"q":"炎症时，局部红、热是由于","o":["血管扩张，血流加快","血流缓慢，血液成分渗出","轴流增宽，血流减慢","血流停滞","血管收缩"],"a":0,"e":"炎症早期细动脉扩张、血流加快，局部血流量增多，导致组织发红和温度升高。血流缓慢、血液成分渗出、轴流增宽、血流停滞为后续改变，与红热关系不大；血管收缩使局部缺血而苍白"},{"q":"可引起肾后性ARF的病因是","o":["弥漫性肾小球肾炎","休克早期","输尿管结石","汞中毒","心力衰竭"],"a":2,"e":"肾后性急性肾功能衰竭由尿路梗阻引起，输尿管结石可阻塞尿路导致肾后性ARF。弥漫性肾小球肾炎为肾性病因；休克早期、心力衰竭属肾前性；汞中毒致肾小管损伤，属肾性病因"},{"q":"子宫内膜样癌的特征不包括","o":["多见于绝经期和绝经后的妇女","与雌激素长期持续作用有关","病理类型主要为腺癌","主要临床表现为不规则阴道出血","以血道转移为主要扩散方式"],"a":4,"e":"子宫内膜样癌多见于绝经前后妇女，与雌激素长期持续作用有关，病理以腺癌为主，临床主要表现为不规则阴道出血，扩散以直接蔓延和淋巴道转移为主，血道转移较少见且多为晚期，故不包括"},{"q":"凝血因子和血小板生成大于消耗的情况见于","o":["失代偿型DIC","代偿型DIC","过度代偿型DIC","急性DIC早期","亚急性DIC"],"a":2,"e":"过度代偿型DIC时凝血因子和血小板生成超过消耗，血液呈高凝状态，出血不明显甚至形成血栓。失代偿型消耗大于生成、出血明显；代偿型生成与消耗大致平衡；急性DIC早期、亚急性DIC均不符合生成大于消耗"},{"q":"严重水中毒的表现不包括","o":["细胞内液增多","细胞外液增多","血清Na+浓度可保持正常","颅内压升高","皮肤凹陷性水肿"],"a":2,"e":"严重水中毒时大量低渗水潴留使血液被稀释，血清Na+浓度明显降低，发生低钠血症，不可能保持正常。细胞内液和细胞外液均增多、颅内压升高致脑水肿、皮肤凹陷性水肿均为严重水中毒表现"},{"q":"大叶性肺炎时的肺肉质变，是由于下列哪种细胞渗出过少而引起","o":["红细胞","中性粒细胞","巨噬细胞","淋巴细胞","嗜酸性粒细胞"],"a":1,"e":"肺肉质变是因肺泡腔内纤维素渗出过多，而中性粒细胞渗出过少、释放蛋白溶解酶不足，纤维素不能被完全溶解吸收，被肉芽组织取代而机化。红细胞、巨噬细胞、淋巴细胞、嗜酸性粒细胞均非此过程的关键细胞"},{"q":"心肌顿抑是指缺血心肌恢复血液供应后","o":["心肌发生不可逆性损伤","心肌功能一时性降低","心肌功能永久性丧失","心肌收缩迟缓、僵硬","心肌节律性下降，心率变慢"],"a":1,"e":"心肌顿抑指缺血心肌恢复血流灌注后，心功能并未立即恢复，而呈一时性、可逆性降低，持续数小时至数日才恢复，并无不可逆损伤。不可逆损伤、功能永久丧失属心肌梗死；收缩迟缓僵硬、心率变慢均不符合"},{"q":"心内膜下心肌梗死的特点是","o":["引起心脏破裂","引起纤维素性心包炎","不波及肉柱和乳头肌","多发性小灶状坏死","引起室壁瘤"],"a":3,"e":"心内膜下心肌梗死的特点是心内膜下心肌多发性小灶状坏死，常累及肉柱和乳头肌，不易引起心脏破裂、室壁瘤或纤维素性心包炎，这些并发症多见于透壁性心肌梗死，故多发性小灶状坏死为其特点"},{"q":"消化性溃疡穿孔最可能发生的部位是","o":["贲门","十二指肠球部","胃小弯近幽门处","胃体部","胃底部"],"a":1,"e":"消化性溃疡穿孔最常见于十二指肠球部前壁，该处肠壁较薄、位置表浅，溃疡易穿透浆膜。胃小弯近幽门处溃疡也常见但穿孔略少；贲门、胃体部、胃底部的溃疡穿孔更为少见"},{"q":"关于异物性肉芽肿，下列描述不正确的是","o":["属于慢性炎症","常常由手术缝线、滑石粉、移植物等引起","局部以中性粒细胞浸润为主","可形成结节状病灶","属于特异性炎症"],"a":2,"e":"异物性肉芽肿属慢性炎症，常由手术缝线、滑石粉、移植物等异物引起，局部以巨噬细胞、异物巨细胞浸润并形成结节状病灶为主，中性粒细胞不是主要浸润细胞，故该项错误。其余关于其病因、性质与形态的描述均正确"},{"q":"与消化性溃疡发病无关的是","o":["饮酒","非甾体类消炎药物","幽门螺旋杆菌感染","外伤","自主神经功能紊乱"],"a":3,"e":"消化性溃疡发病与幽门螺杆菌感染、非甾体抗炎药、饮酒、吸烟、自主神经功能紊乱及胃酸分泌过多密切相关。外伤与消化性溃疡发病无直接关系，是本题的无关项"},{"q":"肺心病发病的中心环节是","o":["慢性支气管炎","慢性阻塞性肺气肿","肺纤维化","肺血管床减少","肺动脉高压"],"a":4,"e":"肺源性心脏病发病的中心环节是肺动脉高压，由慢性支气管肺疾病导致肺血管床减少、肺血管收缩，使右心负荷增加，进而右心肥厚衰竭。慢性支气管炎、阻塞性肺气肿、肺纤维化、肺血管床减少均为肺动脉高压的原因或基础"},{"q":"休克早期的心脑灌流量表现为","o":["均明显增加","均明显减少","先减少后增加","脑灌流量增加，心灌流量无明显改变","心灌流量增加，脑灌流量无明显改变"],"a":4,"e":"休克早期交感肾上腺髓质系统强烈兴奋，儿茶酚胺释放增多，血液发生重新分布，皮肤与内脏血管收缩，而冠状动脉因心肌代谢产物增多而舒张，心灌流量增加；脑血流有自身调节，灌流量无明显改变。心脑灌流量均明显减少是休克失代偿期的表现，脑灌流量增加也不符合早期脑循环相对稳定的实际"},{"q":"常发生液化性坏死的器官是","o":["肺","脑","肾","心脏","脾"],"a":1,"e":"液化性坏死因坏死组织含脂质多、蛋白质少或蛋白酶丰富，坏死后迅速液化成无定形物质，脑组织富含脂质而蛋白少，脑梗死常液化成羹状或形成囊腔，故脑最典型。肺梗死多为出血性坏死，肾、心、脾的梗死则属凝固性坏死，坏死后短期内组织轮廓仍保存，与液化性坏死不同"},{"q":"下列化脓性炎的相关概念，错误的是","o":["表面化脓是指发生在黏膜和浆膜表面的化脓性炎","积脓是指化脓性炎发生于浆膜、胆囊、输卵管时，脓液在上述管腔内积存","脓性卡他性炎是指发生在浆膜表面的化脓性炎","脓肿是指器官或组织内的局限性化脓性炎","蜂窝织炎是指疏松结缔组织的弥漫性化脓性炎"],"a":2,"e":"卡他性炎特指黏膜的渗出性炎，脓性卡他性炎即发生于黏膜表面的化脓性炎，而非浆膜，故该表述错误。表面化脓正是发生于黏膜和浆膜表面的化脓性炎；积脓指浆膜腔或胆囊、输卵管等管腔内脓液蓄积；脓肿为器官组织内局限性化脓性炎；蜂窝织炎为疏松结缔组织的弥漫性化脓性炎"},{"q":"下述哪项不是DIC时产生休克的机制","o":["回心血量减少","出血","激肽、组胺增多","儿茶酚胺减少","微血栓形成"],"a":3,"e":"DIC时微血栓广泛形成阻塞微循环，凝血因子和血小板耗竭引起广泛出血使血量减少，激肽、组胺等扩血管物质增多致血管扩张、通透性增高、回心血量下降，共同促成休克。儿茶酚胺在休克应激中反射性分泌增多而非减少，此项与休克时交感兴奋的实际相反，故不属于DIC产生休克的机制"},{"q":"癌前病变是指","o":["增生的病变","具有癌变可能性的良性病变","早期癌","瘤样病变","炎性假瘤"],"a":1,"e":"癌前病变指本身为良性、但具有潜在癌变可能、长期存在可发展为癌的病变，如黏膜白斑、宫颈糜烂、结肠腺瘤性息肉、乳腺囊性增生病。早期癌已属恶性肿瘤而非良性；瘤样病变是形态类似肿瘤的非肿瘤性增生；炎性假瘤为慢性炎症形成的肿块，本质为炎性增生，三者均非癌前病变"},{"q":"判断慢性肾衰竭程度的最佳指标是","o":["血压","尿量","血清非蛋白氮","血液PH值","内生肌酐清除率"],"a":4,"e":"内生肌酐清除率近似反映肾小球滤过率，能较准确量化肾单位受损程度，是判断慢性肾衰竭严重程度的最佳指标。血清非蛋白氮受蛋白质摄入、分解代谢等肾外因素影响，敏感性和精确性不足；尿量变化个体差异大；血压与血液pH仅反映某些并发症，均不能作为判断肾衰竭程度的可靠依据"},{"q":"糖尿病特征性血管病变是","o":["血管内皮增生","毛细血管基底膜弥漫性增厚","动脉中层钙化","血管壁纤维化","血管内皮损伤脱落"],"a":1,"e":"糖尿病微血管病变的特征性改变是毛细血管基底膜弥漫性增厚，由高血糖致糖基化终产物沉积、胶原合成增加所致，是糖尿病肾病和视网膜病变的病理基础。动脉中层钙化属Monckeberg动脉硬化，多见于老年人，与糖尿病无特异关联；血管内皮增生、内皮损伤脱落并非糖尿病的特征性血管改变"},{"q":"门脉性肝硬化镜下的特征改变是","o":["肝细胞变性","肝细胞坏死","纤维组织增生","形成假小叶","肝细胞再生"],"a":3,"e":"假小叶是肝硬化最具特征性的镜下标志，由增生的纤维组织分割、包绕原有肝小叶或再生肝细胞结节而成，其内中央静脉缺如、偏位或多个。肝细胞变性、坏死、再生在多种肝病均可出现；纤维组织增生是形成假小叶的基础，但单独存在不足以确诊肝硬化，只有假小叶形成才是门脉性肝硬化的特征改变"},{"q":"下列哪一项不是急性普通型肝炎的病变特点","o":["肝细胞气球样变","肝细胞点状坏死","Kupffer细胞增生","肝细胞碎片样坏死","淋巴细胞浸润"],"a":3,"e":"急性普通型肝炎以肝细胞广泛变性为主，可见气球样变和嗜酸性变，坏死轻微呈点状坏死，伴Kupffer细胞增生和淋巴细胞浸润，肝细胞再生明显。碎片样坏死是慢性肝炎的特征，破坏汇管区界线板，多见于慢性活动性肝炎，不属于急性普通型肝炎的病变特点"},{"q":"高血压性心脏病代偿期的特征是","o":["左心室扩张","左心室向心性肥大","心壁肉柱扁平","弥漫性心肌纤维化","左心室离心性肥大"],"a":1,"e":"高血压时左心室长期承受压力负荷，心肌纤维增粗、室壁增厚而心腔不扩大，形成向心性肥大，属代偿期改变，可维持正常射血。左心室离心性肥大伴心腔扩张是失代偿期表现；左心室扩张、心壁肉柱扁平均为心腔扩大的失代偿改变；弥漫性心肌纤维化多见于心肌病或心肌梗死后修复，非高血压心脏病代偿期特征"},{"q":"休克时最早受到损害的器官是","o":["心脏","肝脏","肺脏","肾脏","脑"],"a":3,"e":"肾脏血流灌注丰富且肾小管对缺血极为敏感，休克时肾血管收缩、肾血流量下降，最早出现肾前性急性肾衰竭乃至急性肾小管坏死，故肾是休克时最先受损的器官。肺虽可发生休克肺，但多在休克持续后；心、脑在休克早期因血液重新分布而相对受保护；肝脏受损相对较晚"},{"q":"风湿性动脉炎表现为","o":["细动脉玻璃样变","大动脉粥瘤形成","中等动脉钙化","小动脉纤维素样坏死","小动脉肌层肥厚"],"a":3,"e":"风湿性动脉炎主要累及小动脉，急性期血管壁结缔组织发生黏液样变性和纤维素样坏死，属风湿病变质渗出期的表现。细动脉玻璃样变是高血压病特征；大动脉粥瘤形成属动脉粥样硬化；中等动脉钙化见于动脉硬化；小动脉肌层肥厚是高血压的血管改变，均非风湿性动脉炎表现"},{"q":"下述各项中，一般不引起急性肾小管坏死的是","o":["休克早期","严重休克","重金属（汞、砷等）","药物（氨基苷类抗生素等）","异型输血"],"a":0,"e":"急性肾小管坏死由持续肾缺血或肾毒性物质引起，严重休克、重金属汞砷、氨基苷类抗生素、异型输血溶血均可致病。休克早期仅因肾血管收缩致肾血流量下降，引起功能性即肾前性急性肾衰竭，肾小管结构尚完整，及时纠正缺血后可逆，一般不发生急性肾小管坏死"},{"q":"亚急性重型肝炎的病变特点是","o":["点状坏死","碎片状坏死","桥接坏死","亚大片坏死伴有肝细胞结节状再生","弥漫性大块坏死"],"a":3,"e":"亚急性重型肝炎的病理特点是肝细胞亚大片坏死，坏死范围较急性重型局限，同时存活肝细胞有明显结节状再生，病程较长，易转为坏死后性肝硬化。弥漫性大块坏死是急性重型肝炎特点；点状坏死见于急性普通型肝炎；碎片状、桥接坏死是慢性活动性肝炎的表现，均非亚急性重型肝炎的特征"},{"q":"在热应激时，将细胞新合成的一组蛋白质称为","o":["C反应蛋白","纤维连接蛋白","热休克蛋白","血浆铜蓝蛋白","血清淀粉样A蛋白"],"a":2,"e":"热休克蛋白是细胞在热应激等不良刺激下新合成的一组高度保守蛋白质，作为分子伴侣帮助蛋白质折叠、修复受损蛋白，提高细胞对热损伤的耐受性。C反应蛋白、血清淀粉样A蛋白是肝脏合成的急性期蛋白；纤维连接蛋白、血浆铜蓝蛋白亦属急性时相蛋白，均为细胞外体液成分，与细胞内热休克蛋白不同"},{"q":"乳腺癌最常见的发生部位","o":["乳腺外上象限","乳腺外下象限","乳腺内上象限","乳腺内下象限","乳腺中央区"],"a":0,"e":"乳腺外上象限腺体组织最丰富，是乳腺癌最常见的原发部位，临床上外上象限肿块也最需警惕。外下象限、内上象限、内下象限的腺体量较少，肿瘤发生率依次降低；中央区即乳晕下区仅见于乳头湿疹样癌等少数类型，远不如外上象限常见"},{"q":"关于恶性肿瘤细胞核的特点，错误的是","o":["核大小、形状不一","核质比增大","核分裂多见","核染色质减少","可见病理性核分裂"],"a":3,"e":"恶性肿瘤细胞核异型性明显，表现为核增大、核质比升高、核大小形态不一、染色质增粗深染、核分裂象增多并出现病理性核分裂。核染色质应增多浓染而非减少，故该项错误；核大小形状不一、核质比增大、核分裂多见、病理性核分裂均属恶性细胞核的典型特征，唯有核染色质减少与之相反"},{"q":"下列关于小叶性肺炎的描述，错误的是","o":["由多种致病力较弱的细菌混合感染所致","常为其他疾病的并发症","病变呈灶状散在分布","病变为纤维素性炎","可导致支气管扩张"],"a":3,"e":"小叶性肺炎是以细支气管为中心、累及周围肺泡的急性化脓性炎，多由多种致病力较弱的细菌混合感染引起，常为其他疾病的并发症，病变灶状散在，可因破坏支气管壁导致支气管扩张。纤维素性炎是大叶性肺炎的病变性质，把小叶性肺炎说成纤维素性炎是错误的"},{"q":"丝虫病患者出现水肿是由于","o":["微血管壁通透性增高","毛细血管流体静压升高","血浆胶体渗透压降低","淋巴回流受阻","肾小球滤过率减少"],"a":3,"e":"丝虫成虫寄生于淋巴管和淋巴结，引起淋巴管阻塞和淋巴回流障碍，含蛋白的淋巴液在组织间隙积聚形成淋巴水肿，长期可致象皮肿。微血管壁通透性增高见于炎症水肿；毛细血管流体静压升高见于右心衰或静脉阻塞；血浆胶体渗透压降低见于低蛋白血症；肾小球滤过率减少见于肾性水肿，均非丝虫病水肿机制"},{"q":"下列哪项不符合肾急性细胞型移植排斥反应","o":["发生于肾移植后24小时内","骤然发生移植肾衰竭","肾间质明显水肿","肾间质中可见CD4+、CD8+T细胞为主的单个核细胞浸润","肾小管受累发生局部坏死"],"a":0,"e":"急性细胞型移植排斥反应多发生于移植肾后数天至数周甚至数月，以CD4+、CD8+T细胞为主的单个核细胞浸润肾间质、肾小管受累坏死、间质水肿并骤然发生移植肾衰竭为特点。移植后24小时内发生的是超急性排斥反应，由受者预存抗体介导，发病机制与细胞型不同，故该项时间不符合急性排斥反应"},{"q":"不符合炎症渗出液的描述是","o":["液体混浊","液体比重高","液体静置后凝固","液体内蛋白含量高","液体内含极少细胞"],"a":4,"e":"炎症渗出液因血管通透性增高，蛋白和细胞成分大量渗出，故液体混浊、比重高、蛋白含量高、静置后易凝固，且含有较多炎细胞。液体内含极少细胞是漏出液的特征，漏出液蛋白低、比重低、清亮不凝，多因静脉压升高或低蛋白血症形成，故该项不符合炎症渗出液的描述"},{"q":"下列肝炎类型中，肝脏体积缩小最明显的是","o":["急性重型肝炎","亚急性重型肝炎","轻度慢性肝炎","重度慢性肝炎","急性普通型肝炎"],"a":0,"e":"急性重型肝炎起病急骤，肝细胞发生弥漫性大块坏死，肝组织广泛崩解液化，肝脏体积迅速显著缩小、重量减轻，称急性黄色或红色肝萎缩。亚急性重型肝炎为亚大片坏死伴再生，缩小不如急性显著；慢性肝炎以纤维化和假小叶形成为主，晚期缩小进程缓慢；急性普通型肝炎以变性为主，体积多正常或略大"},{"q":"对肺癌早期诊断最有价值的检查是","o":["血液学检查","X线检查","纤维支气管镜检查","临床症状","CT检查"],"a":2,"e":"纤维支气管镜能直接观察气管支气管腔内病变，并可进行活组织检查和刷检细胞学，对中央型肺癌的早期确诊最有价值。X线和CT属影像学检查，发现肿块时多已非最早阶段；临床症状出现较晚且无特异性；血液学检查对肺癌早期诊断的敏感性和特异性均不足，不能作为早期诊断的首选"},{"q":"肺鳞癌主要起源于","o":["I型肺泡上皮细胞","支气管黏膜上皮细胞鳞状化生","支气管壁腺体上皮细胞","II型肺泡上皮细胞","支气管壁嗜银细胞"],"a":1,"e":"肺鳞状细胞癌多发生于段以上大支气管，其发生经历支气管黏膜上皮鳞状化生、异型增生、原位癌至浸润癌的过程，属中央型肺癌。Ⅱ型肺泡上皮是肺腺癌的主要起源；支气管壁腺体上皮恶变形成腺癌；支气管壁嗜银细胞即Kulchitsky细胞是肺类癌的起源；Ⅰ型肺泡上皮不参与鳞癌发生"},{"q":"患者，女，26岁，孕36周。出现发热、寒战、腰痛，查体时出现肾区的叩击痛，尿液检查发现大量白细胞和白细胞管型，其最可能患有的疾病是","o":["急性弥漫性增生性肾小球肾炎","膀胱炎","子宫内膜异位","急性肾盂肾炎","尿道炎"],"a":3,"e":"患者发热寒战、腰痛、肾区叩击痛，尿中大量白细胞并见白细胞管型，提示肾实质的急性化脓性炎症，符合急性肾盂肾炎，其多由细菌上行感染所致，白细胞管型是与下尿路感染的重要鉴别点。膀胱炎、尿道炎属下尿路感染，无发热腰痛及管型；急性弥漫性增生性肾小球肾炎以血尿、蛋白尿、水肿、高血压为主要表现"},{"q":"肿瘤性增殖与非肿瘤性增殖的根本区别是","o":["有肿块形成","有核分裂象","有炎症反应","增生细胞不同程度地失去分化成熟的能力","细胞生长旺盛"],"a":3,"e":"肿瘤性增殖的本质是细胞获得自主生长能力，增生细胞不同程度失去分化成熟的能力，表现为异型性和单克隆性，即使致病因素去除仍持续生长。核分裂象在正常组织修复增生中亦可见；肿块可由炎性假瘤形成；炎症反应、生长旺盛均非肿瘤增殖所独有，不能作为肿瘤性与非肿瘤性增殖的根本区别"},{"q":"引起发热最常见的原因是","o":["无菌性炎症","恶性肿瘤","抗原抗体复合物","细菌感染","病毒感染"],"a":3,"e":"发热病因以感染性因素最为多见，其中细菌感染引起的发热居首位，细菌毒素及细胞壁成分作为外源性致热原，激活内生致热原释放导致发热。病毒感染亦可发热但总体少于细菌；恶性肿瘤、抗原抗体复合物、无菌性炎症所致发热属非感染性原因，其发生率均远低于细菌感染"},{"q":"导致急性炎症疼痛的原因不包括","o":["渗出物的压迫作用","组胺的作用","P物质的作用","激肽类的作用","PGE2的作用"],"a":1,"e":"急性炎症的疼痛由渗出物压迫神经末梢，以及缓激肽等激肽类、P物质、前列腺素E2等炎症介质刺激伤害感受器共同引起，其中缓激肽是致痛作用最强的介质。组胺主要作用于H1受体引起血管扩张和通透性增高，多与瘙痒相关而非疼痛，故组胺的作用不属于急性炎症致痛原因"},{"q":"胃溃疡难以愈合的局部因素主要是","o":["溃疡过深","溃疡过大","溃疡坏死","溃疡底部神经纤维断裂、变性","溃疡底部小动脉发生增生性内膜炎或血栓形成"],"a":4,"e":"胃溃疡底部的小动脉常发生增生性内膜炎或血栓形成，使溃疡局部血液循环障碍、营养供应不足，肉芽组织生长和上皮再生受限，是溃疡难以愈合的主要局部因素。溃疡过深、过大只增加愈合难度；坏死是溃疡形成的基础；底部神经纤维断裂变性可影响局部调节，但均非难以愈合的首要原因"},{"q":"急性轻度低钾血症患者，心肌的电生理特性的变化是","o":["兴奋性升高，传导性降低，自律性升高，收缩性升高","兴奋性升高，传导性降低，自律性升高，收缩性降低","兴奋性升高，传导性升高，自律性升高，收缩性升高","兴奋性降低，传导性降低，自律性升高，收缩性升高","兴奋性升高，传导性升高，自律性降低，收缩性升高"],"a":0,"e":"急性轻度低钾时，心肌细胞静息电位负值变小、与阈电位距离缩短，兴奋性升高；0期钠内流减少、去极化幅度速度下降，传导性降低；4期自动去极化相对加快使自律性升高；复极期钙内流相对增多、胞内钙增加，收缩性升高。将收缩性写为降低不符，重度缺钾时心肌收缩性才减弱"},{"q":"下列哪种因素与血栓形成无关","o":["血流缓慢","血管内膜损伤","纤溶酶增加","血小板数量增多","血液高凝状态"],"a":2,"e":"血栓形成依赖血管内膜损伤、血流缓慢及涡流形成、血液高凝状态和血小板数量或黏附性增加等条件。纤溶酶是降解纤维蛋白、溶解血栓的蛋白水解酶，其增加促进血栓溶解而非形成，作用方向与血栓形成机制相反，故纤溶酶增加与血栓形成无关"},{"q":"慢性右心衰竭主要表现为","o":["肺循环动脉充血","体循环动脉充血","肺循环静脉淤血","体循环静脉淤血","肺动脉高压"],"a":3,"e":"右心衰竭时右心排血量减少，血液淤积于体循环静脉系统，表现为颈静脉怒张、肝脏淤血肿大、下肢水肿及腹水等体循环静脉淤血征象。肺循环静脉淤血是左心衰竭的主要表现；肺循环动脉充血、体循环动脉充血均非充血性心衰的血液动力学特征；肺动脉高压多为左心疾病或肺血管病变的结果"},{"q":"下列血气变化与脑功能障碍的关系中，错误的是","o":["PaO2低至60mmHg，可出现智力和视力减退","PaO2低至40mmHg，可出现头痛、不安、精神错乱","PaO2低至20mmHg，均可出现昏迷","PaCO2高达80mmHg，可出现烦燥不安、精神错乱、抽搐","PaCO2升高，可促成颅内压增高"],"a":2,"e":"急性缺氧时氧分压降至60毫米汞柱可致智力视力减退，40毫米汞柱出现头痛、不安、精神错乱，二氧化碳分压升高可扩张脑血管促成颅内压增高，达80毫米汞柱出现烦躁、抽搐等二氧化碳麻醉表现。氧分压低至20毫米汞柱已属极重度缺氧，脑细胞常遭不可逆损伤，但意识状态受缺氧速度、持续时间及二氧化碳分压影响，并非均可昏迷，该绝对化表述不成立"},{"q":"细胞水肿早期较常见的亚细胞结构变化是","o":["线粒体肿胀","内质网破裂","核糖体增多","脂褐素增多","溶酶体增多"],"a":0,"e":"细胞水肿是细胞受损后最早的改变之一，因能量代谢障碍、膜泵失灵致细胞内水和钠增多，早期光镜下见细胞肿胀，电镜下最先表现为线粒体肿胀和内质网扩张，线粒体基质淡染、嵴变短。内质网破裂出现较晚；脂褐素增多是细胞萎缩的表现；核糖体在水肿时反而脱落减少；溶酶体增多并非水肿特征"},{"q":"血液中对固定酸和碱进行缓冲的主要缓冲系统是","o":["碳酸氢盐缓冲系统","磷酸盐缓冲系统","还原血红蛋白缓冲系统","氧合血红蛋白缓冲系统","蛋白质缓冲系统"],"a":0,"e":"碳酸氢盐缓冲系统是血液中最重要的缓冲对，含量最高、缓冲能力强，主要缓冲固定酸和碱，其比值决定血液pH。血红蛋白缓冲系统主要缓冲红细胞内的挥发酸；磷酸盐缓冲系统主要在肾脏和细胞内发挥作用；蛋白质缓冲系统作用较弱，均非血液中缓冲固定酸和碱的主要系统"},{"q":"下列哪种措施可减少肠内氨的生成","o":["利尿剂","补碱","给氧","新霉素","补充支链氨基酸"],"a":3,"e":"口服新霉素可抑制肠道细菌生长，减少尿素分解和蛋白质腐败产氨，从而降低血氨，用于肝性脑病的治疗。补碱使肠腔pH升高，铵根转化为易吸收的氨，反而增加氨吸收；利尿剂可致低钾性碱中毒促进氨的生成与吸收；给氧、补充支链氨基酸均不直接减少肠道产氨"},{"q":"关于肿瘤异型性与分化程度的关系，下列描述中正确的是","o":["异型性大的肿瘤，其分化程度低，恶性程度高","异型性大的肿瘤，其分化程度高，恶性程度高","异型性大的肿瘤，其分化程度低，恶性程度低","异型性小的肿瘤，其分化程度低，恶性程度高","异型性小的肿瘤，其分化程度高，恶性程度高"],"a":0,"e":"异型性指肿瘤组织在细胞形态和组织结构上与正常组织的差异，异型性越大说明肿瘤细胞分化程度越低、越接近原始幼稚状态，其恶性程度越高、生长侵袭性越强。异型性小却恶性高自相矛盾；其余各项把异型性与分化程度、恶性程度的关系颠倒，只有异型性大、分化低、恶性高正确反映了三者对应关系"},{"q":"成人短时间内出血量超过循环血量的多少就可能发生休克","o":["5%～10%","10%～15%","20%～25%","30%～35%","40%～45%"],"a":2,"e":"成人循环血量约5000毫升，短时间内快速失血量达总量的20%左右即约1000毫升时，即可引起失血性休克，因代偿机制已不足以维持有效循环血量和血压。失血5%至10%、10%至15%可通过代偿维持循环稳定，一般不发生休克；更大出血量虽更危险，但休克在失血20%左右即已出现，20%至25%为关键阈值"},{"q":"寄生虫感染病灶局部浸润的炎症细胞主要是","o":["中性粒细胞","单核细胞","嗜酸性粒细胞","淋巴细胞","浆细胞"],"a":2,"e":"寄生虫感染及Ⅰ型超敏反应时，肥大细胞释放的嗜酸性粒细胞趋化因子吸引嗜酸性粒细胞局部聚集，后者通过释放主要碱性蛋白等杀伤寄生虫，故病灶中以嗜酸性粒细胞浸润为主。中性粒细胞是急性化脓性炎的主要细胞；单核细胞、淋巴细胞、浆细胞多见于慢性炎症或病毒感染，均非寄生虫感染的主要浸润细胞"},{"q":"最常见的非霍奇金淋巴瘤类型是","o":["滤泡性淋巴瘤","弥漫性大B细胞性淋巴瘤","淋巴母细胞性淋巴瘤","Burkitt淋巴瘤","NK/T细胞淋巴瘤"],"a":1,"e":"弥漫性大B细胞性淋巴瘤是非霍奇金淋巴瘤中最常见的类型，多见于中老年人，由生发中心或生发中心后B细胞恶变而成，侵袭性较强。滤泡性淋巴瘤虽常见但发病率低于弥漫大B细胞型；淋巴母细胞性淋巴瘤、Burkitt淋巴瘤、NK/T细胞淋巴瘤均属相对少见的亚型"},{"q":"乳腺癌的起源部位主要是","o":["导管上皮","腺泡上皮","真皮汗腺上皮","鳞状上皮","移行上皮"],"a":0,"e":"乳腺癌多起源于乳腺导管系统上皮，由导管上皮异型增生、原位癌发展成浸润性导管癌，是最常见的乳腺癌类型。腺泡上皮是小叶癌的起源，发生率明显低于导管癌；真皮汗腺上皮、鳞状上皮、移行上皮均不分布于乳腺实质，与乳腺癌的发生无关"},{"q":"延髓中枢化学感受器对下述哪项刺激最敏感","o":["PaO2","PaCO2","动脉血pH","血浆碳酸氢盐浓度","以上都不对"],"a":1,"e":"延髓腹外侧区的中枢化学感受器对脑脊液中的氢离子敏感，而二氧化碳能迅速透过血脑屏障生成氢离子，故二氧化碳分压升高是刺激中枢化学感受器最敏感、最重要的生理性因素。氧分压降低对中枢化学感受器直接作用很弱，低氧主要经外周化学感受器兴奋呼吸；动脉血氢离子不易通过血脑屏障，血浆碳酸氢盐浓度变化亦非最直接刺激"},{"q":"糖尿病常可引起","o":["呼吸性酸中毒","呼吸性碱中毒","代谢性酸中毒","代谢性碱中毒","混合性碱中毒"],"a":2,"e":"糖尿病尤其是酮症酸中毒时，胰岛素缺乏使脂肪分解增强，肝脏生成大量酮体即乙酰乙酸、β-羟丁酸和丙酮，消耗碳酸氢盐并产生固定酸蓄积，引起代谢性酸中毒，可伴深大呼吸。呼吸性酸碱失衡源于肺通气障碍；代谢性碱中毒多见于呕吐、利尿剂；混合性碱中毒不符合糖尿病酮症的酸碱变化"},{"q":"缺血再灌注时的呼吸爆发可引起","o":["白细胞趋化","白细胞游走","白细胞沿内皮细胞滚动","白细胞黏附与聚集","白细胞产生氧自由基"],"a":4,"e":"缺血再灌注时，激活的中性粒细胞出现呼吸爆发，耗氧量骤增，经还原型辅酶Ⅱ氧化酶催化产生大量超氧阴离子、过氧化氢等氧自由基，引起膜脂质过氧化和组织损伤，是再灌注损伤的重要机制。趋化、游走、沿内皮滚动、黏附聚集均属白细胞渗出迁移的过程，是自由基产生的前提或伴随现象，而非呼吸爆发本身的结果"},{"q":"病毒性肝炎增生性变化不包括","o":["肝细胞再生","Kupffer细胞增生","肝窦内皮细胞增生","肝星状细胞增生","肝管上皮细胞增生"],"a":2,"e":"病毒性肝炎过程中，坏死区周围肝细胞再生，Kupffer细胞增生并吞噬坏死碎屑，肝星状细胞即Ito细胞增生参与纤维化，肝管上皮也可增生，这些均属增生性改变。肝窦内皮细胞在肝炎时主要表现为肿胀、窗孔减少，并无明显增生，不属于肝炎的增生性变化，故该项不包括"},{"q":"中毒性痢疾最多见于","o":["2~7岁儿童","7~10岁儿童","20~30岁青年","30岁以上壮年人","60岁以上老年人"],"a":0,"e":"中毒性细菌性痢疾多见于2至7岁体格健壮的儿童，由福氏或宋内志贺菌引起，起病急骤，以高热、惊厥、休克和中毒性脑病为主要表现，而肠道症状轻微甚至缺如。7至10岁儿童发病率下降；成人及老年人并非中毒性痢疾的高发人群，成人多表现为普通型菌痢"},{"q":"下列各项中，哪一项不是休克肺发生的主要机制","o":["肺毛细血管通透性增强","肺泡表面活性物质减少","肺血管微血栓形成","肺毛细血管流体静压增高","炎症介质导致呼吸膜损伤"],"a":3,"e":"休克肺的发生与肺毛细血管通透性增高、肺泡表面活性物质减少致肺不张、肺微血栓形成以及炎症介质损伤呼吸膜密切相关，属于通透性肺水肿。肺毛细血管流体静压增高是左心衰竭或肺静脉阻塞导致肺淤血水肿的机制，并非休克肺的主要发病环节，故该项不符合休克肺的发生机制"},{"q":"风湿病引起急性心功能不全的最常见原因是","o":["疣状心内膜炎","风湿性心肌炎","绒毛心","缩窄性心包炎","心包积液"],"a":1,"e":"风湿热急性期，风湿性心肌炎使心肌间质出现Aschoff小体、心肌纤维变性坏死，心肌收缩力减弱，是风湿病引起急性心功能不全最常见的原因。疣状心内膜炎主要累及瓣膜，多导致慢性瓣膜病；绒毛心为纤维素性心包炎；缩窄性心包炎、心包积液主要妨碍心室充盈，均非风湿急性心衰的最常见原因"},{"q":"裂体细胞是指","o":["红细胞碎片","白细胞碎片","血小板碎片","平滑肌细胞碎片","血管内皮细胞碎片"],"a":0,"e":"裂体细胞是弥散性血管内凝血时，微血管内形成的纤维蛋白丝网切割通过的红细胞，使其破裂形成盔形、星形、新月形等形态异常的红细胞碎片，外周血涂片出现裂体细胞是弥散性血管内凝血的重要诊断线索。白细胞、血小板、平滑肌细胞、血管内皮细胞的碎片均不构成裂体细胞的定义"},{"q":"下列不同人群细胞外液所占比例最高的是","o":["成年消瘦男性","成年肥胖男性","成年消瘦女性","成年肥胖女性","婴幼儿"],"a":4,"e":"体液总量及细胞外液占体重的比例随年龄变化，婴幼儿因组织间隙大、细胞外液相对较多，细胞外液占体重比例显著高于成人，是各人群中最高者。成年消瘦者、成年肥胖者的细胞外液比例均较低，尤其肥胖者脂肪组织含水量少、体液比例最低，故婴幼儿细胞外液所占比例居首"},{"q":"引起高钾血症最主要的原因是","o":["酸中毒","组织分解","结肠泌钾减少","缺氧","肾排钾减少"],"a":4,"e":"肾脏是机体排钾的主要途径，急慢性肾衰竭、醛固酮分泌减少或使用保钾利尿剂等使肾排钾减少，是引起高钾血症最主要、最常见的原因。酸中毒使氢离子入细胞、钾离子移出细胞，组织分解和缺氧使细胞内钾释放，结肠泌钾减少均可致血钾升高，但均为次要或辅助因素，重要性不及肾排钾障碍"},{"q":"发生在疏松结缔组织的弥漫性化脓性炎称为","o":["肉芽肿","浆液性炎","变质性炎","蜂窝织炎","纤维素性炎"],"a":3,"e":"蜂窝织炎是发生于疏松结缔组织的弥漫性化脓性炎，多由溶血性链球菌引起，其分泌透明质酸酶和链激酶使炎症易于扩散，病变边界不清。肉芽肿是慢性肉芽肿性炎以巨噬细胞增生形成结节为特征；浆液性炎以浆液渗出为主；变质性炎以实质细胞变性坏死为主；纤维素性炎以纤维蛋白渗出为特征"},{"q":"晚期梅毒与一、二期梅毒的不同之处在于前者有","o":["皮肤、黏膜的广泛性损伤","明显临床症状","树胶样肿和瘢痕形成","全身淋巴结肿大","外生殖器病变"],"a":2,"e":"晚期三期梅毒的特征性病变是树胶样肿形成及随后机化导致的瘢痕，可侵犯皮肤、黏膜、骨、心血管和中枢神经，造成组织破坏和器官功能障碍。皮肤黏膜广泛损伤、全身淋巴结肿大是二期梅毒疹的表现；外生殖器硬下疳为一期梅毒；明显临床症状并非三期独有，均非晚期梅毒区别于早期的要点"},{"q":"下列哪一项不是门静脉高压症的形成机制","o":["窦性阻塞","窦后性阻塞","肝内血管网破坏、改建","肝动脉血流入门静脉","肝合成白蛋白功能减退"],"a":4,"e":"肝硬化门静脉高压的形成机制包括肝窦及窦前、窦后阻塞，肝内血管网广泛破坏和改建使门静脉血流受阻，以及肝动脉与门静脉间异常吻合使动脉血涌入门静脉升高其压力。肝合成白蛋白功能减退主要引起血浆胶体渗透压下降，参与腹水形成，并不直接导致门静脉压力升高，故该项不属于门脉高压的形成机制"},{"q":"慢性呼吸性酸中毒的代偿调节主要靠","o":["细胞外液的缓冲","细胞内液的缓冲","肺脏的调节","肾脏的调节","骨骼的调节"],"a":3,"e":"慢性呼吸性酸中毒时，二氧化碳分压持续升高，肾脏通过加强氢离子分泌和碳酸氢盐重吸收、生成铵根排酸，使血浆碳酸氢盐继发性升高以代偿，此过程需数日达高峰，是慢性呼酸的主要代偿方式。细胞外液和细胞内液缓冲在急性呼酸时起主要作用；肺脏本身是原发紊乱器官无法代偿；骨骼缓冲仅长期严重酸中毒时参与"},{"q":"下列引起弥散障碍的原因中，属于弥散膜增厚的是","o":["肺叶切除","肺实变","肺气肿","肺不张","肺水肿"],"a":4,"e":"肺水肿时肺泡间隔和肺泡腔内液体积聚，使肺泡毛细血管膜增厚、弥散距离加大，属于弥散膜增厚引起的弥散障碍。肺实变时肺泡腔被炎性渗出物占据，通气面积减少，主要是弥散面积减少；肺叶切除、肺不张同样减少弥散面积；肺气肿破坏肺泡壁减少弥散面积，均非弥散膜增厚"},{"q":"关于原发性高血压描述，错误的是","o":["可分为良性和恶性高血压病","病变累及全身细小动脉","血压可持续升高，也可呈波动性","常累及心、脑等重要脏器","有明确病因"],"a":4,"e":"原发性高血压是一种原因未明的独立性疾病，与遗传、环境等多因素相关，可分良性与恶性高血压病，病变累及全身细小动脉，血压可持续升高或波动，常累及心、脑、肾等重要脏器。其并无明确单一病因，称有明确病因与原发性高血压的定义相悖，那属于继发性高血压的特点，故该项错误"},{"q":"钙拮抗剂治疗心力衰竭患者的病理生理学基础是","o":["减轻心的前负荷","减轻心的后负荷","增强心肌收缩功能","改善心肌舒张功能","延缓心室重构"],"a":3,"e":"钙拮抗剂通过阻滞L型钙通道减少钙内流，缓解心肌细胞钙超载，使心肌舒张期顺应性改善、舒张功能增强，从而改善心室充盈，这是其治疗心衰的主要病理生理基础。减轻前负荷主要是利尿剂和静脉扩张剂的作用；减轻后负荷以动脉扩张剂为主；钙拮抗剂反而有负性肌力作用；延缓心室重构主要是血管紧张素转换酶抑制剂等的作用"},{"q":"伤寒小结的主要构成成分是","o":["类上皮细胞","淋巴细胞","多核巨细胞","浆细胞","巨噬细胞"],"a":4,"e":"伤寒小结是伤寒的特征性病变，由增生的巨噬细胞聚集形成，这些巨噬细胞吞噬红细胞、淋巴细胞及伤寒沙门菌后称伤寒细胞，多见于回肠末端集合淋巴结、脾、肝、骨髓。类上皮细胞、多核巨细胞是结核结节等肉芽肿的成分；淋巴细胞、浆细胞虽可伴随存在，但非伤寒小结的主要构成细胞"},{"q":"激活肾素-血管紧张素-醛固酮系统的因素不包括","o":["肾脏低灌流","交感神经系统兴奋","低容量性低钠血症","血浆儿茶酚胺浓度升高","钠水潴留"],"a":4,"e":"肾素血管紧张素醛固酮系统激活的典型刺激包括肾脏低灌流、交感神经兴奋、低容量性低钠血症及血浆儿茶酚胺升高，这些均反映有效循环血量不足或肾灌注下降。钠水潴留使血容量增多、肾灌注改善，通过负反馈抑制肾素释放，从而抑制该系统，故钠水潴留不是激活该系统的因素"},{"q":"小叶性肺炎的病理变化是","o":["细支气管及周围肺泡腔内见大量中性粒细胞浸润","整个肺叶的肺泡腔内大量纤维素渗出","肺泡腔内大量浆液和纤维素渗出","支气管、细支气管壁及肺泡间隔淋巴细胞和巨噬细胞浸润","胸膜面有纤维素和脓性渗出"],"a":0,"e":"小叶性肺炎是以细支气管为中心的急性化脓性炎，镜下见细支气管黏膜充血，腔内及周围肺泡腔内充满大量中性粒细胞即脓细胞，病变呈灶状分布。整个肺叶大量纤维素渗出、肺泡腔内浆液和纤维素渗出是大叶性肺炎的表现；淋巴细胞、巨噬细胞浸润见于间质性肺炎；胸膜纤维素脓性渗出是并发胸膜炎的表现"},{"q":"消化性溃疡病的常见原因不包括","o":["迷走神经兴奋性异常","长期服用阿司匹林","胃动力减弱","刺激性食物","HP感染"],"a":3,"e":"消化性溃疡的主要病因包括幽门螺杆菌感染、长期服用阿司匹林等非甾体抗炎药、迷走神经兴奋性增高致胃酸分泌过多，以及胃动力减弱引起的胆汁十二指肠液反流等。刺激性食物可诱发或加重症状，但并非溃疡形成的根本病因，故刺激性食物不属于消化性溃疡的常见原因"},{"q":"低渗性脱水时机体表现为","o":["细胞内液增加，细胞外液减少","细胞内液、细胞外液均减少","细胞内液减少，细胞外液增加","细胞内液变化不大，细胞外液减少","细胞内液减少，细胞外液正常"],"a":0,"e":"低渗性脱水时失钠多于失水，细胞外液渗透压下降，水顺着渗透梯度由细胞外进入细胞内，导致细胞外液明显减少而细胞内液增多，患者早期即出现循环衰竭表现而无明显口渴。细胞内液与细胞外液均减少是高渗性脱水特点；细胞内液减少、细胞外液增加不符合脱水改变；细胞内液变化不大的描述与水向细胞内转移的机制不符"},{"q":"下列关于缺氧引起呼吸系统变化的叙述中，哪一项是错误的","o":["急性低张性缺氧时，呼吸加深加快，肺通气量增加","等张性低氧血症时，一般不出现呼吸运动的增强","慢性低张性缺氧时，肺通气量增加不明显","急性低张性缺氧时，只有当氧分压下降到60mmHg的时候才会出现明显的呼吸中枢兴奋","低张性缺氧的情况越严重，呼吸中枢的兴奋越强烈，呼吸运动的加强越明显"],"a":4,"e":"低张性缺氧时，氧分压降低通过外周化学感受器反射性兴奋呼吸，使呼吸加深加快、肺通气量增加；但缺氧对呼吸中枢本身是抑制作用，当氧分压过低时这种直接抑制占优势，呼吸反而减弱甚至停止，故缺氧越严重呼吸中枢兴奋越强的说法错误。急性低张性缺氧通气增加、等张性低氧血症呼吸增强不明显、慢性低张性缺氧通气增加不明显、氧分压降到60毫米汞柱才明显兴奋呼吸中枢均正确"},{"q":"成人心率过快反而导致心输出量降低，其上限为","o":["120次/分","140次/分","180次/分","160次/分","200次/分"],"a":2,"e":"心率在一定范围内增快可使心输出量增加，但当心率超过180次每分时，心脏舒张期显著缩短，心室充盈量明显减少，每搏输出量下降，心输出量反而降低。心率120、140、160次每分时尚处于代偿范围或刚开始受限；200次每分已远超临界，但教材通常以180次每分作为心输出量由升转降的上限阈值"},{"q":"有关RTK促进肿瘤增殖的描述，正确的是","o":["RTK过表达，使细胞增殖信号转导过强所致","RTK组成型突变，使其受体下调所致","Ras基因突变所致","Smad4失活所致","激活NF-κB所致"],"a":2,"e":"受体酪氨酸激酶信号通路中，Ras基因是关键癌基因，Ras发生组成型激活突变后持续活化，不断向下游Raf、MEK、ERK通路传递增殖信号，导致细胞异常增殖，是受体酪氨酸激酶相关肿瘤的重要机制。受体下调会减弱而非促进信号；Smad4失活属转化生长因子β抑癌通路异常；核因子κB激活主要与炎症和抗凋亡相关，均非正确描述"},{"q":"细胞内玻璃样变可发生于","o":["心肌细胞","肾小管上皮细胞","平滑肌细胞","成纤维细胞","神经细胞"],"a":1,"e":"细胞内玻璃样变是细胞内出现均质红染的玻璃样物质，典型见于肾小管上皮细胞，因其重吸收原尿中蛋白质形成玻璃样小滴，还可见于浆细胞的Russell小体和酒精性肝病的Mallory小体。心肌细胞、平滑肌细胞、成纤维细胞、神经细胞均非细胞内玻璃样变的好发部位，其变性多表现为水肿、脂肪变等其他形式"},{"q":"新月体性肾小球肾炎主要增生的细胞是","o":["内皮细胞","系膜细胞","球囊脏层上皮细胞","球囊壁层上皮细胞","内皮细胞和系膜细胞"],"a":3,"e":"新月体性肾小球肾炎的特征是肾小囊壁层上皮细胞显著增生，堆积成层，形成包绕毛细血管球的新月体即细胞性新月体，随后纤维化机化，导致肾小球功能迅速丧失，临床表现为急进性肾炎综合征。内皮细胞、系膜细胞增生主要见于急性弥漫性增生性肾小球肾炎；球囊脏层上皮细胞即足细胞在该病中并无明显增生"},{"q":"γ-氨基丁酸使神经元呈超极化状态，是通过下述哪种离子实现的","o":["HCO3－","Na+","K+","Cl－","Ca2+"],"a":3,"e":"抑制性递质γ-氨基丁酸与突触后膜受体结合后，开启氯离子通道，氯离子顺浓度梯度内流，使膜电位负值增大发生超极化，产生抑制性突触后电位。钠离子内流引起去极化，属兴奋性离子机制；钾离子外流虽也可致超极化，但γ-氨基丁酸的作用主要由氯离子内流介导；碳酸氢根、钙离子均非其抑制的主要离子基础"},{"q":"可发生慢性肉芽肿性炎的病变是","o":["结核","动脉粥样硬化","菌痢","慢性支气管炎","慢性阑尾炎"],"a":0,"e":"结核病是由结核分枝杆菌引起的慢性肉芽肿性炎，典型病变为结核结节，由类上皮细胞、Langhans多核巨细胞、淋巴细胞和中心干酪样坏死构成。动脉粥样硬化以脂质沉积和粥瘤形成为主，非肉芽肿性炎；菌痢为假膜性炎；慢性支气管炎、慢性阑尾炎属慢性非特异性炎，均不形成典型肉芽肿"},{"q":"坏死组织机化常见于以下何种坏死灶","o":["较小的坏死灶","不易溶解吸收又无法排出的坏死灶","有自然管道与外界相通的较大的坏死灶","位于皮肤黏膜的坏死灶","较大的被组织包裹的坏死灶"],"a":1,"e":"机化是指坏死组织不能被溶解吸收，也无法经自然管道排出时，由周围增生的肉芽组织长入并逐渐取代坏死组织的过程，最终形成瘢痕。较小坏死灶多可完全溶解吸收；有自然管道相通者坏死物可排出形成空洞或溃疡；皮肤黏膜坏死可脱落形成糜烂溃疡；较大坏死灶多先包裹、钙化，均非机化的典型情形"},{"q":"心力衰竭患者使用利尿剂主要是","o":["增强心肌收缩力","降低心脏的后负荷","降低心脏的前负荷","改善心肌舒张功能","控制水肿"],"a":2,"e":"利尿剂通过促进钠水排出、减少循环血容量和静脉回流，降低心脏前负荷即容量负荷，从而减轻肺淤血和体循环水肿，是心力衰竭治疗的基本措施。增强心肌收缩力是洋地黄等正性肌力药的作用；降低后负荷主要靠动脉扩张剂；改善舒张功能非利尿剂所长；控制水肿是其临床效应，但治疗心衰的主要机制在于降低前负荷"},{"q":"急进型高血压患者最常见的死亡原因是","o":["尿毒症","心力衰竭","脑软化","视网膜出血","脑水肿"],"a":0,"e":"急进型高血压病情凶险，血压骤升，全身细小动脉发生纤维素样坏死，肾脏受累最突出，短期内出现严重肾功能损害并迅速进展为尿毒症，这是其最常见的死亡原因。心力衰竭、脑水肿可致脑出血亦是死因，但不如肾衰常见；脑软化、视网膜出血多为表现或并发症，非主要死因"},{"q":"肝硬化腹水的性质是","o":["渗出液","漏出液","浆液","脓液","淋巴液"],"a":1,"e":"肝硬化腹水主要因门静脉高压、低蛋白血症致血浆胶体渗透压下降、肝淋巴液生成过多及继发性醛固酮增多引起钠水潴留，腹水蛋白含量低、比重低、细胞少、清亮不凝，属漏出液。渗出液蛋白和细胞含量高，多见于腹膜炎或腹腔肿瘤；浆液、脓液、淋巴液均非肝硬化腹水的常规性质"},{"q":"下列引起肺弥散障碍的原因中，属于弥散面积减少的是","o":["肺水肿","肺纤维化","肺实变","肺泡透明膜形成","肺泡壁毛细血管扩张"],"a":2,"e":"肺实变时肺泡腔内充满炎性渗出物，肺泡失去通气功能，有效进行气体交换的肺泡毛细血管面积显著减少，属于弥散面积减少。肺水肿、肺纤维化、肺泡透明膜形成均使肺泡毛细血管膜增厚、弥散距离增加；肺泡壁毛细血管扩张反而增加弥散面积，均不符合弥散面积减少的机制"},{"q":"肝癌最常见的转移途径是","o":["淋巴道转移","肝外血道转移","肝内血道转移","种植性转移","门静脉转移"],"a":2,"e":"肝细胞癌最常见的转移途径是肝内血道转移，癌细胞侵犯门静脉分支，在肝内沿门静脉系统播散形成多数转移结节，这也是肝癌易复发和多发的原因。淋巴道转移相对少见；肝外血道转移如肺、骨多属晚期；种植性转移少见；门静脉转移本质属于肝内血道转移，笼统归为肝内血道转移更准确"},{"q":"亚急性感染性心内膜炎的赘生物中，不常见到的成分是","o":["淋巴细胞和浆细胞","中性粒细胞","细菌菌团","纤维蛋白","血小板"],"a":0,"e":"亚急性感染性心内膜炎的赘生物主要由血小板、纤维蛋白、细菌菌团和中性粒细胞构成，底部可有肉芽组织机化。淋巴细胞和浆细胞是慢性炎症的细胞成分，在赘生物中并不常见，故该项为不常见的成分；中性粒细胞、细菌菌团、纤维蛋白、血小板均为赘生物的常见组成"},{"q":"不属于细胞、组织适应性变化的是","o":["萎缩","机化","肥大","增生","化生"],"a":1,"e":"细胞和组织的适应性变化包括萎缩、肥大、增生和化生，是细胞为应对环境改变而发生的形态和功能调整。机化是坏死组织、血栓或异物被新生肉芽组织长入取代的修复过程，属于损伤后的修复反应而非适应性改变，故机化不属于适应；萎缩、肥大、增生、化生均为典型的适应性变化"},{"q":"大叶性肺炎最危重的并发症是","o":["肺肉质样变","肺脓肿、脓胸","感染性休克","败血症","化脓性胸膜炎"],"a":2,"e":"大叶性肺炎由肺炎链球菌引起，严重病例病原菌入血可引起败血症，进而导致感染性休克即中毒性肺炎，是其中最危重、可迅速致死的并发症。肺肉质变是渗出物机化，影响通气但较局限；肺脓肿、脓胸和化脓性胸膜炎为化脓性并发症；败血症虽可发展为休克，但直接危及生命的最危重结局是感染性休克"},{"q":"大剂量甲状旁腺素可","o":["促进远曲小管对钙的吸收、骨钙的溶解和成骨作用","抑制远曲小管对钙的吸收、骨钙的溶解和成骨作用","促进远曲小管对钙的吸收，抑制骨钙的溶解和成骨作用","抑制远曲小管对钙的吸收，促进骨钙的溶解和成骨作用","促进远曲小管对钙的吸收和骨钙的溶解，抑制成骨作用"],"a":4,"e":"甲状旁腺素通过促进远曲小管对钙的重吸收、抑制磷重吸收以升高血钙，并激活破骨细胞促进骨钙溶解和骨吸收。大剂量或持续作用的甲状旁腺素抑制成骨细胞功能、抑制骨形成，导致骨量丢失。其余各项对远曲小管钙吸收和骨钙溶解方向的描述有误，只有促进远曲小管钙吸收和骨钙溶解、抑制成骨作用准确概括了大剂量甲状旁腺素的三重作用"},{"q":"慢支炎引起支气管扩张症的主要病理基础是","o":["支气管慢性炎症致相关淋巴组织显著增生","支气管壁支撑结构破坏及纤维瘢痕牵拉","肺不张和肺实变","大量黏液脓性和血性渗出物","支气管痉挛和阻塞"],"a":1,"e":"慢性支气管炎长期反复感染，炎症破坏支气管壁的平滑肌、弹力纤维和软骨等支撑结构，使管壁失去弹性，同时周围纤维组织增生形成瘢痕并牵拉管壁，二者共同导致支气管持久性扩张。淋巴组织增生、肺不张和肺实变、黏液脓性渗出物、支气管痉挛和阻塞可参与或加重，但均非支气管扩张形成的主要病理基础"},{"q":"肾透明细胞癌的起源细胞是","o":["肾小管上皮细胞","肾小球系膜细胞","集合管上皮细胞","肾血管内皮细胞","肾淋巴管内皮细胞"],"a":0,"e":"肾透明细胞癌是最常见的肾细胞癌，起源于肾小管上皮细胞即近曲小管，镜下癌细胞胞质丰富透明，富含糖原和脂质，排列成腺泡状或片状。肾小球系膜细胞、集合管上皮、肾血管内皮细胞、肾淋巴管内皮细胞均非肾透明细胞癌的组织起源"},{"q":"阴离子间隙是指","o":["细胞内阴离子与阳离子的浓度差","细胞外阴离子与阳离子的浓度差","细胞内、外阴离子与阳离子的浓度差","血浆中未测定阴离子与未测定阳离子的浓度差","细胞内未测定阴离子与未测定阳离子的浓度差"],"a":3,"e":"阴离子间隙指血浆中未测定阴离子如乳酸、酮体、硫酸盐、磷酸盐等，与未测定阳离子如钾、钙、镁等浓度之差，临床上常以钠离子减去氯离子与碳酸氢盐之和估算，用于判断代谢性酸中毒类型。将阴离子间隙描述为细胞内、外或跨细胞的阴阳离子浓度差，均不符合其定义"},{"q":"原发性肺结核病的肺内原发病灶常位于","o":["肺尖部","肺上叶下部或下叶上部近胸膜处","肺门","肺膈面","胸膜面"],"a":1,"e":"原发性肺结核多见于儿童，结核分枝杆菌随吸入到达通气较好的肺上叶下部或下叶上部近胸膜处形成原发病灶，并沿淋巴管蔓延至肺门淋巴结，构成原发综合征。肺尖部是继发性肺结核的好发部位；肺门、肺膈面、胸膜面均非原发病灶的典型定位"},{"q":"下述哪项是代谢性碱中毒引起低血钾的原因","o":["K+摄入减少","细胞外液量增多使血K+被稀释","细胞外H+与细胞内K+交换增加","消化道排K+增加","肾排K+增加"],"a":4,"e":"代谢性碱中毒时血浆碳酸氢盐升高，远端肾小管钠重吸收增加使管腔负电位加大，同时氢钾交换中氢排泌减少而钾排泌增多，导致肾排钾增加，是引起低血钾的重要原因。细胞外氢离子与细胞内钾交换增加方向与实际相反，代碱时是细胞内氢离子外移、细胞外钾内移；钾摄入减少、稀释、消化道排钾均非代碱致低钾的主要机制"},{"q":"休克肺的主要临床表现不包括","o":["进行性氧分压降低","进行性呼吸困难","进行性高碳酸血症","肺部湿性啰音","进行性紫绀"],"a":2,"e":"休克肺以急性进行性呼吸困难和顽固性低氧血症为主要特征，表现为氧分压进行性下降、紫绀、肺部湿性啰音，因缺氧反射性过度通气，早期二氧化碳分压多降低。进行性高碳酸血症并非休克肺的典型表现，反而提示通气衰竭晚期或气道阻塞，故该项不包括在休克肺主要临床表现中"},{"q":"炎症病灶中渗出纤维素的有利作用不包括","o":["成为修复的支架","限制病原微生物扩散","局限病灶","发生机化引起组织粘连","协助白细胞发挥吞噬作用"],"a":3,"e":"炎症时渗出的纤维蛋白形成网状结构，可限制病原微生物扩散、局限病灶，并为组织修复提供支架，同时有助于白细胞发挥吞噬作用，这些都是有利作用。纤维素若不能被吸收而发生机化，则引起组织粘连如胸膜、腹膜粘连，属于不利后果而非有利作用，故机化引起组织粘连不包括在有利作用中"},{"q":"肿瘤异型性的大小主要反映了","o":["肿瘤的生长速度","肿瘤的性质","肿瘤的组织起源","肿瘤的分化程度","肿瘤的复发情况"],"a":3,"e":"肿瘤异型性是指肿瘤组织在细胞形态和组织结构上与正常组织的差异，其大小直接反映肿瘤细胞的分化程度，异型性越大分化越低、越幼稚。肿瘤性质即良恶性虽与异型性相关，但异型性主要且直接的反映对象是分化程度；生长速度、组织起源、复发情况均不能由异型性大小直接反映"},{"q":"细胞凋亡不足与过度并存的疾病是","o":["AIDS","肝癌","心肌梗死","动脉粥样硬化","阿尔茨海默病"],"a":3,"e":"动脉粥样硬化中细胞凋亡呈现不足与过度并存的双重改变，血管平滑肌细胞和巨噬细胞凋亡不足导致其过度增殖、斑块增大，而内皮细胞凋亡过度则损伤血管内膜、促进血栓形成。艾滋病、阿尔茨海默病以细胞凋亡过度为主；肝癌以凋亡不足为主；心肌梗死以心肌细胞凋亡过度为特征，均非二者并存"},{"q":"符合单纯性甲状腺肿的描述是","o":["男性多于女性","老年患者多见","甲状腺多呈结节状肿大","一般伴有甲状腺功能异常","属良性肿瘤"],"a":2,"e":"单纯性甲状腺肿多因缺碘致甲状腺素合成不足、促甲状腺激素分泌增多，引起甲状腺代偿性增生，表现为甲状腺弥漫性或结节状肿大，功能多正常，女性发病率高于男性，本质为非肿瘤性增生。男性多于女性、老年多见描述不符；一般无甲状腺功能异常；属良性肿瘤错误"},{"q":"继发性肺结核的病理特点不包括","o":["常始于肺尖部","肺门淋巴结常明显受累肿大，发生结核病变","病变恶化进展时常发生支气管播散","可形成纤维性空洞","病程较长"],"a":1,"e":"继发性肺结核多始于肺尖部，病程较长，病变较局限，易发生干酪样坏死和空洞形成，恶化时经支气管播散，一般无肺门淋巴结明显受累。肺门淋巴结肿大发生结核病变是原发性肺结核的特征，属于原发综合征的一部分，故该项不属于继发性肺结核的病理特点；始于肺尖、支气管播散、纤维性空洞、病程较长均为其特点"},{"q":"休克早期组织微循环灌流的特点是","o":["少灌多流、灌多于流","多灌多流、灌少于流","少灌少流、灌少于流","多灌少流、灌多于流","少灌少流、灌多于流"],"a":2,"e":"休克早期因交感肾上腺髓质系统强烈兴奋，儿茶酚胺大量释放，微动脉、后微动脉和毛细血管前括约肌收缩，毛细血管前阻力大于后阻力，血液经直捷通路和动静脉短路回流，组织灌流呈现少灌少流、灌少于流，处于缺血缺氧状态。多灌少流、灌多于流是休克淤血期特点，其余组合均不符合休克早期改变"},{"q":"动脉粥样硬化合并血栓形成的主要原因是","o":["血流旋涡形成","血液凝固性增高","血管内皮下胶原暴露","高脂血症","血流缓慢"],"a":2,"e":"动脉粥样硬化斑块表面纤维帽破裂或侵蚀，使内皮下胶原和坏死粥样物质暴露于血流，血小板迅速黏附聚集并激活凝血级联，形成血栓，是动脉粥样硬化合并血栓形成的主要机制。血流旋涡、血液凝固性增高、血流缓慢是促进因素；高脂血症是动脉粥样硬化的病因，均非血栓形成的直接始动环节"},{"q":"下述哪项不符合完全康复的标准","o":["致病因素已经消除或不起作用","疾病时发生的损伤性变化完全消失","劳动能力完全恢复","机体的自稳调节恢复正常","遗留有病理状态，通过机体的代偿来维持内环境相对正常"],"a":4,"e":"完全康复要求致病因素已消除或不起作用，疾病时的损伤性变化完全消失，机体自稳调节恢复正常，劳动能力完全恢复。遗留病理状态、依靠代偿维持内环境相对稳定属于不完全康复，此时仍有客观体征或实验室异常，故不符合完全康复标准；致病因素消除、损伤消失、劳动能力恢复、自稳调节恢复正常均为完全康复的必备条件"},{"q":"下列与门脉高压无关的表现是","o":["脾肿大","腹水","胃肠淤血","侧支循环形成","蜘蛛痣"],"a":4,"e":"门静脉高压的典型表现包括脾肿大、腹水、胃肠道淤血以及食管胃底静脉、腹壁静脉、痔静脉等侧支循环建立与开放。蜘蛛痣是肝硬化时肝脏对雌激素灭活能力下降、体内雌激素增多导致的小动脉扩张，属肝功能不全的表现，与门静脉压力升高无直接关系，故蜘蛛痣与门脉高压无关"},{"q":"凝固性坏死区别于其他类型坏死的组织学特点是","o":["细胞组织溶解液化","细丝状、小条块状无结构物质","细胞、组织轮廓短期内可保存","无结构颗粒状红染物质","细胞基质解聚"],"a":2,"e":"凝固性坏死时坏死细胞的蛋白质凝固、溶酶体酶作用较弱，坏死组织的细胞和组织轮廓在较长时间内仍可辨认，镜下呈灰白、干燥、坚实的凝固状态，典型见于心、肾、脾的贫血性梗死。细胞组织溶解液化是液化性坏死特点；无结构颗粒状红染物质是干酪样坏死；细丝状小条块状无结构物质、细胞基质解聚亦不符合凝固性坏死的形态特征"},{"q":"中晚期食管癌的肉眼类型不包括","o":["缩窄型","蕈伞型","胶样型","溃疡型","髓质型"],"a":2,"e":"中晚期食管癌的肉眼类型包括髓质型即最常见、蕈伞型、溃疡型、缩窄型等，分别以管壁增厚、肿块突起、溃疡形成和管腔狭窄为特征。胶样型并非食管癌的肉眼分型，胶样癌即黏液腺癌多发生于胃、结肠等部位，故胶样型不包括在食管癌的大体类型中；缩窄型、蕈伞型、溃疡型、髓质型均为常见肉眼类型"},{"q":"青霉素过敏性休克血液循环变化的特点是","o":["毛细血管床大量开放","毛细血管床大量关闭","毛细血管壁通透性降低","毛细血管壁通透性正常","容量血管舒张"],"a":0,"e":"青霉素过敏性休克属Ⅰ型超敏反应，抗原抗体反应使肥大细胞脱颗粒释放组胺、白三烯等介质，引起全身小血管和毛细血管广泛扩张、毛细血管床大量开放，血管容量急剧增大导致有效循环血量相对不足和血压骤降。毛细血管床关闭、通透性降低与过敏时血管扩张通透性增高的实际相反；容量血管即静脉舒张并非其主要特点"},{"q":"甲型肝炎病毒的主要传播途径是","o":["经皮肤黏膜接触传播","经血源传播","经消化道传播","经呼吸道传播","经昆虫媒介传播"],"a":2,"e":"甲型肝炎病毒主要经粪口途径传播，即消化道传播，常因饮水或食物被污染引起暴发流行，感染后可获持久免疫。经血源传播是乙型、丙型、丁型肝炎的主要途径；经皮肤黏膜接触、经呼吸道、经昆虫媒介均不是甲肝的传播方式"},{"q":"股静脉血栓脱落常栓塞","o":["肺动脉","右心房","右心室","下腔静脉","右下肢大静脉"],"a":0,"e":"股静脉血栓脱落后随静脉回流进入下腔静脉，再经右心房、右心室排入肺动脉，因肺动脉分支逐渐变细，栓子常嵌塞于肺动脉主干或其分支，引起肺栓塞。右心房、右心室、下腔静脉仅为栓子运行途经的腔室和血管，并非最终停留部位；右下肢大静脉是血栓形成的原发部位，而非栓塞部位"},{"q":"下列哪项原因不易引起代谢性酸中毒","o":["糖尿病","休克","心跳骤停","呕吐","腹泻"],"a":3,"e":"呕吐丢失大量胃液含盐酸，使体内碳酸氢盐相对增多，引起代谢性碱中毒而非酸中毒。糖尿病酮症产生酮酸、休克和心跳骤停致组织缺氧产生乳酸、腹泻丢失大量肠液碳酸氢盐，均是代谢性酸中毒的常见原因，故呕吐不易引起代谢性酸中毒"},{"q":"慢性萎缩性胃炎与慢性浅表性胃炎最主要的区别是","o":["黏膜充血水肿","淋巴滤泡形成","炎细胞浸润","固有腺体萎缩并常伴有肠上皮化生","常见于胃窦部"],"a":3,"e":"慢性萎缩性胃炎与慢性浅表性胃炎的根本区别在于固有腺体是否萎缩，萎缩性胃炎表现为胃黏膜固有腺体减少、消失，并常伴有肠上皮化生和假幽门腺化生，而浅表性胃炎腺体完整，仅黏膜浅层有炎细胞浸润。黏膜充血水肿、淋巴滤泡形成、炎细胞浸润、好发胃窦部在两者均可出现，不能作为最主要鉴别点"},{"q":"心肌梗死最严重的并发症是","o":["心脏破裂","室壁瘤","附壁血栓形成","纤维素性心包炎","心功能不全"],"a":0,"e":"心脏破裂是急性心肌梗死最严重的并发症，多发生于梗死后1周内，因坏死心肌中和溶解酶作用使室壁软弱，在血压作用下破裂，常导致心包填塞和猝死。室壁瘤、附壁血栓、纤维素性心包炎、心功能不全虽也是心梗并发症，但其严重程度和致死性均不及心脏破裂"},{"q":"诊断早期休克的血液动力学的主要标志是","o":["动脉血压下降","中心静脉压下降","脉压缩小","心输出量减少","肺动脉楔压增高"],"a":2,"e":"休克早期因交感兴奋、外周血管收缩，舒张压升高而收缩压可正常或略降，导致脉压显著缩小，这是早期休克重要的血流动力学标志，而此时收缩压尚未明显下降。动脉血压下降多见于休克失代偿期；中心静脉压下降、心输出量减少并非早期最敏感的鉴别标志；肺动脉楔压增高主要反映左心负荷"},{"q":"引起CRF最常见的原因是","o":["慢性肾小球肾炎","慢性肾盂肾炎","糖尿病肾病","高血压性肾损害","肾脏肿瘤"],"a":0,"e":"慢性肾小球肾炎是我国引起慢性肾衰竭最常见的病因，各种原发和继发性肾小球疾病长期进展，导致肾单位广泛破坏、肾功能不可逆减退。慢性肾盂肾炎、糖尿病肾病、高血压性肾损害、肾脏肿瘤也可导致慢性肾衰竭，但发病率均低于慢性肾小球肾炎"},{"q":"尿毒症毒素不包括","o":["正常代谢产物在体内蓄积","正常生理活性物质的浓度过高","毒性物质经机体代谢所产生的新毒性物质","外源性毒物未经机体解毒、排泄而在体内潴留","外源性非毒性物质在体内蓄积"],"a":4,"e":"尿毒症毒素主要包括体内正常代谢产物蓄积如尿素、肌酐、尿酸，正常生理活性物质浓度异常升高如甲状旁腺素、β2微球蛋白，某些物质经体内代谢转化生成的新毒性物质，以及外源性毒物未经解毒排泄而在体内潴留。外源性本无毒性且在体内蓄积后仍无毒性的物质不属于尿毒症毒素，故该项不包括"},{"q":"生理情况下体液中的H+主要来自","o":["食物摄入","含硫氨基酸氧化","乳酸","磷酸","碳酸"],"a":4,"e":"生理情况下，机体摄入的糖、脂肪、蛋白质氧化产生大量二氧化碳，二氧化碳与水结合生成碳酸并解离出氢离子，碳酸是体内氢离子最主要的来源，每日产生的氢离子量远超过固定酸。含硫氨基酸氧化、乳酸、磷酸等产生的固定酸量较少；食物直接摄入的氢离子更少，均非主要来源"},{"q":"急性弥漫性增生性肾小球肾炎最常发生的临床综合征是","o":["急进性肾炎综合征","慢性肾炎综合征","肾病综合征","急性肾炎综合征","Goodpasture综合征"],"a":3,"e":"急性弥漫性增生性肾小球肾炎多见于儿童，常继发于A族链球菌感染，临床上主要表现为急性肾炎综合征，即血尿、蛋白尿、水肿、高血压和不同程度少尿，多数预后良好。急进性肾炎综合征见于新月体性肾炎；慢性肾炎综合征病程迁延；肾病综合征以大量蛋白尿和低蛋白血症为主；Goodpasture综合征为肺出血肾炎综合征"},{"q":"肥大心肌发生衰竭的病理生理学基础是","o":["心肌结构破坏","心肌细胞不平衡生长","心肌能量生成障碍","心肌能量利用障碍","心肌兴奋-收缩耦联障碍"],"a":1,"e":"心肌肥大时心肌细胞体积增大，但细胞内细胞器和毛细血管等并非同步增长，造成心肌细胞不平衡生长，单位重量心肌的毛细血管密度和线粒体相对减少，导致心肌供血供能不足、收缩性下降，最终由代偿转为衰竭。心肌结构破坏、能量生成障碍、能量利用障碍、兴奋收缩耦联障碍是心衰的一般机制，但肥大心肌衰竭的根本基础在于不平衡生长"},{"q":"当机体抵抗力低下、结核分枝杆菌毒力强时，结核病变可表现为","o":["浆液渗出","结核结节形成","病灶纤维化","渗出物吸收、消散","病灶钙化"],"a":0,"e":"结核病变的形态与机体免疫状态和细菌毒力、数量密切相关，当机体抵抗力低下、结核分枝杆菌毒力强且菌量多时，以渗出性病变为主，表现为浆液性或浆液纤维素性渗出，镜下见充血、水肿和炎细胞浸润。结核结节形成、病灶纤维化、渗出物吸收消散、病灶钙化均见于机体抵抗力较强、菌量较少时，以增生或愈合为主的情况"},{"q":"呼吸性酸中毒合并代谢性碱中毒时pH的变化特点为","o":["升高","正常","降低","升高或降低","正常、略升高或降低"],"a":4,"e":"呼吸性酸中毒使pH降低，代谢性碱中毒使pH升高，二者并存时对血液pH的影响相互拮抗，最终pH取决于两种紊乱的相对严重程度，可表现为正常、略升高或略降低。单一方向的判断均不全面；升高或降低遗漏了二者恰好抵消而pH正常的情况，故正常、略升高或降低最为准确"},{"q":"胃溃疡的好发部位是","o":["胃前壁","胃后壁","胃大弯及胃底","胃小弯近贲门部","胃小弯近幽门部"],"a":4,"e":"胃溃疡多发生于胃小弯靠近幽门部即胃窦部小弯侧，此处黏膜易受胃酸和胃蛋白酶侵蚀且血供相对较差。胃小弯近贲门部并非最好发部位；胃前壁、胃后壁及胃大弯、胃底溃疡发生率较低，其中胃大弯溃疡还需警惕恶性可能"},{"q":"发热患者高温持续期（高峰期）的热代谢特点是","o":["产热＞散热","散热＞产热","产热与散热在较高水平上保持相对平衡","产热障碍","散热障碍"],"a":2,"e":"发热的高峰期即高温持续期，体温已升至调定点水平，此时产热和散热在较高水平上保持相对平衡，故体温维持于高水平不再继续上升，患者自觉酷热、皮肤干燥。产热大于散热是体温上升期特点；散热大于产热是体温下降期特点；产热障碍或散热障碍并非发热高峰期的热代谢特征"},{"q":"周围型肺癌主要发生于","o":["肺泡上皮","肺泡囊及肺泡","呼吸性细支气管","肺段或其远端支气管","主支气管或肺叶支气管"],"a":3,"e":"周围型肺癌起源于肺段或其远端支气管，在肺周边部形成肿块，以腺癌最为多见。主支气管或肺叶支气管是中央型肺癌的发生部位；肺泡上皮、肺泡囊及肺泡、呼吸性细支气管与细支气管肺泡癌的发生相关，但并非周围型肺癌最主要的起源定位"},{"q":"休克发生时交感－肾上腺髓质系统处于","o":["强烈兴奋","强烈抑制","先兴奋后抑制","先抑制后兴奋","无明显反应"],"a":0,"e":"休克的各种动因如失血、创伤、感染均通过应激反应激活交感肾上腺髓质系统，使其强烈兴奋，血中儿茶酚胺即肾上腺素、去甲肾上腺素浓度急剧升高，引起心率加快、心肌收缩增强和外周血管收缩，是休克早期重要的代偿机制。抑制、先兴奋后抑制、先抑制后兴奋、无明显反应均不符合休克时的实际神经内分泌反应"},{"q":"良性肿瘤的异型性主要表现在","o":["瘤细胞大","瘤细胞核仁明显","细胞排列异常","核浓染","出现病理性核分裂象"],"a":2,"e":"良性肿瘤分化成熟，细胞异型性很小，其异型性主要表现为组织结构异常，即细胞排列紊乱、极性丧失，但细胞形态和核的异型性不明显。病理性核分裂象是恶性肿瘤的标志；瘤细胞大、核仁明显、核浓染均为细胞异型性表现，多见于恶性肿瘤，不属于良性肿瘤异型性的主要表现"},{"q":"阴道转移性肿瘤结节，切片镜下见血块有水泡状绒毛结构，滋养层细胞显著增生间变，应考虑为","o":["恶性畸胎瘤","畸胎瘤","葡萄胎","绒毛膜上皮癌","侵袭性葡萄胎"],"a":4,"e":"镜下见水泡状绒毛结构是侵蚀性葡萄胎与绒毛膜癌的关键鉴别点，前者保留绒毛结构并侵入肌层或发生远处转移，滋养层细胞显著增生并有间变。绒毛膜癌只见成片增生的滋养层细胞，无绒毛结构，是其与侵蚀性葡萄胎的根本区别；恶性畸胎瘤、畸胎瘤含多种胚层组织；葡萄胎局限于宫腔，不侵犯肌层或转移"},{"q":"引起低镁血症的原因不包括","o":["严重腹泻","醛固酮分泌减少","高钙血症","甲状旁腺功能低下","胰岛素的过量使用"],"a":1,"e":"低镁血症可由严重腹泻致镁丢失、高钙血症抑制肾小管对镁的重吸收、甲状旁腺功能低下使甲状旁腺素促镁重吸收作用减弱，以及胰岛素过量促使镁转入细胞内等因素引起。醛固酮促进肾脏排镁，其分泌减少时镁排泄减少、血镁趋于升高而非降低，故醛固酮分泌减少不是低镁血症的原因"},{"q":"下列属于常染色体显性遗传肿瘤的是","o":["乳腺癌","肾母细胞瘤","恶性黑色素瘤","肝癌","白血病"],"a":1,"e":"肾母细胞瘤即Wilms瘤存在常染色体显性遗传的家族性类型，与WT1等抑癌基因突变相关，是典型的遗传性肿瘤综合征之一。乳腺癌、恶性黑色素瘤、肝癌、白血病多为散发性，由环境与多基因因素共同作用，虽可有家族倾向但并非典型的常染色体显性遗传肿瘤"},{"q":"溶组织内阿米巴具有传染性的阶段是","o":["大滋养体","小滋养体","包囊","幼虫","成虫"],"a":2,"e":"溶组织内阿米巴的生活史包括包囊和滋养体两期，包囊是其感染期和传播阶段，成熟包囊随粪便排出，在外界抵抗力强，经口摄入后在小肠脱囊发育为滋养体。大滋养体是致病阶段，在外界很快死亡不具传染性；小滋养体、幼虫、成虫均不是溶组织内阿米巴的传染阶段"},{"q":"ARF初期少尿的主要机制是","o":["肾小球滤过系数降低","原尿回漏","肾小管阻塞","肾急性缺氧","肾血管及血流动力学的异常"],"a":4,"e":"急性肾衰竭初期少尿的核心机制是肾血管收缩、肾血流量下降及血流动力学紊乱，使肾小球滤过率急剧降低。肾血管及血流动力学异常包括肾皮质缺血、肾素-血管紧张素系统激活等，是起始且主导的因素。A项肾小球滤过系数降低是持续性少尿的后续机制而非初期主因；B项原尿回漏和C项肾小管阻塞均为肾小管损伤后的继发改变，多见于维持期；D项肾急性缺氧是血流动力学异常的结果而非独立主要机制"},{"q":"狂犬病具有特征性病理变化的是","o":["神经细胞胞质中发现嗜酸性包涵体（内基小体）","神经细胞变性与炎性病变","脑细胞充血、水肿、微小出血","急性弥漫性脑脊髓膜炎","血管周围单核细胞浸润"],"a":0,"e":"狂犬病的特征性病理改变是神经元胞质内出现嗜酸性包涵体，即内基小体，常见于海马及小脑浦肯野细胞，具有诊断意义。B项神经细胞变性与炎性病变、E项血管周围单核细胞浸润虽可见，但均为非特异性改变；C项脑细胞充血水肿微小出血也不具特征性；D项急性弥漫性脑脊髓膜炎是流行性脑脊髓膜炎的病变，与病毒性脑炎性质不同"},{"q":"下列哪项是伤口二期愈合的原因","o":["创面小","创面不洁，伴感染","手术切口","肉芽组织少","形成瘢痕小"],"a":1,"e":"二期愈合见于创面大、不洁、伴有感染或坏死组织多的伤口，需先控制感染、清除坏死组织，肉芽组织自底部向上填平，愈合慢、瘢痕大。创面不洁伴感染正是二期愈合的条件。A项创面小、C项手术切口均为一期愈合条件，边缘整齐对合好、愈合快；D项肉芽组织少不符合二期愈合，其肉芽组织反而丰富；E项形成瘢痕小是一期愈合特点，二期愈合瘢痕大"},{"q":"髓袢功能障碍可出现","o":["少尿无尿","多尿、低渗尿","肾小管性酸中毒","肾性尿崩症","钠、钾代谢障碍"],"a":1,"e":"髓袢升支粗段主动重吸收NaCl建立肾髓质高渗梯度，是尿液浓缩的关键。髓袢功能障碍时髓质高渗梯度不能建立，集合管重吸收水减少，出现多尿和低渗尿。A项少尿无尿多见于滤过率严重下降；C项肾小管性酸中毒主要与远曲小管排氢或近曲小管重吸收碳酸氢根障碍有关；D项肾性尿崩症为集合管对ADH不敏感；E项钠钾代谢障碍过于宽泛，非髓袢功能障碍的特征表现"},{"q":"引起脉压差增大的慢性瓣膜病是","o":["主动脉瓣口狭窄","主动脉瓣关闭不全","二尖瓣狭窄","二尖瓣关闭不全","二尖瓣狭窄及主动脉瓣口狭窄"],"a":1,"e":"主动脉瓣关闭不全时舒张期血液反流入左心室，舒张压显著降低，收缩压因每搏量增大而升高，故脉压差增大，并可出现水冲脉等周围血管征。C项二尖瓣狭窄及E项合并主动脉瓣狭窄主要影响左房充盈，脉压多减小；A项主动脉瓣口狭窄使收缩压降低、脉压减小；D项二尖瓣关闭不全脉压变化不显著，无典型脉压增大"},{"q":"可表现为两种血流动力学特点的休克类型是","o":["失血性休克","神经源性休克","感染性休克","过敏性休克","创伤性休克"],"a":2,"e":"感染性休克可表现为高排低阻的暖休克和低排高阻的冷休克两种血流动力学类型，早期多为高排低阻，随病情进展转为低排高阻。A项失血性休克和E项创伤性休克均属低血容量性，表现为低排高阻；B项神经源性休克和D项过敏性休克因血管扩张多呈高排低阻，但一般不出现典型的两种类型转变"},{"q":"细菌性痢疾传播途径为","o":["消化道传播","呼吸道传播","性传播","血液传播","飞沫传播"],"a":0,"e":"细菌性痢疾由志贺菌引起，经粪-口途径即消化道传播，常因污染的水源、食物或手经口感染。B项呼吸道传播和E项飞沫传播多见于流感、肺结核等呼吸道传染病；C项性传播见于梅毒、艾滋病等；D项血液传播见于乙型、丙型肝炎等，均不是菌痢的传播方式"},{"q":"慢性肾小球肾炎肾小球的病变特征是","o":["内皮细胞、系膜细胞增生","足细胞足突融合","毛细血管基膜弥漫性增厚","球囊壁层上皮细胞增生","玻璃样变和硬化"],"a":4,"e":"慢性肾小球肾炎的病变特点是大量肾小球发生玻璃样变和硬化，肾小管萎缩、间质纤维化，最终形成颗粒性固缩肾。A项内皮细胞和系膜细胞增生是急性弥漫性增生性肾小球肾炎的特点；B项足细胞足突融合见于脂性肾病；C项毛细血管基膜弥漫性增厚是膜性肾小球病特点；D项球囊壁层上皮细胞增生形成新月体，见于急进性肾小球肾炎"},{"q":"混合血栓是由下列哪些成分组成的","o":["血小板小梁，纤维素网，白细胞，红细胞","血小板小梁，白细胞，红细胞","纤维素网，白细胞，红细胞","血小板小梁，纤维素网，红细胞","血小板小梁，纤维素网，白细胞"],"a":0,"e":"混合血栓多见于静脉血栓的体部，由血小板小梁、纤维素网及网眼中填充的红细胞和白细胞共同构成，肉眼呈灰白与暗红相间的层状条纹。B项缺少纤维素网；C项缺少血小板小梁；D项缺少白细胞；E项缺少红细胞，成分均不完整。白色血栓主要由血小板和少量纤维素构成，红色血栓则以纤维素网和大量红细胞为主"},{"q":"微血管病性溶血性贫血的发生机制是","o":["微血管强烈收缩","微血管内皮细胞大量受损","纤维蛋白丝在微血管内形成细网","微血管内血流淤滞","血管壁通透性增加"],"a":2,"e":"微血管病性溶血性贫血见于DIC等，微血管内形成纤维蛋白丝细网，红细胞通过时被切割撕裂，形成盔形、三角形裂红细胞而发生溶血。A项微血管强烈收缩、D项血流淤滞可加重损伤但非直接切割机制；B项内皮细胞受损是DIC始动因素，但溶血直接由纤维蛋白网切割引起；E项血管壁通透性增加主要导致渗出，与红细胞破坏无直接关系"},{"q":"儿童中枢神经系统恶性肿瘤最常见的是","o":["脑膜瘤","神经元和混合性神经元-胶质肿瘤","中枢神经细胞瘤","神经鞘瘤和神经纤维瘤","胶质瘤和髓母细胞瘤"],"a":4,"e":"儿童中枢神经系统恶性肿瘤以胶质瘤（尤以小脑星形细胞瘤）和髓母细胞瘤最常见，多发生于小脑及第四脑室。A项脑膜瘤多为成人良性肿瘤；B项神经元和混合性神经元-胶质肿瘤、C项中枢神经细胞瘤均较少见；D项神经鞘瘤和神经纤维瘤多为外周神经来源且分级偏低"},{"q":"下列恶性肿瘤中发生转移几率最低的是","o":["鳞癌","骨肉瘤","乳头状腺癌","基底细胞癌","印戒细胞癌"],"a":3,"e":"基底细胞癌生长缓慢，主要局部浸润破坏，极少发生转移，转移几率最低。A项鳞癌、C项乳头状腺癌、E项印戒细胞癌均可经淋巴或血道转移；B项骨肉瘤恶性度高，早期即可血道转移至肺，转移几率很高"},{"q":"肾小管内出现均质红染管型，形似甲状腺滤泡，见于","o":["慢性肾盂肾炎","膀胱炎","急性弥漫性增生性肾小球肾炎","急性肾盂肾炎","尿道炎"],"a":0,"e":"肾小管腔内出现均质红染、形似甲状腺滤泡的管型，是慢性肾盂肾炎的特征性改变，由浓缩的蛋白分泌物形成，提示肾小管慢性损伤。B项膀胱炎、E项尿道炎为下尿路感染，不累及肾小管；C项急性弥漫性增生性肾小球肾炎以肾小球病变为主；D项急性肾盂肾炎为急性化脓性炎，中性粒细胞浸润为主，无此管型"},{"q":"关于氧疗,下列哪一项是错的","o":["血液性缺氧时因为PaO2 正常, 所以氧疗没有意义","氧疗对低张性缺氧的治疗效果最好","CO中毒可吸纯氧治疗","长时间吸入氧分压过高的气体可引起氧中毒的危险","组织性缺氧因供氧并无障碍，故氧疗的疗效有限"],"a":0,"e":"血液性缺氧如贫血、CO中毒，虽动脉血氧分压正常，但血红蛋白数量或质量改变致携氧障碍，提高吸入氧分压可增加血浆溶解氧，氧疗仍有一定意义，故所给说法错误。B项氧疗对低张性缺氧效果最好；C项CO中毒吸纯氧可加速一氧化碳排出；D项长时间高氧分压可致氧中毒；E项组织性缺氧供氧无障碍，氧疗疗效有限，均正确"},{"q":"血氧容量的大小取决于","o":["血氧分压","血氧含量","血氧饱和度","血红蛋白","2,3-DPG"],"a":3,"e":"血氧容量是每百毫升血液中血红蛋白充分结合氧的最大量，其大小取决于血红蛋白的质和量。A项血氧分压、B项血氧含量、C项血氧饱和度反映氧的供给与结合程度，不决定容量上限；E项2,3-DPG影响血红蛋白与氧的亲和力即氧解离曲线，并不改变血氧容量本身"},{"q":"关于宫颈原位癌的描述，错误的是","o":["可见病理性核分裂象","阴道脱落细胞涂片可呈阳性","局部淋巴结无转移","累及腺体时变为浸润癌","常由不典型增生发展而来"],"a":3,"e":"宫颈原位癌累及腺体时，癌细胞沿腺体基底膜生长，只要基底膜完整仍属原位癌，并非变为浸润癌，该描述错误。A项可见病理性核分裂象、B项阴道脱落细胞涂片可呈阳性、E项常由不典型增生发展而来均符合原位癌特点；C项局部淋巴结无转移是未突破基底膜的表现，正确"},{"q":"血氨升高抑制脑内丙酮酸氧化脱羧过程产生的直接后果是","o":["γ-氨基丁酸减少","乙酰辅酶A减少","谷氨酰胺增多","谷氨酸减少","α-酮戊二酸减少"],"a":1,"e":"丙酮酸氧化脱羧生成乙酰辅酶A，血氨升高消耗α-酮戊二酸并抑制该过程，直接导致乙酰辅酶A生成减少，影响能量代谢与三羧酸循环。A项γ-氨基丁酸减少是谷氨酸脱羧受抑的后续改变；C项谷氨酰胺增多是氨与谷氨酸结合的结果；D项谷氨酸减少、E项α-酮戊二酸减少均为氨解毒消耗的间接结果，非该过程的直接后果"},{"q":"肠阿米巴病最常见的发生部位是","o":["空肠","回肠","盲肠和升结肠","横结肠","乙状结肠和直肠"],"a":2,"e":"肠阿米巴病由溶组织内阿米巴引起，病变最常见于盲肠和升结肠，其次为乙状结肠和直肠，形成烧瓶状溃疡。A项空肠、B项回肠属小肠，不是阿米巴病好发部位；D项横结肠较少受累；E项乙状结肠和直肠也可发生但次于盲肠和升结肠"},{"q":"子宫腺肌病的主要病理学特征是","o":["子宫体积增大","子宫内膜增生","子宫壁肌层内形成平滑肌增生结节","子宫壁肌层出现子宫内膜腺体和间质","子宫内膜腺体出现在子宫外器官肌层"],"a":3,"e":"子宫腺肌病是子宫内膜腺体和间质侵入子宫肌层形成的良性病变，肌层内可见异位的子宫内膜腺体和间质，伴平滑肌增生。C项肌层内形成平滑肌增生结节是子宫肌瘤的特点，无内膜腺体；A项子宫体积增大、B项子宫内膜增生均无特异性；E项内膜腺体出现在子宫外器官肌层属子宫外子宫内膜异位症"},{"q":"下述关于肺淤血的描述，哪一项是错误的","o":["肺泡腔内有水肿液","肺泡壁毛细血管扩张","肺泡内中性粒细胞和纤维素渗出","可发生漏出性出血","常可见心力衰竭细胞"],"a":2,"e":"肺淤血为左心衰竭所致的静脉性充血，肺泡壁毛细血管扩张，肺泡腔内有水肿液及漏出性出血，可见含铁血黄素的心力衰竭细胞；中性粒细胞和纤维素渗出是肺炎等炎症的表现，不属于淤血。C项错误，为本题答案。A项肺泡腔内有水肿液、B项肺泡壁毛细血管扩张、D项可发生漏出性出血、E项常可见心力衰竭细胞均正确"},{"q":"肺鳞癌常见特点为","o":["肿瘤生长较慢，但转移较早，多为中央型，与吸烟史无关","肿瘤生长较慢，转移较晚，多为中央型，有吸烟史","肿瘤生长迅速，转移较早，多为中央型，与吸烟史无关","肿瘤生长迅速，但转移较晚，多为中央型，有吸烟史","肿瘤生长较慢，转移较晚，多为周围型，有吸烟史"],"a":1,"e":"肺鳞癌多见于男性吸烟者，生长较慢，转移较晚，多为中央型，起源于段以上支气管，可形成空洞。A项与吸烟史无关错误；C项生长迅速转移较早不符合鳞癌；D项生长迅速错误；E项多为周围型错误，鳞癌以中央型为主，周围型多为腺癌"},{"q":"单纯失性代偿性代谢性酸中毒时","o":["血pH、PaCO2及HCO3-均降低","血pH降低、PaCO2与HCO3-升高","血pH升高、PaCO2与HCO3-降低","血pH、PaCO2与HCO3-均升高","血pH升高、PaCO2降低、HCO3-升高"],"a":0,"e":"单纯失代偿性代谢性酸中毒时碳酸氢根原发性降低，呼吸代偿使动脉血二氧化碳分压继发性降低，但因失代偿血液pH仍降低，故三者均降低。B项二氧化碳分压与碳酸氢根升高不符合本病；C项pH升高错误；D项三者均升高错误；E项pH升高伴碳酸氢根升高是代谢性碱中毒的表现"},{"q":"下列各项中被称为“分子伴侣”的蛋白质是","o":["急性期反应蛋白","纤维连接蛋白","C反应蛋白","热休克蛋白","血红素结合蛋白"],"a":3,"e":"热休克蛋白又称分子伴侣，可帮助蛋白质正确折叠、组装和转运，防止错误折叠与聚集，应激时表达增加。A项急性期反应蛋白、C项C反应蛋白为急性期反应产物；B项纤维连接蛋白为细胞外基质糖蛋白；E项血红素结合蛋白为急性期蛋白，参与结合游离血红素，均不属于分子伴侣"},{"q":"向心性心肌肥大的特征是","o":["心肌纤维串联性增生","心肌纤维并联性增生","心腔扩大","心腔容积显著扩大与心室壁轻度增厚并存","心肌细胞数量增多"],"a":1,"e":"向心性心肌肥大由压力负荷即后负荷增加引起，心肌纤维呈并联性增生，肌纤维增粗，心室壁增厚而心腔不扩大。A项串联性增生见于容量负荷增加所致的离心性肥大；C项心腔扩大、D项心腔容积显著扩大伴室壁轻度增厚为离心性肥大特点；E项心肌细胞数量增多不成立，心肌细胞为永久性细胞，肥大时体积增大而非数量增多"},{"q":"前列腺素合成不足引起高血压的机制主要是","o":["抑制交感神经释放儿茶酚胺","降低血管平滑肌对缩血管物质的反应性","减弱对血管平滑肌收缩的抑制作用","抑制ADH的作用","抑制近曲小管对钠的重吸收"],"a":2,"e":"前列腺素如PGE2、PGI2为舒血管物质，可抑制血管平滑肌收缩、扩张血管并促进排钠。合成不足时其对血管平滑肌收缩的抑制作用减弱，外周阻力升高，参与高血压发生。A项抑制交感释放儿茶酚胺、B项降低血管平滑肌对缩血管物质的反应性、D项抑制抗利尿激素作用、E项抑制近曲小管重吸收钠均为前列腺素的效应，合成不足时这些作用减弱而非增强"},{"q":"在我国引起肝功能不全最常见的病因是","o":["肝毒性药物","免疫功能异常","遗传因素","生物性因素","营养不良"],"a":3,"e":"在我国，病毒性肝炎属生物性因素，是引起肝功能不全最常见的病因，尤以乙型肝炎多见。A项肝毒性药物、B项免疫功能异常、C项遗传因素、E项营养不良均可造成肝损伤，但总体发病率均低于病毒性肝炎，不是最常见病因"},{"q":"确诊支原体肺炎的依据是","o":["患者多为儿童和青少年","起病急，多有发热、头痛、咽痛及剧烈干咳","X线检查肺部呈段性分布的纹理增加及网状阴影","病变呈间质性炎，肺泡腔内可无渗出物","痰液中培养出支原体"],"a":4,"e":"支原体肺炎的确诊依赖病原学检查，痰液或呼吸道分泌物培养出肺炎支原体可确诊。A项患者多为儿童青少年、B项起病急伴发热头痛及剧烈干咳、C项X线呈段性纹理增加及网状阴影、D项病变呈间质性炎且肺泡腔可无渗出物均为临床与病理特点，只能提示诊断，不能作为确诊依据"},{"q":"普通型流脑特征性的病理变化是","o":["硬脑膜中性白细胞浸润","蛛网膜下腔有大量单核细胞","脑实质内软化灶形成","蛛网膜下腔大量中性白细胞浸润","硬脑膜有大量单核细胞浸润"],"a":3,"e":"流行性脑脊髓膜炎由脑膜炎奈瑟菌引起，属化脓性炎，特征为蛛网膜下腔大量中性粒细胞浸润，形成脓性渗出物。A项硬脑膜中性粒细胞浸润、E项硬脑膜大量单核细胞浸润均非本病典型部位，病变在软脑膜和蛛网膜；B项蛛网膜下腔大量单核细胞为病毒性脑炎特点；C项脑实质内软化灶为流行性乙型脑炎特点"},{"q":"左心衰竭引起淤血的器官是","o":["肺","脾","肝","胃肠道","下肢"],"a":0,"e":"左心衰竭时左心室排血减少，肺静脉回流受阻，血液淤积于肺循环，引起肺淤血甚至肺水肿。B项脾、C项肝、D项胃肠道、E项下肢淤血均为右心衰竭体循环淤血的表现，与左心衰竭无关"},{"q":"日本血吸虫引起的肝硬化为","o":["门脉性肝硬化","胆汁性肝硬化","坏死后性肝硬化","干线性肝硬化","淤血性肝硬化"],"a":3,"e":"日本血吸虫虫卵沉积于肝内门静脉分支周围，引起虫卵结节和纤维组织增生，形成沿门静脉分支分布的干线性肝硬化。A项门脉性肝硬化多由病毒性肝炎或酒精引起；B项胆汁性肝硬化与胆道阻塞相关；C项坏死后性肝硬化见于重症肝炎；E项淤血性肝硬化由慢性肝淤血引起"},{"q":"下列致瘤因素中，最常见的是","o":["化学因素","营养因素","生物因素","生活方式","遗传因素"],"a":0,"e":"在人类肿瘤病因中，化学因素如吸烟、职业暴露及食物中的致癌物最为常见，多数人类肿瘤与化学致癌物相关。B项营养因素、C项生物因素如病毒与细菌、D项生活方式、E项遗传因素均可致癌，但从总体构成看发病率均不及化学因素"},{"q":"皮肤恶性肿瘤的大体形态多为","o":["结节状","菜花状","乳头状","分叶状","息肉状"],"a":1,"e":"皮肤恶性肿瘤如鳞状细胞癌生长迅速，表面常破溃坏死，大体形态多呈菜花状或溃疡状。A项结节状、C项乳头状、D项分叶状、E项息肉状多见于良性肿瘤，一般边界清楚、生长缓慢，与恶性肿瘤的浸润破溃外观不同"},{"q":"肺性脑病的发生机制不包括","o":["脑血流量增加","脑毛细血管通透性增高","Na+-K+泵功能障碍","颅内压升高","氢离子浓度降低"],"a":4,"e":"肺性脑病由呼吸衰竭导致二氧化碳潴留和缺氧引起，二氧化碳升高使脑内氢离子浓度升高即呼吸性酸中毒，氢离子浓度降低不属于其机制。A项脑血流量增加、B项脑毛细血管通透性增高、C项钠钾泵功能障碍、D项颅内压升高均为二氧化碳潴留与缺氧引起的脑水肿及脑功能障碍机制"},{"q":"心功能不全时，下列哪项反应已失去代偿意义","o":["心脏紧张源性扩张","交感神经兴奋使心率加快","肾素-血管紧张素-醛固酮系统激活，血容量增加","组织摄氧和利用氧能力增强","心脏肌源性扩张"],"a":4,"e":"心脏肌源性扩张是心肌过度拉长、肌节超过最适长度的扩张，收缩力反而下降，心输出量减少，已失去代偿意义。A项紧张源性扩张伴心肌收缩力增强，仍有代偿意义；B项交感神经兴奋心率加快、C项肾素-血管紧张素-醛固酮系统激活使血容量增加、D项组织摄氧和利用氧能力增强均为心功能不全时的代偿反应"},{"q":"心肌脂肪变又称为","o":["绒毛心","虎斑心","靴形心","烧瓶心","盔甲心"],"a":1,"e":"心肌脂肪变时，脂肪变性的心肌细胞呈黄色，与正常心肌的暗红色相间，形成黄红相间的虎皮状条纹，称虎斑心。A项绒毛心为心包纤维素性炎；C项靴形心见于主动脉瓣关闭不全等；D项烧瓶心为心包积液；E项盔甲心为缩窄性心包炎"},{"q":"酒精性肝病，肝脏颜色变黄的原因是肝细胞发生了","o":["细胞水肿","色素形成","玻璃样变","坏死","脂肪变性"],"a":4,"e":"酒精性肝病时肝细胞发生脂肪变性，胞质内出现脂滴，使肝脏颜色变黄、体积增大。A项细胞水肿使肝细胞肿胀、颜色变淡；B项色素形成如脂褐素沉积使肝呈棕褐色；C项玻璃样变如Mallory小体为酒精性肝炎特点但不致肝黄；D项坏死为肝细胞死亡，不直接导致肝脏变黄"},{"q":"肾功能不全引起蛋白尿和血尿的重要原因是","o":["肾小球滤过膜通透性增加","GFR降低","肾小管损伤","尿路阻塞","肾内分泌功能障碍"],"a":0,"e":"蛋白尿和血尿主要因肾小球滤过膜即内皮细胞、基膜与足细胞裂孔膜受损，通透性增加，使蛋白和红细胞漏出。B项肾小球滤过率降低主要导致少尿和氮质血症；C项肾小管损伤影响重吸收，引起低分子蛋白尿及浓缩障碍；D项尿路阻塞、E项肾内分泌功能障碍与蛋白尿血尿关系不密切"},{"q":"肺源性心脏病病理诊断标准是","o":["心脏外观钝圆呈横位","右心室前壁肺动脉圆锥膨隆","右心室内乳头肌、肉柱增粗","三尖瓣狭窄伴关闭不全","肺动脉瓣下2cm处右心室壁厚度≥5mm"],"a":4,"e":"慢性肺源性心脏病的病理诊断标准为肺动脉瓣下2cm处右心室前壁肌层厚度达到或超过5mm，正常约为3至4mm，反映右心室肥大。A项心脏钝圆呈横位、B项肺动脉圆锥膨隆、C项乳头肌和肉柱增粗为大体形态改变，均非量化诊断标准；D项三尖瓣狭窄伴关闭不全不是肺心病必备病变"},{"q":"慢性肾小球肾炎的病理改变不包括","o":["形成颗粒性固缩肾","肾小球玻璃样变和硬化","出现“肾小球集中”现象","间质大量中性粒细胞浸润","肾内小动脉狭窄或闭塞"],"a":3,"e":"慢性肾小球肾炎以肾小球玻璃样变硬化、肾小管萎缩、间质慢性炎细胞浸润和纤维化为主，无大量中性粒细胞浸润，后者提示急性炎症。D项不包括，为本题答案。A项颗粒性固缩肾、B项肾小球玻璃样变和硬化、C项肾小球集中现象因肾小管萎缩致肾小球相对集中、E项肾内小动脉狭窄或闭塞均为慢性肾炎病变"},{"q":"急性弥漫性增生性肾小球肾炎主要增生的细胞是","o":["内皮细胞","系膜细胞","球囊脏层上皮细胞","球囊壁层上皮细胞","内皮细胞和系膜细胞"],"a":4,"e":"急性弥漫性增生性肾小球肾炎即链球菌感染后肾炎，病变特点是肾小球毛细血管内皮细胞和系膜细胞弥漫增生，伴中性粒细胞浸润。A项仅内皮细胞、B项仅系膜细胞均不全面；C项球囊脏层上皮细胞即足细胞一般不增生；D项球囊壁层上皮细胞增生形成新月体，为急进性肾小球肾炎特点"},{"q":"下列哪项不属于发热激活物","o":["葡萄球菌","溶血性链球菌","流感病毒","抗原抗体复合物","生理盐水"],"a":4,"e":"发热激活物是能激活产内生致热原细胞产生并释放内生致热原的物质，包括葡萄球菌、溶血性链球菌、流感病毒及抗原抗体复合物等。生理盐水为等渗溶液，不能激活产致热原细胞，不属于发热激活物。A项葡萄球菌、B项溶血性链球菌为细菌，C项流感病毒为病毒，D项抗原抗体复合物均为发热激活物"},{"q":"在肝性脑病发病中，色氨酸由外周血进入脑组织后发挥的作用是","o":["生成5-羟色胺","对抗乙酰胆碱","对抗去甲肾上腺素","直接抑制中枢神经系统","直接兴奋中枢神经系统"],"a":0,"e":"色氨酸入脑后经羟化、脱羧生成5-羟色胺，为抑制性神经递质，参与肝性脑病的神经抑制，同时还可生成犬尿氨酸等。B项对抗乙酰胆碱、C项对抗去甲肾上腺素为假性神经递质如羟苯乙醇胺的作用；D项直接抑制中枢、E项直接兴奋中枢均不准确，色氨酸通过代谢产物发挥作用"},{"q":"DIC患者出血与下列哪项因素关系最为密切","o":["凝血因子Ⅻ被激活","凝血因子大量消耗","FDP的形成","血管壁受损","抗凝血酶物质增加"],"a":1,"e":"弥散性血管内凝血患者出血的主要机制是凝血因子和血小板在微血栓形成过程中大量消耗，即消耗性凝血障碍，导致凝血功能低下。A项凝血因子十二被激活是内源性凝血始动环节；C项纤维蛋白降解产物形成有抗凝作用，加重出血但属继发因素；D项血管壁受损、E项抗凝血酶物质增加不是出血的主要机制"},{"q":"小叶性肺炎的常见并发症是","o":["肺气肿","感染性休克","肺肉质变","慢性支气管炎","心功能不全"],"a":4,"e":"小叶性肺炎的常见并发症包括呼吸衰竭、心功能不全、脓胸和肺脓肿等，婴幼儿及年老体弱者易发生心功能不全。A项肺气肿为慢性阻塞性肺疾病表现；B项感染性休克可发生但不如心功能不全常见；C项肺肉质变为大叶性肺炎并发症；D项慢性支气管炎为独立疾病，不是小叶性肺炎的并发症"},{"q":"男性生殖系统结核病多见于","o":["前列腺","精囊","输精管","附睾","睾丸"],"a":3,"e":"男性生殖系统结核多见于附睾，常继发于泌尿系统结核，表现为附睾肿大、质硬、结节，可形成窦道。A项前列腺、B项精囊、C项输精管也可受累但发病率低于附睾；E项睾丸结核较少见，多由附睾蔓延而来"},{"q":"下列激素中，影响钾跨细胞转移的主要是","o":["胰岛素","去甲肾上腺素","甲状腺素","生长激素","甲状旁腺素"],"a":0,"e":"胰岛素可促进细胞摄取钾，使钾由细胞外转移入细胞内，降低血钾，是影响钾跨细胞转移的主要激素，同时促进糖原与蛋白质合成。B项去甲肾上腺素、C项甲状腺素、D项生长激素、E项甲状旁腺素对钾跨细胞转移的影响均不如胰岛素显著"},{"q":"休克微循环缺血期发生的急性肾衰竭属于","o":["肾前性肾衰竭","肾后性肾衰竭","肾性肾衰竭","肾性和肾前性肾衰竭","器质性肾衰竭"],"a":0,"e":"休克微循环缺血期肾灌注不足、肾血流量减少，但肾实质尚未发生器质性损伤，属肾前性即功能性肾衰竭，及时恢复灌注可恢复。B项肾后性由尿路阻塞引起；C项肾性和E项器质性肾衰竭为肾实质损伤如急性肾小管坏死，多见于休克进展期；D项混合类型不符合缺血期特点"},{"q":"休克时最常出现的酸碱失衡是","o":["代谢性酸中毒","代谢性碱中毒","低钾性代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒"],"a":0,"e":"休克时组织缺血缺氧，无氧酵解增强，乳酸生成增多，加之肾功能障碍排酸减少，最常出现代谢性酸中毒。B项代谢性碱中毒、C项低钾性代谢性碱中毒多见于呕吐或利尿剂使用；D项呼吸性酸中毒见于通气障碍；E项呼吸性碱中毒可见于休克早期过度通气，但并非最常见"},{"q":"霍奇金淋巴瘤的病变中最具有诊断价值的细胞是","o":["R-S细胞","镜影细胞","隐窝细胞","多形性瘤细胞","未分化的细胞"],"a":1,"e":"霍奇金淋巴瘤的特征性细胞为里-施细胞，其中双核镜像对称的镜影细胞最具诊断价值，见于经典型霍奇金淋巴瘤。A项里-施细胞为统称，镜影细胞是其中典型且最具诊断价值者；C项隐窝细胞为变异型；D项多形性瘤细胞、E项未分化细胞均无特异性诊断价值"},{"q":"反常性酸性尿可见于","o":["高钾性酸中毒","呼吸性酸中毒","低钾性碱中毒","呼吸性碱中毒","乳酸酸中毒"],"a":2,"e":"低钾性碱中毒时细胞外液氢离子降低，肾小管上皮细胞内氢离子增多即细胞内酸中毒，远曲小管排氢增加，尿液反而呈酸性，称反常性酸性尿。A项高钾性酸中毒时细胞内氢离子减少、排氢减少，尿呈碱性即反常性碱性尿；B项呼吸性酸中毒、D项呼吸性碱中毒、E项乳酸酸中毒通常不出现反常性酸性尿"},{"q":"慢性阻塞性肺疾病产生呼气性呼吸困难的主要机制是","o":["中央型气道阻塞","呼气时气道内压大于大气压","胸内压升高压迫气道，气道狭窄加重","肺泡扩张，小气道口径变大","小气道阻力增加"],"a":4,"e":"慢性阻塞性肺疾病时小气道痉挛、黏膜肿胀、分泌物增多及肺泡壁破坏致小气道塌陷，呼气时小气道阻力显著增加，气体呼出困难，形成呼气性呼吸困难。A项中央型气道阻塞引起吸气性呼吸困难；B项呼气时气道内压大于大气压是正常力学变化，不是阻力增加的机制；C项胸内压升高压迫气道只是加重因素；D项肺泡扩张使小气道口径变大与实情相反"},{"q":"高分化肝细胞癌的主要的组织学特点是","o":["可分泌黏液","与肝细胞相似的癌细胞形成团块，癌细胞间有丰富的血窦样腔隙","形成巨细胞","分泌胆汁","肿瘤细胞弥漫散在分布"],"a":1,"e":"高分化肝细胞癌的癌细胞形态接近正常肝细胞，排列成索状或团块状，癌索间有丰富的血窦样腔隙，是其特征。A项分泌黏液多见于腺癌；C项形成巨细胞为某些未分化癌特点；D项分泌胆汁为肝细胞功能但非高分化肝癌的主要组织学特点；E项肿瘤细胞弥漫散在分布不符合高分化肝癌的索状团块排列"},{"q":"下列关于超急性排斥反应的描述，不正确的是","o":["可发生于移植后数分钟至数小时内","可发生于移植后1~3天内","可发生于受者、供者ABO血型不符者","可发生于受者血液循环中已有供体特异性HLA抗体存在","可发生急性小动脉炎、血栓形成和组织缺血性坏死"],"a":1,"e":"超急性排斥反应发生于移植后数分钟至数小时内，由受者体内预存的供体特异性抗体引起，移植后一至三天发生者属急性排斥反应，故该项描述不正确。A项数分钟至数小时内、C项ABO血型不符、D项已有供体特异性HLA抗体、E项急性小动脉炎血栓形成与组织缺血性坏死均为超急性排斥反应的特点"},{"q":"核受体本质上是配体依赖的","o":["G蛋白偶联受体","效应器","转录调节因子","离子通道受体","酪氨酸蛋白激酶"],"a":2,"e":"核受体位于胞质或胞核，与配体如类固醇激素、甲状腺激素结合后转位入核，作为转录调节因子调控靶基因转录。A项G蛋白偶联受体、D项离子通道受体、E项酪氨酸蛋白激酶受体均为膜受体；B项效应器为信号转导的下游成分，均不是核受体的本质"},{"q":"下列哪些因素会导致血液性缺氧","o":["动脉供血不足","法洛四联症","贫血","静脉血栓形成","心力衰竭"],"a":2,"e":"血液性缺氧因血红蛋白数量减少或质量异常导致携氧障碍，贫血时血红蛋白减少，属血液性缺氧。A项动脉供血不足、D项静脉血栓形成、E项心力衰竭均为循环性缺氧；B项法洛四联症因动静脉分流致血氧饱和度降低，属低张性缺氧"},{"q":"肾小球有效滤过压正常值约为","o":["20mmHg","25mmHg","30mmHg","40mmHg","60mmHg"],"a":1,"e":"肾小球有效滤过压等于肾小球毛细血管血压减去血浆胶体渗透压与肾小囊内压之和，正常约为25mmHg，是推动滤过的净压力。A项20mmHg、C项30mmHg、D项40mmHg均为常见近似值干扰；E项60mmHg接近肾小球毛细血管静水压本身而非净滤过压，需区分净压与毛细血管血压"},{"q":"关于肿瘤对机体的影响，下列说法中正确的是","o":["良性肿瘤患者常出现恶病质","良性肿瘤常引起异位内分泌综合征","良性肿瘤常引起出血和感染","恶性肿瘤可引起副肿瘤综合征","恶性肿瘤早期常引起顽固性疼痛"],"a":3,"e":"恶性肿瘤可通过分泌激素或细胞因子引起副肿瘤综合征，表现出内分泌、神经、皮肤等异常，且晚期常伴恶病质。A项恶病质为恶性肿瘤晚期表现，良性肿瘤一般不出现；B项异位内分泌综合征多见于恶性肿瘤如肺燕麦细胞癌；C项出血和感染多为恶性肿瘤浸润破坏或晚期表现；E项顽固性疼痛多为恶性肿瘤晚期侵犯神经所致"},{"q":"深部脓肿向体表或自然管道穿破，形成两个或两个以上开口的病理性通道，称为","o":["窦道","瘘管","穿孔","痈","溃疡"],"a":1,"e":"瘘管是深部脓肿向体表或自然管道穿破后形成的连接两个开口的病理性管道，如体表与空腔脏器之间或两个空腔脏器之间。A项窦道为仅有一个开口的盲端管道；C项穿孔为空腔脏器壁破裂；D项痈为多个毛囊的急性化脓性炎；E项溃疡为皮肤黏膜表面的局限性缺损"},{"q":"对人体造成严重后果的风湿病变发生在","o":["关节","血管","心脏","皮肤","脑"],"a":2,"e":"风湿病可累及心脏、关节、血管、皮肤和脑，其中心脏病变包括风湿性心内膜炎、心肌炎和心包炎，可导致心瓣膜病与心力衰竭，后果最严重。A项关节病变为游走性关节炎，多可完全吸收；B项血管病变、D项皮肤病变如环形红斑和皮下结节、E项脑病变即舞蹈病一般后果较轻或可自愈"},{"q":"X线摄片检查发现患者心脏呈梨形，常见于下列哪种疾病","o":["二尖瓣关闭不全","主动脉瓣关闭不全","二尖瓣狭窄","高血压病晚期","主动脉瓣狭窄"],"a":2,"e":"二尖瓣狭窄时左房血液流入左室受阻，左心房扩大、肺动脉高压致右心室扩大，心腰部饱满，心影呈梨形。A项二尖瓣关闭不全、B项主动脉瓣关闭不全主要引起左心室扩大，心影呈靴形；D项高血压病晚期左室肥大致靴形心；E项主动脉瓣狭窄左室肥厚，心影亦偏靴形"},{"q":"肢端肥大症时生长激素过度分泌的机制是","o":["生长激素释放激素合成过少","生长激素释放抑制激素合成过多","cAMP合成降低","基因突变抑制了GTP酶活性","生长激素受体增多"],"a":3,"e":"肢端肥大症多由垂体生长激素腺瘤引起，约四成病例存在G蛋白α亚基基因突变，抑制其GTP酶活性，使Gs持续激活、环磷酸腺苷持续升高，生长激素过度分泌。A项生长激素释放激素合成过少、B项生长抑素合成过多均会减少生长激素分泌；C项环磷酸腺苷合成降低与机制相反；E项生长激素受体增多不是生长激素过度分泌的原因"},{"q":"下列各项中，不属于胃黏膜防御功能的是","o":["黏液-碳酸氢盐屏障","黏膜上皮细胞之间紧密连接","黏膜上皮细胞再生能力强","黏膜血液循环减少","神经内分泌功能正常"],"a":3,"e":"胃黏膜血液循环减少会削弱黏膜屏障和修复能力，属于损害因素而非防御功能。A项黏液-碳酸氢盐屏障、B项上皮细胞紧密连接、C项上皮再生能力强、E项神经内分泌功能正常均为胃黏膜防御机制的组成部分"},{"q":"ACEI治疗心力衰竭的主要机制是","o":["降低血压，减轻心脏后负荷","减少醛固酮的分泌，从而减少降低容量负荷","抑制RAAS活性，延缓心室重构","抑制交感神经活性，减低心肌耗氧量","增强心肌收缩功能"],"a":2,"e":"血管紧张素转换酶抑制剂抑制转换酶，减少血管紧张素二和醛固酮生成，既扩张血管减轻负荷，更重要的是抑制心肌和血管重构，改善长期预后，是治疗心衰的核心。A项降低血压减轻后负荷、B项减少醛固酮降低容量负荷、D项抑制交感活性均为其作用但非核心；E项增强心肌收缩功能不是该类药物的作用"},{"q":"低渗性脱水的婴儿皮肤弹性降低、眼窝凹陷、囟门凹陷主要是由于","o":["血容量减少","细胞内液量减少","细胞外液量减少","淋巴液减少","组织间液减少"],"a":4,"e":"低渗性脱水时细胞外液渗透压降低，水向细胞内转移，细胞外液尤其组织间液明显减少，故皮肤弹性降低、眼窝和囟门凹陷等脱水征突出。A项血容量减少、C项细胞外液量减少为脱水表现，但上述体征主要与组织间液减少关系最密切；B项细胞内液量在低渗性脱水时反而增多；D项淋巴液减少非主要原因"},{"q":"溶血性链球菌主要引起的炎症是","o":["脓肿","出血性炎","假膜性炎","浆液性炎","蜂窝织炎"],"a":4,"e":"溶血性链球菌可产生透明质酸酶和链激酶，使炎症易于扩散，主要引起蜂窝织炎即疏松结缔组织的弥漫性化脓性炎。A项脓肿主要由金黄色葡萄球菌引起，为局限性化脓性炎；B项出血性炎如鼠疫、炭疽；C项假膜性炎如白喉、细菌性痢疾；D项浆液性炎如烫伤、风湿热"},{"q":"小叶性肺炎的病变特征为","o":["支气管及肺泡的卡他性炎","肺泡内的纤维素性炎","支气管及肺泡的出血性炎","支气管及肺泡的化脓性炎症","肺间质非化脓性炎"],"a":3,"e":"小叶性肺炎又称支气管肺炎，以细支气管为中心的肺组织化脓性炎为特征，细支气管及周围肺泡腔内充满中性粒细胞和脓细胞。A项卡他性炎为黏膜浅表炎症；B项纤维素性炎为大叶性肺炎特点；C项出血性炎非本病特征；E项肺间质非化脓性炎为病毒或支原体所致间质性肺炎特点"},{"q":"下列哪种物质与热限有关","o":["前列腺素E","环磷酸腺苷","Na+/Ca2+比值","促肾上腺皮质激素释放激素","精氨酸血管加压素"],"a":4,"e":"发热时体温升高存在上限即热限，与精氨酸血管加压素等负调节介质有关，该介质可限制体温过度升高。A项前列腺素E、B项环磷酸腺苷为正调节介质，促进发热；C项钠钙比值参与体温调节但非热限的主要物质；D项促肾上腺皮质激素释放激素参与应激，不是热限的核心介质"},{"q":"栓塞在肝内门静脉分支的栓子最可能来自于","o":["肠系膜动脉","肠系膜静脉","右心室","脾动脉","左心室"],"a":1,"e":"门静脉系统收集消化道血液，肠系膜静脉内血栓或栓子可随血流进入门静脉及其肝内分支引起栓塞。A项肠系膜动脉、D项脾动脉属体循环动脉，其栓子进入体循环动脉系统；C项右心室栓子进入肺动脉引起肺栓塞；E项左心室栓子进入体循环动脉，引起脑、肾等器官栓塞"},{"q":"下列哪一项是发热的中枢调节介质","o":["前列腺素A","前列腺素F","前列腺素D","前列腺素E","前列腺素I"],"a":3,"e":"前列腺素E是重要的中枢正调节介质，由下丘脑产生，可作用于体温调节中枢使调定点上移。A项前列腺素A、B项前列腺素F、C项前列腺素D、E项前列腺素I均不是主要的中枢发热介质，不能混淆"},{"q":"主动脉瓣狭窄的临床表现不包括","o":["血压下降，脉压减小","头晕","主动脉瓣区吹风样收缩期杂音","水冲脉","心绞痛"],"a":3,"e":"主动脉瓣狭窄时左室射血受阻，收缩压降低、脉压减小，表现为心绞痛、头晕、晕厥及主动脉瓣区喷射性收缩期杂音，无水冲脉。D项水冲脉是主动脉瓣关闭不全的周围血管征，不属于狭窄表现。A项血压下降脉压减小、B项头晕、C项主动脉瓣区收缩期杂音、E项心绞痛均为主动脉瓣狭窄表现"},{"q":"下述哪种细胞转化形式不属于化生范畴","o":["柱状上皮变为鳞状上皮","移行上皮变为鳞状上皮","胃黏膜上皮变为肠上皮","鳞状上皮变为柱状上皮","成纤维细胞变为纤维细胞"],"a":4,"e":"化生是一种分化成熟的组织转化为另一种分化成熟组织的过程，多见于上皮或间叶组织。成纤维细胞变为纤维细胞是同一细胞的功能状态改变，不属组织类型转化，不属于化生。A项柱状上皮变为鳞状上皮、B项移行上皮变为鳞状上皮、C项胃黏膜上皮变为肠上皮、D项鳞状上皮变为柱状上皮均为上皮化生"},{"q":"下列关于病毒性心肌炎的描述，错误的是","o":["心肌细胞变性坏死","淋巴细胞浸润","由嗜心肌病毒引起","多量中性粒细胞浸润","心肌间质纤维组织增生"],"a":3,"e":"病毒性心肌炎以心肌细胞变性坏死、淋巴细胞和单核细胞浸润为主，伴间质纤维组织增生，中性粒细胞浸润不是其特点而提示细菌感染。D项错误，为本题答案。A项心肌细胞变性坏死、B项淋巴细胞浸润、C项由嗜心肌病毒如柯萨奇病毒引起、E项心肌间质纤维组织增生均正确"},{"q":"伤寒所形成的肠道溃疡可表现为","o":["环形溃疡","烧瓶口状溃疡","地图状溃疡","火山口状溃疡","与肠的长轴平行的溃疡"],"a":4,"e":"伤寒由伤寒沙门菌引起，回肠末端集合淋巴结发生坏死脱落，形成与肠长轴平行的椭圆形溃疡，其长轴与肠管长轴一致。A项环形溃疡为肠结核特点；B项烧瓶口状溃疡为阿米巴痢疾特点；C项地图状溃疡为细菌性痢疾特点；D项火山口状溃疡为恶性肿瘤溃疡特点"},{"q":"发热时机体的代谢和功能改变，下列哪项描述是正确的","o":["糖原合成加强","脂肪分解加强","蛋白质合成加强","呼吸变浅、变慢","心率减慢"],"a":1,"e":"发热时交感神经兴奋、代谢率升高，糖原分解加强而合成减弱，脂肪分解加强，蛋白质分解加强，呼吸加深加快，心率加快。B项正确。A项糖原合成加强、C项蛋白质合成加强均与分解代谢增强相反；D项呼吸变浅变慢、E项心率减慢均与发热时的功能改变相反"},{"q":"关于肝硬化假小叶的病变的描述，错误的是","o":["小叶内肝细胞变性、坏死和再生同时存在","小叶内缺少中央静脉","小叶内中央静脉偏位或有两个以上","小叶内肝细胞排列紊乱","小叶内不会出现汇管区"],"a":4,"e":"假小叶内可因纤维组织包绕原有肝小叶或再生结节而将汇管区包入，故小叶内不会出现汇管区的说法错误，为本题答案。A项小叶内肝细胞变性坏死和再生同时存在、B项小叶内缺少中央静脉、C项中央静脉偏位或有两个以上、D项肝细胞排列紊乱均为假小叶的特点"},{"q":"不符合２型糖尿病病因的描述是","o":["与胰岛素作用不足有关","与自身免疫有关","与遗传因素有关","与肥胖有关","与胰岛素抵抗性有关"],"a":1,"e":"二型糖尿病的病因与遗传、肥胖、胰岛素抵抗及胰岛素作用不足有关；自身免疫介导的胰岛β细胞破坏是一型糖尿病的病因，与二型无关。B项为本题答案。A项与胰岛素作用不足有关、C项与遗传因素有关、D项与肥胖有关、E项与胰岛素抵抗性有关均符合二型糖尿病病因"},{"q":"对组织性缺氧最有诊断价值的血氧指标是哪一项","o":["动-静脉血氧含量差","动脉血氧含量","动脉血氧容量","动脉血氧饱和度","动脉血氧分压"],"a":0,"e":"组织性缺氧时组织利用氧发生障碍，动静脉血氧含量差显著减小，静脉血氧含量升高，是最有诊断价值的指标。B项动脉血氧含量、C项动脉血氧容量、D项动脉血氧饱和度、E项动脉血氧分压在组织性缺氧时一般正常，不能反映组织摄氧障碍"},{"q":"下列属APUD肿瘤的是","o":["乳腺髓样癌","鼻咽泡状核细胞癌","甲状腺髓样癌","肠印戒细胞癌","单纯癌"],"a":2,"e":"APUD肿瘤起源于弥散神经内分泌系统，甲状腺髓样癌由滤泡旁C细胞即神经内分泌细胞发生，分泌降钙素，属APUD肿瘤。A项乳腺髓样癌、B项鼻咽泡状核细胞癌、D项肠印戒细胞癌、E项单纯癌均为普通上皮性恶性肿瘤，不属于APUD肿瘤"},{"q":"引起低渗性脱水的最常见原因是","o":["长期连续使用利尿剂","呕吐、腹泻后只补充水分","肾上腺皮质功能降低","大面积烧伤","慢性间质性肾炎"],"a":1,"e":"低渗性脱水因失钠多于失水，最常见于呕吐、腹泻等丢失等渗或低渗液体后只补充水分而未补钠，使细胞外液渗透压降低。A项长期连续使用利尿剂、C项肾上腺皮质功能降低、D项大面积烧伤、E项慢性间质性肾炎也可引起，但均不如补液不当常见"},{"q":"“气球样变”指的是下列哪种病理变化","o":["脂肪变","玻璃样变","淀粉样变","重度细胞水肿","黏液样变"],"a":3,"e":"气球样变是重度细胞水肿的表现，肝细胞等高度肿胀呈球形、胞质疏松透明似气球，常见于病毒性肝炎。A项脂肪变为胞质内脂滴；B项玻璃样变为细胞内或间质均质红染物质；C项淀粉样变为淀粉样蛋白沉积；E项黏液样变为间质黏液样物质积聚"},{"q":"下列哪种混合性酸碱平衡紊乱不可能出现","o":["呼吸性酸中毒合并代谢性酸中毒","呼吸性碱中毒合并代谢性碱中毒","呼吸性酸中毒合并代谢性酸中毒合并代谢性碱中毒","呼吸性酸中毒合并呼吸性碱中毒","代谢性酸中毒合并代谢性碱中毒"],"a":3,"e":"呼吸性酸中毒与呼吸性碱中毒均源于二氧化碳分压的原发性改变，二者方向相反，同一二氧化碳分压不可能同时原发性升高和降低，故该组合不可能出现。A项呼酸合并代酸、B项呼碱合并代碱、C项呼酸合并代酸再合并代碱、E项代酸合并代碱均为临床可出现的混合性紊乱"},{"q":"体液免疫缺陷患者临床可表现为连绵不断的微生物感染，主要是","o":["真菌感染","细菌感染","病毒感染","胞内寄生菌感染","原虫感染"],"a":1,"e":"体液免疫即B细胞与抗体缺陷患者对化脓性细菌感染易感，因抗体中和及调理作用缺失，表现为反复化脓性细菌感染。A项真菌感染、C项病毒感染、D项胞内寄生菌感染、E项原虫感染主要与细胞免疫即T细胞缺陷有关，不是体液免疫缺陷的主要表现"},{"q":"濒死期时","o":["脑干以上部位处于深度抑制状态","延髓处于深度抑制状态","全脑机能永久性丧失","脊髓功能处于抑制状态","小脑功能丧失"],"a":0,"e":"濒死期大脑皮质及脑干以上部位处于深度抑制，意识模糊或丧失，各种反射减弱，呼吸循环衰竭，但延髓生命中枢尚未完全停止。B项延髓处于深度抑制为临床死亡期表现；C项全脑机能永久性丧失为脑死亡；D项脊髓功能抑制、E项小脑功能丧失均不是濒死期的主要特征"},{"q":"主动脉粥样硬化一般不引起","o":["管腔狭窄","血栓形成","溃疡形成","动脉瘤形成","动脉中层钙化"],"a":0,"e":"主动脉管径大，粥样斑块通常不足以引起明显管腔狭窄，其主要后果是动脉瘤形成、血栓形成、溃疡及动脉中层钙化等。A项管腔狭窄一般不引起，为本题答案。B项血栓形成、C项溃疡形成、D项动脉瘤形成、E项动脉中层钙化均为主动脉粥样硬化的病变或并发症"},{"q":"可产生大量胶原以促使肝硬化发生的细胞是","o":["肝细胞","星状细胞","肝窦内皮细胞","Kupffer细胞","大淋巴细胞"],"a":1,"e":"肝星状细胞在肝损伤时活化转化为肌成纤维样细胞，大量合成胶原等细胞外基质，是肝纤维化和肝硬化胶原沉积的主要来源。A项肝细胞为实质细胞；C项肝窦内皮细胞参与滤过；D项Kupffer细胞为巨噬细胞，主要吞噬并分泌细胞因子；E项大淋巴细胞参与免疫，均非胶原的主要产生细胞"},{"q":"应激反应中，可发挥负调控作用的激素是","o":["胰高血糖素","胰岛素","醛固酮","β-内啡肽","肾上腺素"],"a":3,"e":"β-内啡肽为应激时释放的阿片样肽，可抑制促肾上腺皮质激素释放激素及交感活性，对应激反应发挥负反馈调控，防止反应过度。A项胰高血糖素、B项胰岛素、C项醛固酮、E项肾上腺素均为应激时升高并参与正性应激反应的激素"},{"q":"下列各项因素中不参与水、钠平衡调节的是","o":["抗利尿激素","醛固酮","渴感中枢","心房钠尿肽","胰岛素"],"a":4,"e":"水钠平衡调节主要依赖抗利尿激素、醛固酮、心房钠尿肽及渴感中枢等，胰岛素主要调节糖代谢，虽能促进细胞摄钾并有一定促肾小管重吸收钠的作用，但不属于水钠平衡的主要调节因素。A项抗利尿激素、B项醛固酮、C项渴感中枢、D项心房钠尿肽均直接参与水钠平衡调节"},{"q":"肾脏恶性肿瘤最常见的组织学亚型是","o":["乳头状肾细胞癌","透明细胞性肾细胞癌","小细胞癌","鳞状细胞癌","尿路上皮癌"],"a":1,"e":"透明细胞性肾细胞癌是肾细胞癌中最常见的亚型，约占七至八成，镜下癌细胞胞质透明、富含糖原和脂质。A项乳头状肾细胞癌为第二常见亚型；C项小细胞癌、D项鳞状细胞癌在肾脏罕见；E项尿路上皮癌主要发生于肾盂，属上尿路上皮肿瘤而非肾实质肿瘤"},{"q":"应激时，促使GC分泌增加的神经内分泌反应是","o":["蓝斑-交感-肾上腺皮质系统兴奋","蓝斑-垂体-肾上腺髓质系统兴奋","下丘脑-垂体-肾上腺髓质系统兴奋","下丘脑-垂体-肾上腺皮质系统兴奋","下丘脑-垂体-促性腺系统兴奋"],"a":3,"e":"应激时下丘脑-垂体-肾上腺皮质轴兴奋，促肾上腺皮质激素释放激素促使ACTH分泌，进而使糖皮质激素分泌增加，是糖皮质激素升高的主要机制。A项蓝斑-交感-肾上腺皮质系统、B项蓝斑-垂体-肾上腺髓质系统、C项下丘脑-垂体-肾上腺髓质系统均非正确通路，髓质分泌儿茶酚胺；E项下丘脑-垂体-促性腺系统兴奋与糖皮质激素分泌无关且应激时常受抑制"},{"q":"p53基因突变后，细胞发生癌变的主要原因","o":["细胞钙稳态失衡","细胞增殖能力增强","免疫监视作用减弱","DNA异常的细胞直接进入S期","DNA异常的细胞停滞在G1期"],"a":3,"e":"p53为抑癌基因，正常情况下使DNA损伤细胞停滞于G1期进行修复，修复失败则诱导凋亡。突变后失去该监控功能，DNA异常细胞不能停滞而直接进入S期，带着突变DNA复制导致癌变。E项DNA异常细胞停滞在G1期是p53的正常功能，突变后恰相反；A项钙稳态失衡、B项增殖能力增强、C项免疫监视减弱均非p53突变的直接主要后果"},{"q":"在IgA肾病免疫荧光检查中，IgA的沉积方式是","o":["上皮下沉积","沿基底膜呈颗粒状沉积","系膜区沉积","内皮下沉积","沿基底膜呈线状沉积"],"a":2,"e":"IgA肾病以IgA1在肾小球系膜区沉积为特征，免疫荧光见系膜区颗粒状或团块状IgA沉积，常伴补体C3沉积。A项上皮下沉积常见于膜性肾病；B项沿基底膜呈颗粒状沉积为膜性肾小球病；D项内皮下沉积见于狼疮性肾炎等；E项沿基底膜呈线状沉积为抗基底膜病"},{"q":"慢性浅表性胃炎胃镜下观察表现主要为","o":["胃黏膜薄而平滑","胃黏膜皱襞变浅或消失","黏膜下血管清晰可见","局部黏膜充血、水肿，表面有灰白色或灰黄色分泌物","胃黏膜由橘红色变为灰白色"],"a":3,"e":"慢性浅表性胃炎胃镜下见黏膜充血水肿、红白相间，表面可附着灰白色或灰黄色黏液分泌物，病变局限于黏膜浅层。A项胃黏膜薄而平滑、B项皱襞变浅或消失、C项黏膜下血管清晰可见、E项黏膜由橘红色变为灰白色均为慢性萎缩性胃炎的表现，即黏膜变薄与血管透见"},{"q":"被称为良性应激的是","o":["躯体性应激","心理性应激","生理性应激","病理性应激","所有应激反应"],"a":2,"e":"生理性应激如适度运动、环境温度变化等引起的应激强度适中、持续时间短，对机体有利，称为良性应激。A项躯体性应激、B项心理性应激按应激源性质分类；D项病理性应激强度大持续久，对机体有害，属恶性应激；E项所有应激反应过于宽泛，并非都是良性"},{"q":"炎症时，白细胞经血管壁游出到血管外并在炎区聚集的现象称为","o":["白细胞边集","白细胞黏附","炎细胞浸润","白细胞游出","白细胞滚动"],"a":2,"e":"白细胞穿过血管壁后在炎区组织间隙聚集的现象称炎细胞浸润。A项白细胞边集为白细胞靠近血管壁；B项黏附为白细胞黏附于内皮；D项白细胞游出为白细胞穿过血管壁的过程，是浸润的前提步骤；E项滚动为白细胞沿内皮滚动，这几项均为渗出的不同阶段，而游出并聚集强调的是结果"},{"q":"恶性肿瘤对机体的影响不包括","o":["压迫破坏周围组织","肿瘤组织易出血、坏死","浸润神经引起疼痛","机体代谢增强","晚期形成恶病质"],"a":3,"e":"恶性肿瘤对机体的影响包括压迫破坏周围组织、浸润神经引起疼痛、易出血坏死及晚期恶病质等，而机体代谢增强并非其对机体的影响。D项不包括，为本题答案。A项压迫破坏周围组织、B项易出血坏死、C项浸润神经引起疼痛、E项晚期形成恶病质均为恶性肿瘤的影响"},{"q":"某呼吸衰竭患者血气分析结果pH：7、02，PaCO2：60mmHg，PaO2：37、5mmHg，HCO3－：26mmol/L ，问并发何种酸碱平衡紊乱","o":["急性呼吸性酸中毒","慢性呼吸性酸中毒","急性呼吸性酸中毒合并代谢性酸中毒","代谢性酸中毒","慢性呼吸性酸中毒合并代谢性酸中毒"],"a":0,"e":"患者动脉血二氧化碳分压显著升高至60mmHg并使pH降至7.02，而碳酸氢根仅轻度升高接近正常，说明肾脏尚未来得及充分代偿，符合急性呼吸性酸中毒。B项慢性呼吸性酸中毒时碳酸氢根应明显升高；C项合并代谢性酸中毒时碳酸氢根应降低；D项代谢性酸中毒以碳酸氢根原发降低、二氧化碳分压代偿降低为特点；E项慢性呼酸合并代酸碳酸氢根不会仅轻度升高"},{"q":"下列哪项不是大肠癌的常见肉眼形态","o":["隆起型","溃疡型","浸润型","缩窄型","胶样型"],"a":3,"e":"大肠癌常见肉眼形态包括隆起型、溃疡型、浸润型和胶样型，缩窄型不是其常见肉眼类型。D项为本题答案。A项隆起型、B项溃疡型、C项浸润型、E项胶样型均为大肠癌的常见大体类型，其中浸润型可致肠壁增厚与管腔狭窄但类型名称为浸润型"},{"q":"肺源性心脏病最常见的原因是","o":["支气管哮喘","支气管扩张","慢性支气管炎","肺结核病","硅沉着病"],"a":2,"e":"慢性肺源性心脏病最常见病因是慢性支气管炎并发阻塞性肺气肿，长期气道阻塞导致通气换气障碍和肺动脉高压。A项支气管哮喘、B项支气管扩张、D项肺结核病、E项硅沉着病均可引起肺心病，但发病率远低于慢性支气管炎"},{"q":"左心衰竭患者发生呼吸困难的原因是","o":["低血压","体循环淤血，回心血量减少","肺淤血、肺水肿","心肌缺血缺氧","肺动脉高压"],"a":2,"e":"左心衰竭时左心排血减少，肺静脉压升高导致肺淤血和肺水肿，肺顺应性下降、气体交换障碍，引起劳力性呼吸困难、端坐呼吸及夜间阵发性呼吸困难。A项低血压、B项体循环淤血回心血量减少为右心衰竭表现；D项心肌缺血缺氧为冠心病机制；E项肺动脉高压为肺心病机制"},{"q":"慢性支气管炎黏膜上皮容易发生的化生类型是","o":["黏液上皮化生","移行上皮化生","鳞状上皮化生","杯状上皮化生","肠上皮化生"],"a":2,"e":"慢性支气管炎时假复层纤毛柱状上皮在慢性刺激下转化为鳞状上皮，即鳞状上皮化生，纤毛减少使防御功能下降。A项黏液上皮化生、B项移行上皮化生、D项杯状上皮化生、E项肠上皮化生均不是慢性支气管炎的典型化生类型，肠上皮化生多见于胃黏膜"},{"q":"心力衰竭细胞见于左心衰竭时，巨噬细胞吞噬了","o":["肺泡内尘埃颗粒","肺泡内红细胞","肺泡内纤维素样坏死物","心脏心肌细胞","血浆蛋白"],"a":1,"e":"左心衰竭肺淤血时，肺泡腔内漏出的红细胞被巨噬细胞吞噬，胞质内形成含铁血黄素，这种细胞称心力衰竭细胞。A项肺泡内尘埃颗粒被吞噬形成尘细胞；C项纤维素样坏死物、D项心肌细胞、E项血浆蛋白均不是心力衰竭细胞吞噬的内容物"},{"q":"慢性炎症病灶内浸润的炎细胞主要是","o":["中性粒细胞和单核细胞","淋巴细胞和单核细胞","浆细胞和嗜碱性粒细胞","嗜酸性粒细胞和嗜碱性粒细胞","中性粒细胞和嗜酸性粒细胞"],"a":1,"e":"慢性炎症以淋巴细胞、单核细胞即巨噬细胞和浆细胞浸润为主，伴纤维组织增生。A项中性粒细胞和单核细胞、E项中性粒细胞和嗜酸性粒细胞以中性粒细胞为主提示急性炎症；C项浆细胞和嗜碱性粒细胞、D项嗜酸性粒细胞和嗜碱性粒细胞的组合均不符合慢性炎症特点，嗜酸性粒细胞多见于过敏或寄生虫感染"},{"q":"如果AG正常则不可能出现","o":["代谢性酸中毒","代谢性碱中毒","呼吸性酸中毒","呼吸性碱中毒","三重性酸碱平衡紊乱"],"a":4,"e":"三重性酸碱平衡紊乱必然包含代谢性酸中毒成分，需依靠阴离子间隙升高来判定，若阴离子间隙正常则无从确立该成分，故三重性紊乱不可能出现。A项代谢性酸中毒可为正常阴离子间隙即高氯性；B项代谢性碱中毒、C项呼吸性酸中毒、D项呼吸性碱中毒在阴离子间隙正常时均可单独存在"},{"q":"下列关于肉瘤的描述，错误的是","o":["骨肉瘤是最常见的骨恶性肿瘤","纤维肉瘤是软组织中发病率高的肉瘤","血管肉瘤起源于血管内皮细胞","脂肪肉瘤常发生于大腿深部的软组织或腹膜后","葡萄状肉瘤是发生于泌尿生殖道的横纹肌肉瘤"],"a":1,"e":"软组织肉瘤中发病率高的是脂肪肉瘤、横纹肌肉瘤和平滑肌肉瘤等，纤维肉瘤发病率相对较低，故该描述错误。A项骨肉瘤是最常见的骨恶性肿瘤、C项血管肉瘤起源于血管内皮细胞、D项脂肪肉瘤常发生于大腿深部软组织或腹膜后、E项葡萄状肉瘤为泌尿生殖道的胚胎性横纹肌肉瘤均正确"},{"q":"高血压性肾病的病理改变不包括","o":["肾动脉纤维素样坏死","部分肾小球纤维化","入球小动脉玻璃样变","部分肾小球代偿性肥大","肾小管内可见蛋白管型"],"a":0,"e":"高血压性肾病即良性高血压肾硬化，主要表现为入球小动脉玻璃样变和小动脉硬化，肾小球纤维化与代偿性肥大，肾小管内蛋白管型，不出现肾动脉纤维素样坏死，后者为恶性高血压特点。A项不包括，为本题答案。B项部分肾小球纤维化、C项入球小动脉玻璃样变、D项部分肾小球代偿性肥大、E项肾小管内蛋白管型均为高血压肾病改变"},{"q":"尿毒症患者最早出现和最突出的症状是","o":["皮肤瘙痒和尿素霜","Kussmaul呼吸、呼气有氨味、肺水肿等","充血性心力衰竭和心律失常","食欲减退、恶心、呕吐、腹泻、口腔黏膜溃疡等","不安、思维不集中、记忆力减退、失眠等"],"a":3,"e":"尿毒症时消化系统症状出现最早且最突出，表现为食欲减退、恶心、呕吐、腹泻及口腔黏膜溃疡等，因尿素等毒素刺激胃肠道黏膜所致。A项皮肤瘙痒和尿素霜、B项库斯莫尔呼吸与呼气氨味及肺水肿、C项充血性心力衰竭和心律失常、E项不安与记忆力减退失眠均为尿毒症表现，但出现较晚或不最早最突出"},{"q":"低镁血症可引起","o":["低钾血症和低钙血症","高钾血症和低钙血症","低钾血症和高钙血症","高钾血症和高钠血症","低钾血症和低钠血症"],"a":0,"e":"低镁血症时镁离子对肾小管钠钾交换的抑制减弱，钾排出增多致低钾血症；低镁还抑制甲状旁腺激素分泌并阻碍骨钙动员，引起低钙血症。B项高钾血症、C项高钙血症、D项高钾高钠、E项低钾低钠的电解质组合均不符合低镁血症的改变"},{"q":"原发性膜性肾小球病的免疫荧光特点是IgC和C3沉积于","o":["系膜区","基底膜，呈颗粒状","上皮下","内皮下","基底膜，呈线性"],"a":2,"e":"原发性膜性肾小球病即膜性肾病，免疫荧光见IgG和补体C3沿毛细血管壁呈颗粒状沉积，电镜证实沉积物位于上皮下即脏层上皮细胞与基底膜之间，伴基底膜增厚和钉突形成。C项为本题答案。A项系膜区沉积见于IgA肾病；B项基底膜颗粒状沉积为光镜免疫荧光描述，本质定位在上皮下；D项内皮下沉积见于膜增生性肾炎；E项基底膜线性沉积见于抗基底膜病"},{"q":"肺癌沿淋巴道转移时，首先转移到","o":["纵膈淋巴结","颈部淋巴结","锁骨上淋巴结","肺门淋巴结","腋窝淋巴结"],"a":3,"e":"肺癌沿淋巴道转移首先到达肺门及支气管旁淋巴结，再累及纵隔淋巴结，晚期可转移至锁骨上淋巴结。A项纵隔淋巴结为第二站；B项颈部淋巴结、C项锁骨上淋巴结属远处淋巴结转移，多为晚期；E项腋窝淋巴结不是肺癌淋巴转移的首站"},{"q":"黄嘌呤氧化酶主要存在于","o":["毛细血管内皮细胞内","结缔组织细胞内","巨噬细胞内","白细胞内","肌细胞内"],"a":0,"e":"黄嘌呤氧化酶由黄嘌呤脱氢酶转化而来，主要存在于毛细血管内皮细胞，参与嘌呤代谢生成尿酸，并在缺血再灌注损伤中催化产生氧自由基。B项结缔组织细胞、C项巨噬细胞、D项白细胞、E项肌细胞内该酶含量均少或不是主要存在部位，白细胞中富含的是髓过氧化物酶等"},{"q":"系统性红斑狼疮最特异性的病变是","o":["面部蝶形红斑","肾损害","脾洋葱皮样结构","关节损害","狼疮细胞"],"a":4,"e":"狼疮细胞是系统性红斑狼疮的特征性发现，指中性粒细胞吞噬了被抗核抗体致敏的细胞核即均质体所形成的细胞，特异性较高。A项面部蝶形红斑虽典型但特异性不及狼疮细胞；B项肾损害、D项关节损害可见于多种疾病；C项脾洋葱皮样结构为脾小动脉周围纤维化，有一定特征性但不如狼疮细胞特异"},{"q":"导致GFR下降的肾血流量减少，可见于动脉血压降至","o":["40mmHg以下","50mmHg以下","60mmHg以下","80mmHg以下","100mmHg以下"],"a":3,"e":"肾血流自身调节范围约为动脉血压80至180mmHg，当血压降至80mmHg以下时，肾血流量和肾小球滤过率随血压下降而明显减少。A项40mmHg以下、B项50mmHg以下、C项60mmHg以下时滤过已严重下降甚至停止；E项100mmHg以下仍处自身调节范围内，滤过率保持相对稳定"},{"q":"血吸虫病时形成的虫卵结节中不含有","o":["干酪样坏死","上皮样细胞","多核巨细胞","淋巴细胞","肉芽组织"],"a":0,"e":"血吸虫虫卵结节即肉芽肿，由上皮样细胞、多核巨细胞、淋巴细胞和纤维组织即肉芽组织构成，中心为虫卵，不发生干酪样坏死，后者是结核结节的特点。A项不含有，为本题答案。B项上皮样细胞、C项多核巨细胞、D项淋巴细胞、E项肉芽组织均为虫卵结节的成分"},{"q":"蕈样肉芽肿的起源为","o":["组织细胞来源","B细胞来源","原发于颈部淋巴结","原发于中枢神经","T细胞来源"],"a":4,"e":"蕈样肉芽肿又称蕈样真菌病，是原发于皮肤的辅助性T细胞淋巴瘤，起源于T细胞。A项组织细胞来源、B项B细胞来源均不符合；C项原发于颈部淋巴结、D项原发于中枢神经均错误，本病原发于皮肤而非淋巴结或中枢"},{"q":"急性呼吸性酸中毒较之急性代谢性酸中毒，下述哪个系统的功能障碍更严重","o":["中枢神经系统","心血管系统","泌尿系统","运动系统","血液系统"],"a":0,"e":"急性呼吸性酸中毒时二氧化碳分压迅速升高，二氧化碳易透过血脑屏障，使脑内氢离子浓度快速升高，引起脑血管扩张、脑水肿及中枢抑制即二氧化碳麻醉，中枢神经系统症状较代谢性酸中毒更重。B项心血管系统、C项泌尿系统、D项运动系统、E项血液系统受累均不如中枢神经系统突出"},{"q":"下列指标均需在标准条件下测定，除了","o":["BB","AG","SB","AB","BE"],"a":3,"e":"实际碳酸氢盐是在患者实际二氧化碳分压和体温条件下测得的血浆碳酸氢根，受呼吸影响，不需标准条件。标准碳酸氢盐、缓冲碱和碱剩余均在标准条件下测定；阴离子间隙为电解质计算值。D项为本题答案，A项缓冲碱、C项标准碳酸氢盐、E项碱剩余均需标准条件"},{"q":"能将心肌的兴奋和收缩耦联在一起的因子是","o":["Mg2+","Ca2+","K+","Na+","Cl-"],"a":1,"e":"钙离子是心肌兴奋-收缩耦联的关键因子，动作电位去极化激活L型钙通道，钙内流触发肌质网释放钙，胞质钙升高与肌钙蛋白结合启动收缩。A项镁离子为多种酶的辅因子；C项钾离子、D项钠离子参与动作电位形成；E项氯离子参与复极，均非耦联因子"},{"q":"脂性肾病电镜下肾小球特征性病变是","o":["肾小球毛细血管基底膜上皮侧可见致密沉积物","肾小球系膜增生","肾小球内皮细胞显著增生肥大","肾小球壁层上皮细胞增生形成新月体","肾小球脏层上皮细胞足突消失"],"a":4,"e":"脂性肾病即微小病变肾病，电镜特征为脏层上皮细胞即足细胞足突广泛融合消失，光镜下肾小球基本正常，临床表现为肾病综合征。A项上皮侧致密沉积物为膜性肾病特点；B项系膜增生为系膜增生性肾炎；C项内皮细胞增生肥大见于急性增生性肾炎；D项壁层上皮细胞增生形成新月体为急进性肾炎"},{"q":"宫颈鳞状上皮化生提示","o":["急性宫颈炎","宫颈上皮萎缩","宫颈癌","慢性宫颈炎","宫颈上皮不典型增生"],"a":3,"e":"宫颈鳞状上皮化生是宫颈管柱状上皮在慢性炎症刺激下转化为鳞状上皮，是慢性宫颈炎的表现，属适应性改变。A项急性宫颈炎以中性粒细胞浸润为主；B项宫颈上皮萎缩见于雌激素水平下降；C项宫颈癌为恶性病变伴明显异型；E项不典型增生为癌前病变，细胞异型，与单纯化生不同"}];
